#[test]
#[serial]
fn a_duration_bound_makes_replay_produce_fewer_missing_messages() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 6);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("cap.mcap");
    write_bag(&rec, &bag, None);

    // Re-execute only the first 4 of the 6 recorded steps of BAG TIME → replay
    // produces 4 relay frames vs 6 recorded → MissingMessages { 6, 4 }.
    let outcome = replay(
        &bag,
        source_relay_factories,
        Some(duration_for_steps(4)),
        None,
    )
    .unwrap();
    assert_eq!(
        outcome.ticks_replayed, 4,
        "the bag-time bound caps the replayed steps"
    );
    assert!(!outcome.passed);
    let v = outcome
        .violations
        .iter()
        .find(|v| v.topic == "/sr/relay/out")
        .unwrap();
    match v.class {
        ViolationClass::MissingMessages { recorded, replayed } => {
            assert_eq!((recorded, replayed), (6, 4));
        }
        ref other => panic!("expected MissingMessages, got {other:?}"),
    }
    // Capping pin: the recorded fire sequence is capped to the replayed
    // steps, so a `--duration` truncation is a DATA violation (exit 1), NOT a
    // false structural divergence (the recorded fires past step 4 are excluded).
    assert!(
        outcome.trace_divergence.is_none(),
        "--duration truncation must not be reported as a trace divergence: {:?}",
        outcome.trace_divergence
    );
}

