// ===========================================================================
// 7. Sparse-trace / long-period invariant
// ===========================================================================

/// A long-period source: fires every 5th step (period 25 ms driven at 5 ms).
#[cerulion_node(period_ms = 25)]
#[derive(Default)]
struct SlowSourceNode {
    #[output]
    out: Vector3,
    counter: f64,
}

#[cerulion_node_impl]
impl SlowSourceNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.counter += 1.0;
        self.out.x = self.counter;
        Ok(())
    }
}

#[test]
#[serial]
fn sparse_fires_long_period_replays_every_boundary_byte_exact() {
    // The source fires every 25 ms; stepped at 5 ms → most steps produce NO
    // FIRE record, but EVERY step carries a STEP_BOUNDARY record. Replay runs
    // one step per boundary (silent steps advance the clock too — they are NOT
    // folded into the next fire-bearing step) and stays byte-exact.
    let yaml = "name: slow\nprefix: sl\nnodes:\n\
        \x20 - id: source\n    type: slow_source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n";
    let make = || factories(vec![("source", Box::new(SlowSourceNodeEntry::new()))]);

    let steps = 25; // 5 fires over 125 ms.
    let rec = record_uniform(yaml, make, &[], steps);
    let src = &rec.messages["/sl/source/out"];
    assert_eq!(
        src.len(),
        5,
        "a 25 ms period stepped at 5 ms fires 5× over 25 steps"
    );
    // FIRE records are sparse (one per fired step); boundaries are dense (one
    // per step, fired or silent).
    let fire_count = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_FIRE)
        .count();
    let boundary_count = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY)
        .count();
    assert_eq!(fire_count, 5, "sparse fires: one per fired step");
    assert_eq!(boundary_count, 25, "dense boundaries: one per step");

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("sparse.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, make, None, None).unwrap();
    assert!(
        outcome.passed,
        "sparse-fire replay must be byte-exact: {:?}",
        outcome.violations
    );
    // EVERY recorded step is replayed (silent boundaries included).
    assert_eq!(outcome.ticks_replayed, 25, "one replayed step per boundary");
    // Recorded oracle: exactly 5 sparse FIRE records at the recorded fire times
    // (25,50,…,125 ms). `outcome.passed` (a `None` trace_divergence) proves the
    // STREAMING check found the replay reproduced this schedule fire-for-fire —
    // node, step, level AND gating time — so the recorded side is the witness.
    let recorded_fire_times: Vec<u64> = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_FIRE)
        .map(|r| r.fire_time_ns)
        .collect();
    assert_eq!(recorded_fire_times.len(), 5);
    for (i, ft) in recorded_fire_times.iter().enumerate() {
        assert_eq!(
            *ft,
            (i as u64 + 1) * 25 * 1_000_000,
            "gating target retraced"
        );
    }
}

// ===========================================================================
// 8. Clock pin — replayed fire_time_ns EXACTLY equals recorded
// ===========================================================================

#[test]
#[serial]
fn replayed_fire_times_exactly_equal_recorded() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 6);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("clock.mcap");
    write_bag(&rec, &bag, None);

    let (outcome, fires) = replay_with_tap(&bag, source_relay_factories);
    let outcome = outcome.unwrap();
    assert!(outcome.passed, "violations: {:?}", outcome.violations);
    assert!(outcome.trace_divergence.is_none());
    // The recorded-clock re-advance contract, witnessed INDEPENDENTLY of the
    // comparator: the REPLAYED fire stream the engine fed the
    // divergence check — captured by the fire tap — must equal the bag's FIRE
    // records resolved by the TEST'S own resolver: same nodes, same steps,
    // same levels, same fire times, same ORDER.
    let oracle = resolved_fire_oracle(&rec);
    // Non-vacuous: the recording actually carries fires (2 nodes × 6 steps).
    assert_eq!(
        oracle.len(),
        2 * 6,
        "recorded oracle carries every fire the replay had to reproduce"
    );
    let (recorded_side, replayed_side) = tap_sides(&fires);
    assert_eq!(
        replayed_side, oracle,
        "replayed (node, step, level, fire_time) must equal recorded exactly, in order"
    );
    assert_eq!(recorded_side, oracle, "recorded side resolves identically");
}

// ===========================================================================
// 9. External injection (absolute source topic re-injected byte-exact)
// ===========================================================================

fn ext_graph_yaml() -> &'static str {
    "name: extg\nprefix: xr\nnodes:\n\
     \x20 - id: relay\n    type: relay_node\n    inputs:\n      - name: inp\n        source: /xr/ext/cam\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

/// The `relay` node's state as every arm in this file runs it.
///
/// ONE definition, because two of them exist: the entry the replay LOADS
/// (below) and the anchor a resume arm crafts ([`relay_anchor_blob`]). A
/// `#[cerulion_node]` declares real state, so an anchor whose
/// `addend` disagreed with the factory's would RESTORE the relay to a different
/// addend and byte-mismatch every frame it went on to publish — a divergence
/// against an unchanged graph, invented entirely by the fixture.
fn ext_relay_state() -> RelayNode {
    RelayNode {
        addend: 100.0,
        ..Default::default()
    }
}

fn ext_relay_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![(
        "relay",
        Box::new(RelayNodeEntry::with_state(ext_relay_state())),
    )])
}

#[test]
#[serial]
fn external_frames_are_reinjected_and_downstream_matches() {
    let steps = 5;
    let per_step: Vec<f64> = (0..steps).map(|k| (k * 10 + 1) as f64).collect(); // 1,11,21,31,41
    let externals = vec![ExternalDrive::singles("/xr/ext/cam", per_step.clone())];
    let rec = record_uniform(ext_graph_yaml(), ext_relay_factories, &externals, steps);

    // Anchor: relay.out.x == ext_value + 100.
    let rel = &rec.messages["/xr/relay/out"];
    assert_eq!(rel.len(), steps);
    for k in 0..steps {
        assert_eq!(
            frame_x(&rel[k]),
            per_step[k] + 100.0,
            "relay-from-external oracle"
        );
    }
    // The external channel was recorded byte-exact.
    assert_eq!(rec.messages["/xr/ext/cam"].len(), steps);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("external.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, ext_relay_factories, None, None).unwrap();
    assert!(
        outcome.passed,
        "external injection must reproduce downstream byte-exact: {:?}",
        outcome.violations
    );
    // /xr/relay/out is the only graph-produced topic; /xr/ext/cam is injected
    // (not diffed), so exactly one topic is checked.
    assert_eq!(outcome.topics_checked, 1);
    assert_eq!(outcome.topics_passed, 1);
}

// ===========================================================================
// 10. Env divergence (WARN-only, never exit-affecting)
// ===========================================================================

#[test]
#[serial]
fn env_divergence_is_warn_only_and_surfaced() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("env.mcap");

    // env.json: a plain (allowlist-style) var + a redacted (fnv64) var. Compute
    // the redacted hash for the value "secret".
    let secret_fnv = format!("{:016x}", cerulion_core::wire::fnv1a_hash(b"secret"));
    let env = serde_json::json!({
        "CER_REPLAY_PLAIN": "orig",
        "CER_REPLAY_HASHED": {"redacted": true, "fnv64": secret_fnv},
    });
    let env_bytes = serde_json::to_vec(&env).unwrap();
    write_bag(&rec, &bag, Some(&env_bytes));

    // Set the process env: the plain var CHANGED, the hashed var MATCHES.
    std::env::set_var("CER_REPLAY_PLAIN", "CHANGED");
    std::env::set_var("CER_REPLAY_HASHED", "secret");
    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    std::env::remove_var("CER_REPLAY_PLAIN");
    std::env::remove_var("CER_REPLAY_HASHED");

    // Data still passes — env divergence never fails the run.
    assert!(
        outcome.passed,
        "env divergence must not affect exit: {:?}",
        outcome.violations
    );
    // The plain var changed → surfaced; the hashed var matched → NOT surfaced.
    let names: Vec<&str> = outcome
        .env_divergence
        .iter()
        .map(|d| d.name.as_str())
        .collect();
    assert!(
        names.contains(&"CER_REPLAY_PLAIN"),
        "changed plain var surfaced: {names:?}"
    );
    assert!(
        !names.contains(&"CER_REPLAY_HASHED"),
        "matching hashed var must NOT surface"
    );
}

#[test]
#[serial]
fn env_redacted_hash_mismatch_is_surfaced() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 3);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("env_hash.mcap");
    let secret_fnv = format!("{:016x}", cerulion_core::wire::fnv1a_hash(b"secret"));
    let env = serde_json::json!({ "CER_REPLAY_HASHED2": {"redacted": true, "fnv64": secret_fnv} });
    write_bag(&rec, &bag, Some(&serde_json::to_vec(&env).unwrap()));

    std::env::set_var("CER_REPLAY_HASHED2", "different");
    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    std::env::remove_var("CER_REPLAY_HASHED2");

    assert!(outcome.passed);
    let d = outcome
        .env_divergence
        .iter()
        .find(|d| d.name == "CER_REPLAY_HASHED2")
        .expect("hash mismatch surfaced");
    assert!(
        matches!(d.kind, replay_engine::EnvDivergenceKind::HashChanged),
        "redacted value change is a HashChanged, got {:?}",
        d.kind
    );
}

