// 18. Defensive branches
// ===========================================================================

/// An external frame too short for a wire header (< 32 bytes) injects
/// UNCONDITIONALLY (it cannot be time-windowed) and must not strand later
/// frames behind it. Placed FIRST in file order: it is injected alongside the
/// first real frame; the data-trigger consumer reads the LATEST queued frame
/// (the real one), so downstream output still byte-matches → the run PASSES,
/// which simultaneously proves (a) no stranding (all later injections flowed —
/// a stuck cursor would starve the relay into MissingTopic) and (b) no
/// downstream corruption.
#[test]
#[serial]
fn tiny_unparseable_external_frame_injects_without_stranding() {
    let steps = 4;
    let per_step: Vec<f64> = (0..steps).map(|k| (k + 1) as f64).collect();
    let externals = vec![ExternalDrive::singles("/xr/ext/cam", per_step)];
    let mut rec = record_uniform(ext_graph_yaml(), ext_relay_factories, &externals, steps);
    // Prepend a 3-byte junk frame to the recorded external stream (external
    // topics are exempt from the graph-produced frame cross-checks).
    rec.messages
        .get_mut("/xr/ext/cam")
        .unwrap()
        .insert(0, vec![0xAA, 0xBB, 0xCC]);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("tiny_ext.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, ext_relay_factories, None, None).unwrap();
    assert!(
        outcome.passed,
        "the unparseable frame must inject-and-pass-through without stranding \
         the cursor or corrupting downstream: {:?}",
        outcome.violations
    );
}

/// `frame_first_diff`'s length-mismatch-with-matching-prefix branch: a recorded
/// frame EXTENDED with trailing bytes (prefix identical to the replayed frame)
/// reports its first divergence at exactly the COMMON length.
#[test]
#[serial]
fn extended_recorded_frame_reports_diff_at_common_length() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // Append 4 trailing bytes to the LAST source frame (56 → 60 bytes). The
    // wire header (total_size 56, timestamp) is untouched, so the cross-checks
    // pass; only the byte diff sees the tail.
    let frames = rec.messages.get_mut("/sr/source/out").unwrap();
    let last = frames.len() - 1;
    frames[last].extend_from_slice(&[0xEE; 4]);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("extended.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(!outcome.passed);
    let source_violations: Vec<_> = outcome
        .violations
        .iter()
        .filter(|v| v.topic == "/sr/source/out")
        .collect();
    assert_eq!(source_violations.len(), 1, "{:?}", outcome.violations);
    match source_violations[0].class {
        ViolationClass::ByteMismatch {
            index,
            first_diff_byte_offset,
            recorded_len,
            replayed_len,
        } => {
            assert_eq!(index, 3, "the extended frame is the last of 4");
            assert_eq!(
                first_diff_byte_offset, 56,
                "matching prefix → first diff at the common length"
            );
            assert_eq!((recorded_len, replayed_len), (60, 56));
        }
        ref other => panic!("expected ByteMismatch, got {other:?}"),
    }
}

