#[test]
#[serial]
fn env_missing_recorded_var_is_missing_divergence() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 3);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("env_missing.mcap");
    let env = serde_json::json!({ "CER_REPLAY_ABSENT_V": "recorded-value" });
    write_bag(&rec, &bag, Some(&serde_json::to_vec(&env).unwrap()));

    std::env::remove_var("CER_REPLAY_ABSENT_V"); // ensure absent
    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();

    assert!(outcome.passed, "env divergence is warn-only");
    let d = outcome
        .env_divergence
        .iter()
        .find(|d| d.name == "CER_REPLAY_ABSENT_V")
        .expect("missing var surfaced");
    assert!(
        matches!(d.kind, replay_engine::EnvDivergenceKind::Missing),
        "got {:?}",
        d.kind
    );
}

#[test]
#[serial]
fn env_names_only_null_var_absent_is_missing_divergence() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 3);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("env_null.mcap");
    // Names-only (null) entries: presence check only. One absent (surfaces as
    // Missing via the null branch), one present (must NOT surface — the
    // anti-tautology control proving the null arm checks presence, not value).
    let env = serde_json::json!({
        "CER_REPLAY_NULL_ABSENT": null,
        "CER_REPLAY_NULL_PRESENT": null,
    });
    write_bag(&rec, &bag, Some(&serde_json::to_vec(&env).unwrap()));

    std::env::remove_var("CER_REPLAY_NULL_ABSENT");
    std::env::set_var("CER_REPLAY_NULL_PRESENT", "any-value");
    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    std::env::remove_var("CER_REPLAY_NULL_PRESENT");

    assert!(outcome.passed, "env divergence is warn-only");
    let names: Vec<&str> = outcome
        .env_divergence
        .iter()
        .map(|d| d.name.as_str())
        .collect();
    assert!(
        names.contains(&"CER_REPLAY_NULL_ABSENT"),
        "absent names-only var surfaced: {names:?}"
    );
    assert!(
        !names.contains(&"CER_REPLAY_NULL_PRESENT"),
        "present names-only var must NOT surface: {names:?}"
    );
    let d = outcome
        .env_divergence
        .iter()
        .find(|d| d.name == "CER_REPLAY_NULL_ABSENT")
        .unwrap();
    assert!(matches!(d.kind, replay_engine::EnvDivergenceKind::Missing));
}

