/// The non-verdict fields of a synthetic failing outcome, so an arm can
/// state ONLY the counts it is about. Shared with the FAIL-path
/// verdict oracle; the shape is lifted verbatim from the arm below.
fn failing_outcome_skeleton() -> ReplayOutcome {
    ReplayOutcome {
        topics_checked: 0,
        topics_passed: 0,
        violations: Vec::new(),
        declined_frame_comparisons: Vec::new(),
        ros2_entries_skipped: Vec::new(),
        passed: false,
        node_failures: vec![],
        ticks_replayed: 7,
        trace_divergence: None,
        env_divergence: Vec::new(),
        recorder: None,
        record_health: RecordHealthReport::Absent,
        tolerated_ragged_tails: vec![],
        unmodelled_topics: vec![],
        resume: None,
        covered_range: None,
        read_log_divergence: None,
        read_log: replay_engine::ReadLogStatus::Inert,
        read_log_quarantine: Vec::new(),
        // A hand-built outcome for the verdict renderer: the
        // unstamped shape (no stamp ⇒ inferred lockstep).
        coordination: replay_engine::CoordinationReport {
            mode: replay_engine::CoordinationMode::Lockstep,
            inferred: true,
        },
        // The classes THIS hand-built outcome's own
        // findings fall into — the verdict renderer prints their phrases.
        divergence_classes: vec![replay_engine::DivergenceClass::FrameContent],
        injection_stand_downs: Vec::new(),
        injection_coverage: Vec::new(),
        rederivation_notes: Vec::new(),
        replay_input_shortfalls: Vec::new(),
        injection_anomalies: Vec::new(),
        rank_execution: Vec::new(),
        aborted: None,
        report_version: replay_engine::REPORT_VERSION,
    }
}

/// The FAIL summary's DECLINED suffix, by hand.
///
/// The mixed-regime arm asserts the suffix on the PASS line, because that bag's
/// verdict is clean — so the FAIL branch's copy of the same suffix is reached by
/// no other test at all.
/// This drives the FAIL branch directly: a synthetic outcome that FAILS
/// (one violation) AND declines two topics, one of which matched under the
/// fallback. The suffix is asserted as ONE literal string, because that is what an
/// operator reads.
#[test]
#[serial]
fn render_verdict_failing_branch_reports_declined_topics_in_its_summary() {
    use cerulion_cli_engine::replay_engine::{DeclinedFrameComparison, Violation};
    let withheld = Violation {
        topic: "/g/declined/out".to_string(),
        class: ViolationClass::MissingTopic,
        detail: "withheld-detail".to_string(),
    };
    let outcome = ReplayOutcome {
        topics_checked: 5,
        topics_passed: 2,
        violations: vec![Violation {
            topic: "/g/real/out".to_string(),
            class: ViolationClass::MissingTopic,
            detail: "a genuine violation on an un-steered topic".to_string(),
        }],
        declined_frame_comparisons: vec![
            DeclinedFrameComparison {
                topic: "/g/declined/out".to_string(),
                ranks: vec![1],
                code: "unresolved_producer".to_string(),
                reason: "a read cannot be attributed to a producer.".to_string(),
                matched_under_fallback: false,
                withheld: vec![withheld],
            },
            DeclinedFrameComparison {
                topic: "/g/matched/out".to_string(),
                ranks: vec![1],
                code: "unresolved_producer".to_string(),
                reason: "a read cannot be attributed to a producer.".to_string(),
                matched_under_fallback: true,
                withheld: Vec::new(),
            },
        ],
        ..failing_outcome_skeleton()
    };

    let s = replay_engine::render_verdict(&outcome, std::path::Path::new("/tmp/x.mcap"));
    assert!(
        s.contains(
            "2/5 topic(s) matched and were credited; 2 DECLINED (1 of them matched \
             under the fallback, not credited); 1 violation(s):"
        ),
        "the FAIL summary states credited, declined and matched-under-fallback as one \
         sentence: {s}"
    );
    // …and the per-row tail renders both outcomes distinctly, with no doubled period.
    assert!(
        s.contains(
            "[unresolved_producer]: 1 withheld divergence(s) — a read cannot be \
             attributed to a producer."
        ),
        "a withheld row names its count: {s}"
    );
    assert!(
        s.contains("MATCHED under the fallback (not credited)"),
        "a matched row says so rather than reporting 0 withheld: {s}"
    );
    assert!(!s.contains(".."), "no doubled period in the row tail: {s}");
}

#[test]
#[serial]
fn render_verdict_failing_branch_lists_all_classes_in_order() {
    use cerulion_cli_engine::replay_engine::{EnvDivergence, EnvDivergenceKind, Violation};
    // Hand-built outcome with ONE violation of EVERY class, in a chosen
    // (graph-definition) order, plus one env divergence.
    let violations = vec![
        Violation {
            topic: "/g/a/out".to_string(),
            class: ViolationClass::MissingTopic,
            detail: "detail-a".to_string(),
        },
        Violation {
            topic: "/g/b/out".to_string(),
            class: ViolationClass::ExtraTopic,
            detail: "detail-b".to_string(),
        },
        Violation {
            topic: "/g/c/out".to_string(),
            class: ViolationClass::MissingMessages {
                recorded: 6,
                replayed: 4,
            },
            detail: "detail-c".to_string(),
        },
        Violation {
            topic: "/g/d/out".to_string(),
            class: ViolationClass::ExtraMessages {
                recorded: 4,
                replayed: 6,
            },
            detail: "detail-d".to_string(),
        },
        Violation {
            topic: "/g/e/out".to_string(),
            class: ViolationClass::ByteMismatch {
                index: 2,
                first_diff_byte_offset: 32,
                recorded_len: 56,
                replayed_len: 56,
            },
            detail: "detail-e".to_string(),
        },
    ];
    let outcome = ReplayOutcome {
        ros2_entries_skipped: Vec::new(),
        passed: false,
        node_failures: vec![],
        ticks_replayed: 7,
        topics_checked: 6,
        topics_passed: 1,
        violations,
        trace_divergence: None,
        env_divergence: vec![EnvDivergence {
            name: "SOME_VAR".to_string(),
            kind: EnvDivergenceKind::ValueChanged,
            detail: "variable 'SOME_VAR' value changed since recording".to_string(),
        }],
        recorder: None,
        record_health: RecordHealthReport::Absent,
        tolerated_ragged_tails: vec![],
        unmodelled_topics: vec![],
        resume: None,
        covered_range: None,
        read_log_divergence: None,
        read_log: replay_engine::ReadLogStatus::Inert,
        read_log_quarantine: Vec::new(),
        // A hand-built outcome for the verdict renderer: the
        // unstamped shape (no stamp ⇒ inferred lockstep).
        coordination: replay_engine::CoordinationReport {
            mode: replay_engine::CoordinationMode::Lockstep,
            inferred: true,
        },
        // The classes THIS hand-built outcome's own
        // findings fall into — the verdict renderer prints their phrases.
        divergence_classes: vec![replay_engine::DivergenceClass::FrameContent],
        injection_stand_downs: Vec::new(),
        declined_frame_comparisons: Vec::new(),
        injection_coverage: Vec::new(),
        rederivation_notes: Vec::new(),
        replay_input_shortfalls: Vec::new(),
        injection_anomalies: Vec::new(),
        rank_execution: Vec::new(),
        aborted: None,
        report_version: replay_engine::REPORT_VERSION,
    };

    let s = replay_engine::render_verdict(&outcome, std::path::Path::new("/tmp/x.mcap"));

    // Header + env warning + footer (hand-written expected lines).
    assert!(
        s.contains("FRAME-CONTENT DIVERGENCE: /tmp/x.mcap"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains("WARNING: env divergence: variable 'SOME_VAR' value changed since recording"),
        "verdict:\n{s}"
    );
    // The line says what its numbers MEAN. A line printing
    // `topics_passed/topics_checked` as "matched" would under-report once a
    // declined-but-matched topic exists — such a topic matched and is deliberately
    // absent from `topics_passed`. This outcome declines nothing, so the suffix is
    // empty and the rest of the line is unchanged.
    assert!(
        s.contains("7 tick(s) replayed; 1/6 topic(s) matched and were credited; 5 violation(s):"),
        "verdict:\n{s}"
    );
    assert!(s.contains("  Topics passed: 1/6"), "verdict:\n{s}");

    // One line per violation, each carrying its class label + detail, exact.
    let expected_lines = [
        "  - /g/a/out [missing-topic]: detail-a",
        "  - /g/b/out [extra-topic]: detail-b",
        "  - /g/c/out [missing-messages]: detail-c",
        "  - /g/d/out [extra-messages]: detail-d",
        "  - /g/e/out [byte-mismatch]: detail-e",
    ];
    let mut prev_pos = 0usize;
    for line in &expected_lines {
        let pos = s
            .find(line)
            .unwrap_or_else(|| panic!("missing verdict line {line:?} in:\n{s}"));
        assert!(
            pos > prev_pos,
            "violation lines must render in graph-definition (vec) order; \
             {line:?} out of order in:\n{s}"
        );
        prev_pos = pos;
    }
}

/// The per-topic frame-MONOTONICITY killer. Two recorded frames
/// on a graph-produced topic are SWAPPED — both timestamps remain valid
/// boundary-set members (so the membership check passes) and only the
/// non-decreasing check can fire. Deleting the monotonicity branch turns this
/// bag into a spurious byte-mismatch data violation instead of the loud
/// corruption error.
#[test]
#[serial]
fn swapped_frames_violate_monotonicity_recording_inconsistent_exit_2() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // Frames stamped 5/10/15/20 ms; swap indices 1 and 2 → 5, 15, 10, 20 (all
    // still IN the boundary set — only the order is corrupt).
    rec.messages.get_mut("/sr/source/out").unwrap().swap(1, 2);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("swapped.mcap");
    write_bag(&rec, &bag, None);

    let err = replay(&bag, source_relay_factories, None, None).unwrap_err();
    match &err {
        ReplayError::RecordingInconsistent { detail } => {
            // Hand-written values (frame 2 = 10 ms after 15 ms), spanning the
            // literal's wrap points ("ns, \ BEFORE" and "are \ written").
            assert!(
                detail.contains(
                    "is stamped 10000000 ns, BEFORE the preceding frame's 15000000 ns — \
                     recorded frames are written in arrival order on one clock"
                ),
                "got detail: {detail}"
            );
        }
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
}

/// A PRODUCED-topic frame too short for a wire header hits the
/// "no parseable wire header" cross-check arm (graph publishers always stamp a
/// 32-byte header, so this is corruption — unlike the EXTERNAL tiny-frame
/// exemption pinned by `tiny_unparseable_external_frame_injects_without_stranding`).
#[test]
#[serial]
fn unparseable_produced_frame_is_recording_inconsistent_exit_2() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 3);
    rec.messages
        .get_mut("/sr/source/out")
        .unwrap()
        .push(vec![0xAA, 0xBB, 0xCC]);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("tiny_produced.mcap");
    write_bag(&rec, &bag, None);

    let err = replay(&bag, source_relay_factories, None, None).unwrap_err();
    match &err {
        ReplayError::RecordingInconsistent { detail } => {
            // Spans the literal's wrap point ("wire \ header").
            assert!(
                detail.contains("has no parseable wire header (3 bytes)")
                    && detail.contains("frame 3"),
                "got detail: {detail}"
            );
        }
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
}

/// A FIRE record at a step index BEYOND the last boundary hits
/// the "carries no STEP_BOUNDARY for that step" cross-check arm (every fire
