// ===========================================================================
// 19. Structural trace divergence (exit 6)
//
// The scheduler-level detector: after the replay loop, the RECORDED fire
// schedule (bag FIRE records, resolved through the manifest node-id table) is
// compared against the REPLAYED fire schedule in canonical (step, global_level,
// rank, seq) order. A mismatch is `trace_divergence: Some` (the CLI maps it to
// exit 6). Distinct from a data-payload violation (exit 1) — a diverged
// schedule takes exit precedence and is reported ALONGSIDE any data drift.
//
// The source→relay fixture fires TWO nodes per step: source (level 0) then
// relay (level 1). So an N-step recording's canonical fire sequence is
// [s0,r0, s1,r1, …] where sK=source@(step K, level 0), rK=relay@(step K,
// level 1); the manifest node-id table is ["source","relay"]. Each test PERTURBS
// the recorded trace (never the frames, unless it is the precedence arm) so the
// divergence is a pure STRUCTURAL one anchored to a hand-computed position.
// ===========================================================================

/// The trace-Vec index of the FIRE record for `node_id` at `step` (panics if
/// absent) — the perturbation anchor for the schedule-divergence tests.
fn fire_index_at(rec: &Recording, node_id: &str, step: u64) -> usize {
    let idx = rec
        .node_ids
        .iter()
        .position(|n| n == node_id)
        .unwrap_or_else(|| panic!("node id {node_id} not in manifest")) as u32;
    rec.trace
        .iter()
        .position(|r| r.record_type == RECORD_TYPE_FIRE && r.step == step && r.node_idx == idx)
        .unwrap_or_else(|| panic!("no FIRE record for {node_id}@step{step}"))
}

/// Test 2 — a REMOVED fire (StepBoundary + frames kept) makes the replay
/// OVER-fire relative to the thinned record. The data diff PASSES (every frame
/// is present); the divergence is purely structural (exit 6), naming the
/// replayed-extra node at the exact shifted position.
#[test]
#[serial]
fn removed_fire_is_over_fire_trace_divergence_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let i = fire_index_at(&rec, "relay", 1);
    rec.trace.remove(i);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("removed_fire.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(
        outcome.violations.is_empty(),
        "removing a trace fire (not frames) must not create a data violation: {:?}",
        outcome.violations
    );
    assert!(!outcome.passed, "a trace divergence fails the overall run");
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("the thinned schedule must diverge (exit 6)");
    // [s0,r0,s1] match; recorded pos 3 is source@(step2,level0) while replay
    // produced relay@(step1,level1) — the removed fire shifts the record by one.
    assert_eq!(td.position, 3, "divergence position");
    let rec_t = td.recorded.as_ref().expect("recorded fire present");
    let rep_t = td.replayed.as_ref().expect("replayed fire present");
    assert_eq!(
        (rec_t.node_id.as_str(), rec_t.step, rec_t.global_level),
        ("source", 2, 0)
    );
    assert_eq!(
        (rep_t.node_id.as_str(), rep_t.step, rep_t.global_level),
        ("relay", 1, 1)
    );
    assert!(
        td.detail.contains("source") && td.detail.contains("relay"),
        "detail names both nodes: {}",
        td.detail
    );
    // Whitespace guard on a REAL production detail string (double-space-free).
    assert!(
        !td.detail.contains("  "),
        "TraceDivergence detail has embedded whitespace runs: {:?}",
        td.detail
    );
}

/// Test 3 — an INJECTED extra fire at the tail makes the replay UNDER-fire
/// (the recording has a fire replay never produced). Length mismatch at the
/// boundary position: recorded present, replayed `None`.
#[test]
#[serial]
fn injected_tail_fire_is_under_fire_trace_divergence_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // Append an identical copy of the last relay fire (step 3, level 1) — order
    // stays non-decreasing and its time == the step-3 boundary, so every
    // consistency check passes; only the length differs from replay.
    let last_relay = rec.trace[fire_index_at(&rec, "relay", 3)];
    rec.trace.push(last_relay);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("injected_fire.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(
        outcome.violations.is_empty(),
        "injecting a trace fire (not frames) must not create a data violation: {:?}",
        outcome.violations
    );
    assert!(!outcome.passed);
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("the padded schedule must diverge (exit 6)");
    // 8 replayed fires; 9 recorded — the common prefix matches, the divergence
    // is the tail at position 8 (recorded relay@(step3,level1), replay none).
    assert_eq!(td.position, 8);
    let rec_t = td.recorded.as_ref().expect("recorded tail fire present");
    assert_eq!(
        (rec_t.node_id.as_str(), rec_t.step, rec_t.global_level),
        ("relay", 3, 1)
    );
    assert!(
        td.replayed.is_none(),
        "replay under-fired: no fire at the tail position"
    );
    assert!(
        td.detail.contains("UNDER-fired"),
        "detail names the under-fire direction: {}",
        td.detail
    );
    assert!(!td.detail.contains("  "), "detail: {:?}", td.detail);
}

/// Test 4 — a same-step LEVEL SWAP (level 1 emitted before level 0) is
/// out-of-canonical-order RECORDING CORRUPTION (exit 2 via the fire-order
/// pre-check), NOT a schedule divergence (exit 6). The boundary between the two
/// classes.
#[test]
#[serial]
fn swapped_same_step_levels_is_recording_inconsistent_exit_2() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let si = fire_index_at(&rec, "source", 1);
    let ri = fire_index_at(&rec, "relay", 1);
    rec.trace.swap(si, ri);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("level_swap.mcap");
    write_bag(&rec, &bag, None);

    let err = replay(&bag, source_relay_factories, None, None).unwrap_err();
    match &err {
        ReplayError::RecordingInconsistent { detail } => {
            // Hand-written coordinates spanning the literal's wrap point
            // ("the \ preceding" / "be \ non-decreasing").
            assert!(
                detail.contains("is a FIRE at (step 1, level 0)")
                    && detail.contains("the preceding FIRE was at (step 1, level 1)")
                    && detail.contains("non-decreasing in (step, level) write order"),
                "got detail: {detail}"
            );
        }
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
    // Whitespace guard: the RecordingInconsistent Display over the new detail.
    assert!(
        !err.to_string().contains("  "),
        "fire-order RecordingInconsistent Display has whitespace runs: {err}"
    );
}

/// Test 5 — SWAPPED node identities at one step (same step/level/time, node ids
/// permuted): the schedule SHAPE is unchanged so the (step, level) order
/// pre-check passes, but the node IDENTITY diverges from replay (exit 6),
/// naming both node ids.
#[test]
#[serial]
fn swapped_node_ids_at_one_step_is_trace_divergence_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let si = fire_index_at(&rec, "source", 1);
    let ri = fire_index_at(&rec, "relay", 1);
    let (sidx, ridx) = (rec.trace[si].node_idx, rec.trace[ri].node_idx);
    rec.trace[si].node_idx = ridx;
    rec.trace[ri].node_idx = sidx;

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("node_swap.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(
        outcome.violations.is_empty(),
        "frames unchanged → no data violation: {:?}",
        outcome.violations
    );
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("permuted node identities must diverge (exit 6)");
    // Position 2 is the step-1 level-0 fire: recorded now 'relay', replay 'source'.
    assert_eq!(td.position, 2);
    let rec_t = td.recorded.as_ref().unwrap();
    let rep_t = td.replayed.as_ref().unwrap();
    assert_eq!(rec_t.node_id, "relay");
    assert_eq!(rep_t.node_id, "source");
    assert_eq!((rec_t.step, rec_t.global_level), (1, 0));
    assert_eq!((rep_t.step, rep_t.global_level), (1, 0));
    assert!(
        td.detail.contains("'relay'") && td.detail.contains("'source'"),
        "detail names both node ids: {}",
        td.detail
    );
}

/// Test 6 — a tampered GLOBAL_LEVEL (order kept non-decreasing) diverges on the
/// level field alone (exit 6).
#[test]
#[serial]
fn tampered_global_level_is_trace_divergence_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // Bump the step-2 relay fire's level 1 → 5: (2,0) <= (2,5) <= (3,0) stays
    // non-decreasing (passes the order pre-check); replay produces it at level 1.
    let ri = fire_index_at(&rec, "relay", 2);
    rec.trace[ri].global_level = 5;

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("level_tamper.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(outcome.violations.is_empty(), "frames unchanged");
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("a wrong global_level must diverge (exit 6)");
    // r2 is fire index 5 in [s0,r0,s1,r1,s2,r2,…].
    assert_eq!(td.position, 5);
    let rec_t = td.recorded.as_ref().unwrap();
    let rep_t = td.replayed.as_ref().unwrap();
    assert_eq!(
        (rec_t.node_id.as_str(), rec_t.step, rec_t.global_level),
        ("relay", 2, 5)
    );
    assert_eq!(
        (rep_t.node_id.as_str(), rep_t.step, rep_t.global_level),
        ("relay", 2, 1)
    );
    assert!(
        td.detail.contains("level 5") && td.detail.contains("level 1"),
        "detail names both levels: {}",
        td.detail
    );
}

/// Test 7 — a tampered FIRE_TIME_NS (nudged 1 ns below its step boundary, so the
/// fire<=boundary consistency check still passes) diverges on the clock field
/// alone (exit 6), step/level/node all matching.
#[test]
#[serial]
fn tampered_fire_time_is_trace_divergence_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let si = fire_index_at(&rec, "source", 2);
    let original = rec.trace[si].fire_time_ns;
    assert!(original > 0, "step-2 fire time is non-zero");
    rec.trace[si].fire_time_ns = original - 1;

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("time_tamper.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(outcome.violations.is_empty(), "frames unchanged");
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("a wrong fire_time must diverge (exit 6)");
    // s2 is fire index 4 in [s0,r0,s1,r1,s2,…].
    assert_eq!(td.position, 4);
    let rec_t = td.recorded.as_ref().unwrap();
    let rep_t = td.replayed.as_ref().unwrap();
    assert_eq!(
        (rec_t.node_id.as_str(), rec_t.step, rec_t.global_level),
        ("source", 2, 0)
    );
    assert_eq!(
        (rep_t.node_id.as_str(), rep_t.step, rep_t.global_level),
        ("source", 2, 0)
    );
    assert_eq!(
        rec_t.fire_time_ns + 1,
        rep_t.fire_time_ns,
        "recorded time is exactly 1 ns below what replay reproduces"
    );
}

/// Test 8 — a bag with BOTH a payload flip (data) AND a removed fire
/// (structural): the OUTCOME records both failure classes and the verdict
/// renders BOTH sections. The 6-over-1 exit PRECEDENCE itself is pinned at the
/// process-exit layer by the subprocess CLI arm
/// (`subprocess_replay_with_both_divergence_classes_exits_6_and_renders_both`
/// in `cerulion_cli/tests/replay_cli_test.rs`) — this engine-level test pins
/// the outcome/verdict halves that arm builds on.
#[test]
#[serial]
fn both_data_and_structural_divergence_are_both_recorded_and_rendered() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // (a) data violation: flip a payload byte of relay frame 2.
    rec.messages.get_mut("/sr/relay/out").unwrap()[2][WireHeader::SIZE] ^= 0xFF;
    // (b) structural divergence: remove the step-1 relay fire (frames intact).
    let i = fire_index_at(&rec, "relay", 1);
    rec.trace.remove(i);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("both.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(
        outcome.trace_divergence.is_some(),
        "the structural divergence is recorded"
    );
    assert!(
        outcome
            .violations
            .iter()
            .any(|v| matches!(v.class, ViolationClass::ByteMismatch { .. })),
        "the data violation is ALSO recorded: {:?}",
        outcome.violations
    );
    assert!(!outcome.passed);
    // The verdict renders BOTH the trace-divergence and the data-regression
    // sections (the fuller report).
    let verdict = replay_engine::render_verdict(&outcome, std::path::Path::new("/tmp/x.mcap"));
    assert!(
        verdict.contains("FIRE-SCHEDULE DIVERGENCE"),
        "verdict:\n{verdict}"
    );
    assert!(
        verdict.contains("FRAME-CONTENT DIVERGENCE"),
        "verdict:\n{verdict}"
    );
    assert!(verdict.contains("byte-mismatch"), "verdict:\n{verdict}");
}

/// Test 9 — the divergence report is byte-identical across two replays of the
/// same perturbed bag (determinism; the report is serialized in the outcome).
#[test]
#[serial]
fn trace_divergence_report_is_deterministic_across_replays() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 5);
    let i = fire_index_at(&rec, "relay", 2);
    rec.trace.remove(i);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("determinism_div.mcap");
    write_bag(&rec, &bag, None);

    let a = replay(&bag, source_relay_factories, None, None).unwrap();
    let b = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(a.trace_divergence.is_some());
    let ja = serde_json::to_string(&a.trace_divergence).unwrap();
    let jb = serde_json::to_string(&b.trace_divergence).unwrap();
    assert_eq!(
        ja, jb,
        "the divergence report must be byte-identical across replays"
    );
    // Whole-outcome determinism too (trace_divergence is serialized in the JSON).
    assert_eq!(
        serde_json::to_string(&a).unwrap(),
        serde_json::to_string(&b).unwrap(),
        "the full outcome JSON must be byte-identical across replays"
    );
}

/// Test 10 — verdict rendering: a hand-built outcome with a `trace_divergence`
/// renders the exact `FIRE-SCHEDULE DIVERGENCE` section lines (and no `REPLAY
/// REGRESSION` block when there are no data violations).
#[test]
#[serial]
fn render_verdict_trace_divergence_section_exact_lines() {
    use cerulion_cli_engine::replay_engine::{FireTuple, TraceContextRow, TraceDivergenceReport};

    // `rank: None` — the single-rank shape: the rendered lines below
    // are asserted EXACTLY, pinning that a `None` rank adds nothing.
    let recorded = FireTuple {
        step: 2,
        global_level: 0,
        node_id: "source".to_string(),
        fire_time_ns: 15_000_000,
        rank: None,
    };
    let replayed = FireTuple {
        step: 1,
        global_level: 1,
        node_id: "relay".to_string(),
        fire_time_ns: 5_000_000,
        rank: None,
    };
    let prior = FireTuple {
        step: 1,
        global_level: 0,
        node_id: "source".to_string(),
        fire_time_ns: 10_000_000,
        rank: None,
    };
    let report = TraceDivergenceReport {
        position: 3,
        detail: "the replayed schedule diverged from the recording at fire 3: recorded step 2 \
                 level 0 node 'source' @ 15000000 ns but replay produced step 1 level 1 node \
                 'relay' @ 5000000 ns"
            .to_string(),
        recorded: Some(recorded.clone()),
        replayed: Some(replayed.clone()),
        context: vec![
            TraceContextRow {
                position: 2,
                recorded: Some(prior.clone()),
                replayed: Some(prior),
            },
            TraceContextRow {
                position: 3,
                recorded: Some(recorded),
                replayed: Some(replayed),
            },
        ],
    };
    let outcome = ReplayOutcome {
        ros2_entries_skipped: Vec::new(),
        passed: false,
        node_failures: vec![],
        ticks_replayed: 5,
        topics_checked: 2,
        topics_passed: 2,
        violations: vec![],
        trace_divergence: Some(report),
        env_divergence: vec![],
        recorder: None,
        record_health: RecordHealthReport::Absent,
        tolerated_ragged_tails: vec![],
        unmodelled_topics: vec![],
        resume: None,
        covered_range: None,
        read_log_divergence: None,
        read_log: replay_engine::ReadLogStatus::Inert,
        read_log_quarantine: Vec::new(),
        // A hand-built outcome for the verdict renderer: the
        // unstamped shape (no stamp ⇒ inferred lockstep).
        coordination: replay_engine::CoordinationReport {
            mode: replay_engine::CoordinationMode::Lockstep,
            inferred: true,
        },
        // The classes THIS hand-built outcome's own
        // findings fall into — the verdict renderer prints their phrases.
        divergence_classes: vec![replay_engine::DivergenceClass::FireSchedule],
        injection_stand_downs: Vec::new(),
        declined_frame_comparisons: Vec::new(),
        injection_coverage: Vec::new(),
        rederivation_notes: Vec::new(),
        replay_input_shortfalls: Vec::new(),
        injection_anomalies: Vec::new(),
        rank_execution: Vec::new(),
        aborted: None,
        report_version: replay_engine::REPORT_VERSION,
    };

    let s = replay_engine::render_verdict(&outcome, std::path::Path::new("/tmp/x.mcap"));
    assert!(
        s.contains("FIRE-SCHEDULE DIVERGENCE: /tmp/x.mcap"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains(
            "5 tick(s) replayed; the replayed schedule diverged from the recording at fire 3:"
        ),
        "verdict:\n{s}"
    );
    assert!(
        s.contains("  recorded: step 2 level 0 node 'source' @ 15000000 ns"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains("  replayed: step 1 level 1 node 'relay' @ 5000000 ns"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains("context (recorded | replayed):"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains(">> [3]"),
        "the divergence context row is marked: {s}"
    );
    // No data violations → no FRAME-CONTENT DIVERGENCE block.
    assert!(!s.contains("FRAME-CONTENT DIVERGENCE"), "verdict:\n{s}");
}

/// **The NON-POSITIONAL twin of the arm above** — a free-run mint, where the
/// comparator has no fire ordinal to name.
///
/// A trace-driven pass makes no positional compare, so its divergence reports
/// carry `position: 0` and BOTH sides `None`. Rendering the positional header
/// over one said "diverged at fire 0" — an affirmatively WRONG claim about
/// WHERE — and then printed `recorded: <none>` / `replayed: <none>`, two lines
/// carrying no information.
///
/// Asserted as EXACT LINES in both directions: the positional phrasing and the
/// two side lines must be ABSENT, and the non-positional phrasing plus the
/// detail sentence must be PRESENT. Without the second half a renderer that
/// printed nothing at all would pass.
///
/// Re-keying `positional` on `td.position != 0` puts this report on
/// the positional branch (its position IS 0, so that change flips the arm the
/// other way round only for a NON-ZERO position — which is why the sibling arm
/// above, whose position is 3 and whose sides are `Some`, is the other half of
/// the pair: between them the flag is pinned on both inputs).
#[test]
fn render_verdict_trace_divergence_non_positional_exact_lines() {
    use cerulion_cli_engine::replay_engine::{FireTuple, TraceDivergenceReport};

    let report = TraceDivergenceReport {
        position: 0,
        detail: "FIRE-SCHEDULE DIVERGENCE: rank 1 step 4 — the recording holds fire(s) for \
                 node(s) [relay] that this re-execution did not perform"
            .to_string(),
        recorded: None,
        replayed: None,
        context: Vec::new(),
    };
    let outcome = ReplayOutcome {
        ros2_entries_skipped: Vec::new(),
        passed: false,
        node_failures: vec![],
        ticks_replayed: 5,
        topics_checked: 2,
        topics_passed: 2,
        violations: vec![],
        trace_divergence: Some(report),
        env_divergence: vec![],
        recorder: None,
        record_health: RecordHealthReport::Absent,
        tolerated_ragged_tails: vec![],
        unmodelled_topics: vec![],
        resume: None,
        covered_range: None,
        read_log_divergence: None,
        read_log: replay_engine::ReadLogStatus::Inert,
        read_log_quarantine: Vec::new(),
        coordination: replay_engine::CoordinationReport {
            mode: replay_engine::CoordinationMode::FreeRun,
            inferred: false,
        },
        divergence_classes: vec![replay_engine::DivergenceClass::FireSchedule],
        injection_stand_downs: Vec::new(),
        declined_frame_comparisons: Vec::new(),
        injection_coverage: Vec::new(),
        rederivation_notes: Vec::new(),
        replay_input_shortfalls: Vec::new(),
        injection_anomalies: Vec::new(),
        rank_execution: Vec::new(),
        aborted: None,
        report_version: replay_engine::REPORT_VERSION,
    };

    let s = replay_engine::render_verdict(&outcome, std::path::Path::new("/tmp/x.mcap"));
    assert!(
        s.contains("FIRE-SCHEDULE DIVERGENCE: /tmp/x.mcap"),
        "verdict:\n{s}"
    );
    // PRESENT: the non-positional phrasing and the detail sentence.
    assert!(
        s.contains("5 tick(s) replayed; the replayed schedule diverged from the recording:"),
        "verdict:\n{s}"
    );
    assert!(
        s.contains("the recording holds fire(s) for node(s) [relay]"),
        "verdict:\n{s}"
    );
    // ABSENT: the WHERE claim and the two empty side lines.
    assert!(
        !s.contains("at fire"),
        "no fire ordinal may be claimed:\n{s}"
    );
    assert!(!s.contains("recorded: "), "no empty recorded line:\n{s}");
    assert!(!s.contains("replayed: "), "no empty replayed line:\n{s}");
    assert!(!s.contains("<none>"), "verdict:\n{s}");
    assert!(
        !s.contains("context (recorded | replayed):"),
        "an empty context renders no header:\n{s}"
    );

    // THE DISCRIMINATOR, and without it this pair pins nothing. Both arms so
    // far have `position != 0` together with `Some` sides, or `position == 0`
    // together with `None` sides — so a renderer keyed on the POSITION instead
    // of on the sides agrees with both. The shape that separates them is a real
    // one: a POSITIONAL compare that diverges at the very FIRST fire has
    // position 0 AND two real sides, and it must still render positionally.
    //
    // Changing `let positional = td.position != 0;` renders this
    // non-positionally — dropping the WHERE claim and both side lines from a
    // report that has them — and fails exactly here.
    let first_fire = FireTuple {
        step: 0,
        global_level: 0,
        node_id: "source".to_string(),
        fire_time_ns: 1,
        rank: None,
    };
    let at_zero = ReplayOutcome {
        trace_divergence: Some(TraceDivergenceReport {
            position: 0,
            detail: "diverged at the first fire".to_string(),
            recorded: Some(first_fire.clone()),
            replayed: None,
            context: Vec::new(),
        }),
        ..outcome
    };
    let s = replay_engine::render_verdict(&at_zero, std::path::Path::new("/tmp/x.mcap"));
    assert!(
        s.contains("diverged from the recording at fire 0:"),
        "a positional compare that diverges at fire 0 still names WHERE:\n{s}"
    );
    assert!(
        s.contains("  recorded: step 0 level 0 node 'source' @ 1 ns"),
        "…and still renders both sides:\n{s}"
    );
    assert!(s.contains("  replayed: <none>"), "verdict:\n{s}");
}

/// **The `--report` JSON's `rederivation_notes` vocabulary is a CLOSED set with
/// a fixed spelling, and `code` is ABSENT when a note has none.**
///
/// `kind` was a `String` a producer could typo; it is an enum whose serde output
/// must stay `snake_case`, because every reader of a shipped report matches on
/// those two literals. `code` is additive and skipped when `None`, which is what
/// keeps a pre-existing report byte-identical.
#[test]
fn rederivation_note_serde_spelling_is_pinned() {
    let conservation = replay_engine::RederivationNote {
        rank: 1,
        kind: replay_engine::RederivationNoteKind::Conservation,
        subject: "/t".to_string(),
        detail: "d".to_string(),
        code: None,
    };
    let json = serde_json::to_value(&conservation).unwrap();
    assert_eq!(json["kind"], "conservation");
    assert!(
        json.get("code").is_none(),
        "an absent code is SKIPPED, never serialized as null: {json}"
    );

    let stand_down = replay_engine::RederivationNote {
        kind: replay_engine::RederivationNoteKind::StandDown,
        code: Some("verifier_declined_schedule_budget".to_string()),
        ..conservation.clone()
    };
    let json = serde_json::to_value(&stand_down).unwrap();
    assert_eq!(json["kind"], "stand_down");
    assert_eq!(json["code"], "verifier_declined_schedule_budget");

    // There is a THIRD kind. It is additive on the wire —
    // a new string inside an existing array, so no top-level key moves — and
    // its spelling is pinned here beside the other two, because a reader that
    // matches on the two literals must be able to tell the third apart rather
    // than fall into whichever arm it wrote last.
    let census = replay_engine::RederivationNote {
        kind: replay_engine::RederivationNoteKind::ReadSiteCensus,
        ..conservation
    };
    let json = serde_json::to_value(&census).unwrap();
    assert_eq!(json["kind"], "read_site_census");
    assert!(
        json.get("code").is_none(),
        "a census is addressed by `subject` and carries no enum-valued cause, so \
         it mints no token: {json}"
    );

    // A FOURTH kind — the record-time producer-label
    // reading. Same argument as the third: additive on the wire, and a reader
    // matching on the existing literals must be able to tell it apart rather
    // than fall into whichever arm it wrote last. It DOES carry a code (the
    // severity token a CI job keys on), which is what distinguishes it from
    // the census.
    let labels = replay_engine::RederivationNote {
        kind: replay_engine::RederivationNoteKind::ProducerLabels,
        code: Some("producer_labels_malformed".to_string()),
        ..census
    };
    let json = serde_json::to_value(&labels).unwrap();
    assert_eq!(json["kind"], "producer_labels");
    assert_eq!(json["code"], "producer_labels_malformed");

    // There is NO `intra_step_injection` kind. The intra-step
    // injection seam has no report-only voice:
    // its counters are a verdict gate (a
    // non-zero counter refuses the pass at exit 5, naming the counter), so no
    // report can carry the kind and it is not kept as dead vocabulary. The
    // spelling is pinned ABSENT so it cannot quietly appear as a fifth.
    assert!(
        !serde_json::to_string(&labels)
            .unwrap()
            .contains("intra_step_injection"),
        "no note kind spells a seam token"
    );

    // The verify_sync redesign added the FIFTH surviving kind: a
    // Sync node judged on WIDENED alignment evidence because a non-trigger
    // input can silently re-offer a fired head. Like the census it carries NO
    // code (the decision: the note is a disclosure about the judging basis, not
    // a fault with an enum-valued cause), which the assertion pins so a later
    // "helpful" token cannot slip in unnoticed.
    let carried = replay_engine::RederivationNote {
        kind: replay_engine::RederivationNoteKind::CarriedHeads,
        code: None,
        ..labels
    };
    let json = serde_json::to_value(&carried).unwrap();
    assert_eq!(json["kind"], "carried_heads");
    assert!(
        json.get("code").is_none(),
        "a carried-heads disclosure mints no token: {json}"
    );

    // …and the five spellings are DISTINCT, which a per-variant assertion
    // above cannot see (two variants renamed to one string would satisfy both).
    let all = [
        replay_engine::RederivationNoteKind::StandDown,
        replay_engine::RederivationNoteKind::Conservation,
        replay_engine::RederivationNoteKind::ReadSiteCensus,
        replay_engine::RederivationNoteKind::ProducerLabels,
        replay_engine::RederivationNoteKind::CarriedHeads,
    ];
    let kinds: std::collections::BTreeSet<String> = all
        .iter()
        .map(|k| {
            serde_json::to_value(k)
                .unwrap()
                .as_str()
                .unwrap()
                .to_string()
        })
        .collect();
    assert_eq!(kinds.len(), 5, "every note kind has its own wire spelling");
    // The list above is TOTAL — an EXHAUSTIVE match over the
    // enum, with no wildcard, so adding a sixth kind (or deleting one) fails
    // to COMPILE here rather than leaving the spelling walk one short.
    for k in &all {
        let _spelled: &str = match k {
            replay_engine::RederivationNoteKind::StandDown => "stand_down",
            replay_engine::RederivationNoteKind::Conservation => "conservation",
            replay_engine::RederivationNoteKind::ReadSiteCensus => "read_site_census",
            replay_engine::RederivationNoteKind::ProducerLabels => "producer_labels",
            replay_engine::RederivationNoteKind::CarriedHeads => "carried_heads",
        };
        assert_eq!(serde_json::to_value(k).unwrap(), _spelled);
    }
}

/// The OVER-fire TAIL branch of the comparison (replayed
/// strictly longer, common prefix fully matching): remove the TRAILING recorded
/// fire. Unlike `removed_fire_is_over_fire_trace_divergence_exit_6` (a
/// mid-sequence removal, which diverges on a FIELD mismatch at the shift
/// point), a tail removal leaves every compared position equal and exercises
/// the length-mismatch arm where REPLAY has the extra fire: recorded `None`,
/// replayed present, the OVER-fired detail phrase.
#[test]
#[serial]
fn removed_trailing_fire_hits_the_over_fire_tail_branch_exit_6() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // The canonical tail is relay@(step 3, level 1) — the LAST fire. Removing it
    // leaves recorded = 7 fires, all position-equal to replay's first 7.
    let i = fire_index_at(&rec, "relay", 3);
    rec.trace.remove(i);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("removed_tail_fire.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None).unwrap();
    assert!(
        outcome.violations.is_empty(),
        "removing a trace fire (not frames) must not create a data violation: {:?}",
        outcome.violations
    );
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("a thinned tail must diverge (exit 6)");
    // 7 recorded vs 8 replayed — the divergence is the tail at position 7.
    assert_eq!(td.position, 7);
    assert!(
        td.recorded.is_none(),
        "the recording has no fire at the tail position"
    );
    let rep_t = td
        .replayed
        .as_ref()
        .expect("the replayed tail fire present");
    assert_eq!(
        (rep_t.node_id.as_str(), rep_t.step, rep_t.global_level),
        ("relay", 3, 1)
    );
    assert!(
        td.detail.contains("OVER-fired") && td.detail.contains("7 recorded vs 8 replayed"),
        "detail names the over-fire direction + counts: {}",
        td.detail
    );
    assert!(!td.detail.contains("  "), "detail: {:?}", td.detail);
}

// ===========================================================================
// 20. Within-(step, level) ordering
//
// Every other fixture is single-node-per-level, so the within-level half of the
// canonical (step, global_level, rank, seq) order is exercised only here. Two
// INDEPENDENT source nodes share ONE DAG level (both level 0): the recording's
// within-level write order IS the canonical (rank=0, seq) order — seq is bag
// write position — so an unperturbed bag aligns with the deterministic replay
// emission order (graph-declaration order), and a PERMUTED same-(step, level)
// pair diverges (exit 6): the order pre-check passes (equal (step, level) keys
// are non-decreasing) but the node identity at the position differs.
// ===========================================================================

/// Two-independent-source graph: `alpha` and `beta` both at DAG level 0 (no
/// edges), each a 5 ms period source.
fn two_sources_yaml() -> &'static str {
    "name: tsgraph\nprefix: ts\nnodes:\n\
     \x20 - id: alpha\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: beta\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

/// Fresh factories for the two-source graph.
fn two_sources_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        ("alpha", Box::new(SourceNodeEntry::new())),
        ("beta", Box::new(SourceNodeEntry::new())),
    ])
}

/// Item 5 arm (a) — the happy alignment pin for a MULTI-fire level: an
/// unperturbed two-nodes-one-level bag replays with NO divergence (the
/// recording's within-level write order matches the deterministic replay
/// emission order position-for-position).
#[test]
#[serial]
fn two_nodes_one_level_unperturbed_has_no_trace_divergence() {
    let steps = 4;
    let rec = record_uniform(two_sources_yaml(), two_sources_factories, &[], steps);

    // Structural oracle: both nodes fire EVERY step at level 0, alpha before
    // beta (graph-declaration order) — [a0,b0,a1,b1,…].
    let fires: Vec<(String, u64, u32)> = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_FIRE)
        .map(|r| {
            (
                rec.node_ids[r.node_idx as usize].clone(),
                r.step,
                r.global_level,
            )
        })
        .collect();
    let expected: Vec<(String, u64, u32)> = (0..steps as u64)
        .flat_map(|s| {
            [
                ("alpha".to_string(), s, 0u32),
                ("beta".to_string(), s, 0u32),
            ]
        })
        .collect();
    assert_eq!(fires, expected, "recorded fire order oracle");

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("two_sources.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, two_sources_factories, None, None).unwrap();
    assert!(
        outcome.passed,
        "unperturbed multi-fire-level replay must pass: {:?}",
        outcome.violations
    );
    assert!(
        outcome.trace_divergence.is_none(),
        "within-level order must align with the deterministic emission order: {:?}",
        outcome.trace_divergence
    );
}

/// Item 5 arm (b) — a PERMUTED same-(step, level) recorded pair diverges (exit
/// 6). The two step-1 fires (alpha then beta, both (step 1, level 0)) are
/// swapped: the fire-order pre-check PASSES (equal (step, level) keys are
/// non-decreasing — this is NOT recording corruption), but the recording's
/// within-level write order IS the canonical (rank, seq) order, so the permuted
/// recording diverges from the deterministic replay emission order at the first
/// swapped position, naming both node ids.
#[test]
#[serial]
fn permuted_same_step_level_pair_is_trace_divergence_exit_6() {
    let mut rec = record_uniform(two_sources_yaml(), two_sources_factories, &[], 4);
    let ai = fire_index_at(&rec, "alpha", 1);
    let bi = fire_index_at(&rec, "beta", 1);
    rec.trace.swap(ai, bi);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("permuted_pair.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, two_sources_factories, None, None).unwrap();
    assert!(
        outcome.violations.is_empty(),
        "frames unchanged → no data violation: {:?}",
        outcome.violations
    );
    let td = outcome
        .trace_divergence
        .as_ref()
        .expect("a permuted within-level pair must diverge (exit 6)");
    // Canonical fires [a0,b0,a1,b1,…]: the step-1 alpha slot is position 2 —
    // recorded now 'beta', replay emits 'alpha' there.
    assert_eq!(td.position, 2);
    let rec_t = td.recorded.as_ref().unwrap();
    let rep_t = td.replayed.as_ref().unwrap();
    assert_eq!(rec_t.node_id, "beta");
    assert_eq!(rep_t.node_id, "alpha");
    assert_eq!((rec_t.step, rec_t.global_level), (1, 0));
    assert_eq!((rep_t.step, rep_t.global_level), (1, 0));
    assert!(
        td.detail.contains("'beta'") && td.detail.contains("'alpha'"),
        "detail names both node ids: {}",
        td.detail
    );
}

/// The TIME-denominated cap — a `--duration`
/// bound that covers EXACTLY the recorded span is a no-op cap: the outcome is
/// identical to the unbounded replay (no false divergence at the boundary,
/// every recorded fire included, all ticks replayed). Guards an off-by-one in
/// the recorded-fire capping.
#[test]
#[serial]
fn a_duration_covering_the_whole_recording_is_identical_to_unbounded() {
    let steps = 5;
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], steps);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("exact_cap.mcap");
    write_bag(&rec, &bag, None);

    let capped = replay(
        &bag,
        source_relay_factories,
        Some(duration_for_steps(steps as u64)),
        None,
    )
    .unwrap();
    let uncapped = replay(&bag, source_relay_factories, None, None).unwrap();

    // Anchor: BOTH pass (not a self-compare of two failures).
    assert!(
        capped.passed,
        "exact cap must pass: {:?}",
        capped.violations
    );
    assert!(uncapped.passed);
    assert!(capped.trace_divergence.is_none());
    assert_eq!(capped.ticks_replayed, steps, "every recorded step replayed");
    assert_eq!(uncapped.ticks_replayed, steps);
    // Every recorded fire is compared (2 nodes × steps) — a clean pass proves the
    // streaming check matched all of them; the recorded oracle counts them.
    let recorded_fire_count = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_FIRE)
        .count();
    assert_eq!(recorded_fire_count, 2 * steps);
    // Byte-identical outcomes (the JSON serializes trace_divergence too).
    assert_eq!(
        serde_json::to_string(&capped).unwrap(),
        serde_json::to_string(&uncapped).unwrap(),
        "a whole-span duration bound must be indistinguishable from unbounded"
    );
}

// ===========================================================================
// Exit 3: PANIC-CLASS node failures during replay
// ===========================================================================

/// The PANICKING candidate: same shape as [`SourceNode`], but the tick PANICS
/// from its third fire onward (ticks 1–2 publish the golden `x == counter`).
/// Models "the candidate build crashes mid-replay" — the exit-3 execution
/// class.
#[cerulion_node(period_ms = 5)]
#[derive(Default)]
struct PanicAtTick3SourceNode {
    #[output]
    out: Vector3,
    counter: f64,
}

#[cerulion_node_impl]
impl PanicAtTick3SourceNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.counter += 1.0;
        if self.counter >= 3.0 {
            panic!("injected candidate crash at tick {}", self.counter);
        }
        self.out.x = self.counter;
        Ok(())
    }
}

/// The deterministic-Err candidate: same shape as [`SourceNode`], but ODD
/// ticks return `Err` (publishing nothing — the macro publishes only on a
/// clean tick) while EVEN ticks publish `x == counter`. The Err message
/// deliberately SAYS "panicked" — proving the panic-class detection is
/// STRUCTURAL (the variant / catch site), never a string match on the reason.
#[cerulion_node(period_ms = 5)]
#[derive(Default)]
struct ErrEveryOtherSourceNode {
    #[output]
    out: Vector3,
    counter: f64,
}

#[cerulion_node_impl]
impl ErrEveryOtherSourceNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.counter += 1.0;
        if (self.counter as u64) % 2 == 1 {
            return Err(NodeError::Logic(
                "deterministic Err — this message says panicked but is NOT a panic".to_string(),
            ));
        }
        self.out.x = self.counter;
        Ok(())
    }
}

/// Single-source graph YAML for the Err≠panic pin (prefix `errg`).
fn err_source_yaml() -> &'static str {
    "name: errgraph\nprefix: errg\nnodes:\n\
     \x20 - id: source\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

/// Exit 3, the POSITIVE pin: a candidate node that PANICS
/// mid-replay is reported as a panic-class [`replay_engine::NodeFailure`] —
/// the root cause the CLI maps to exit 3 — while the data diff AND the
/// structural trace check still complete (the fuller report: all three
/// blocks render, pinning the 3-over-6-over-1 precedence material at the
/// outcome layer; the exit-code pick itself is `main.rs` + the subprocess
/// e2e in `cerulion_cli/tests/replay_cli_test.rs`).
///
/// Shape: a GOLDEN source→relay recording (6 steps, hand-oracle-anchored by
/// the happy-path test) replayed with a source that panics from tick 3 —
/// so ticks 1–2 match, ticks 3+ crash (recorded even as fires — the
/// scheduler records fires on panic — until the consecutive-panic breaker
/// disables the node), leaving missing frames (violations) AND a thinner
/// replayed schedule (trace divergence) downstream of the ONE root cause.
#[test]
#[serial]
fn panicking_candidate_reports_node_failure_and_renders_all_blocks() {
    let steps = 6;
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], steps);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("panic_candidate.mcap");
    write_bag(&rec, &bag, None);

    let make = || {
        factories(vec![
            ("source", Box::new(PanicAtTick3SourceNodeEntry::new())),
            (
                "relay",
                Box::new(RelayNodeEntry::with_state(RelayNode {
                    addend: 100.0,
                    ..Default::default()
                })),
            ),
        ])
    };
    let outcome = replay(&bag, make, None, None).expect("replay runs to an outcome");

    // The headline: the panic is reported STRUCTURALLY as a node failure.
    assert_eq!(
        outcome.node_failures.len(),
        1,
        "exactly one crashed node: {:?}",
        outcome.node_failures
    );
    assert_eq!(outcome.node_failures[0].node_id, "source");
    assert!(
        outcome.node_failures[0]
            .reason
            .contains("injected candidate crash at tick 3"),
        "the FIRST panic reason is recorded: {}",
        outcome.node_failures[0].reason
    );
    assert!(!outcome.passed, "a crashed candidate never passes");

    // The downstream fallout is STILL fully reported (root cause preempts the
    // exit code, not the diff): missing frames on both topics + a thinner
    // replayed schedule.
    assert!(
        !outcome.violations.is_empty(),
        "the missing frames must still surface as data violations"
    );
    assert!(
        outcome.trace_divergence.is_some(),
        "the crashed node's thinner schedule must still surface structurally"
    );

    // All THREE verdict blocks render (the fuller report).
    let verdict = replay_engine::render_verdict(&outcome, &bag);
    assert!(
        verdict.contains("NODE FAILURE") && verdict.contains("panic-class"),
        "verdict must open with the NODE FAILURE block: {verdict}"
    );
    assert!(
        verdict.contains("'source'"),
        "the NODE FAILURE block names the crashed node: {verdict}"
    );
    assert!(
        verdict.contains("FIRE-SCHEDULE DIVERGENCE"),
        "the structural block still renders: {verdict}"
    );
    assert!(
        verdict.contains("FRAME-CONTENT DIVERGENCE"),
        "the data block still renders: {verdict}"
    );
}

/// Exit 3, the NEGATIVE pin (THE Replay=Live pin): a node
/// whose tick returns `Err` DETERMINISTICALLY is NORMAL execution — a bag
/// recorded from the Err-ing node replays byte-exact against the same
/// candidate to a clean PASS (exit 0) with ZERO node failures, even though
/// the Err message says "panicked" (structural detection, no string match).
/// Fires are recorded even on tick Err, so the schedule matches; frames
/// exist only for the clean (even) ticks on BOTH sides.
#[test]
#[serial]
fn deterministic_err_candidate_replays_byte_exact_with_no_node_failure() {
    let steps = 6;
    let make = || {
        factories(vec![(
            "source",
            Box::new(ErrEveryOtherSourceNodeEntry::new()),
        )])
    };
    let rec = record_uniform(err_source_yaml(), make, &[], steps);

    // Anchor the RECORDING to a hand oracle (not a self-compare): only the
    // EVEN ticks published, x == 2, 4, 6.
    let frames = &rec.messages["/errg/source/out"];
    assert_eq!(frames.len(), 3, "odd ticks Err → publish nothing");
    for (i, frame) in frames.iter().enumerate() {
        assert_eq!(frame_x(frame), ((i + 1) * 2) as f64, "even-tick oracle");
    }
    // The trace still carries one fire per step (fires record even on Err).
    let fire_count = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_FIRE)
        .count();
    assert_eq!(fire_count, steps, "every tick fired, Err or not");

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("err_candidate.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, make, None, None).expect("replay runs");
    assert!(
        outcome.node_failures.is_empty(),
        "a deterministic tick Err is NOT panic-class (no string matching on \
         the reason): {:?}",
        outcome.node_failures
    );
    assert!(
        outcome.passed,
        "Err-ing candidate replays byte-exact (Replay = Live): {:?}",
        outcome.violations
    );
    assert_eq!(outcome.ticks_replayed, steps);
    assert!(outcome.trace_divergence.is_none());
    assert!(outcome.violations.is_empty());
}

// ===========================================================================
// Burst-aware tap provisioning: Period catch-up bursts
// ===========================================================================

/// Burst-aware provisioning, the REGRESSION pin. A recording-time
/// stall writes one large step-boundary delta; at replay the period node
/// fires EVERY catch-up tick in that one step — an intra-step burst larger
/// than the default tap depth (measured on a real 1.4 GB moveit2 bag: 23
/// frames in one 22.8 ms step on a 1 kHz topic, which overflowed the
/// depth-16 tap and failed the replay exit 5). Here the 300 ms delta on a
/// 5 ms-period source fires 60 catch-up ticks in ONE step → 60 frames on one
/// topic in one step, ~4× the old default tap depth.
///
/// The engine pre-scans the recording (`burst_provisioning`) and raises
/// ONLY the bursty topic's service ceiling (the capture tap inherits it), so
/// the full replay is byte-exact. Reverting the
/// burst provisioning (passing `None` into the build) makes THIS test fail
/// with the recording-aware tap-loss error — `capture tap lost frames … a
/// skipped sequence exists in the recording` (exit 5) — exactly what a real bag
/// with such a burst produces. The reference run records through a DEEP (128) tap, modelling
/// bagd's deep recorder buffers, so the bag really holds the whole burst.
#[test]
#[serial]
fn period_catchup_burst_replays_byte_exact_with_burst_provisioning() {
    // Steps: 5 ms, 5 ms, 300 ms (the stall → 60 catch-up fires), 5 ms.
    let deltas = [5u64, 5, 300, 5];
    let rec = record_reference_with_buffer(
        source_relay_yaml(),
        source_relay_factories,
        &[],
        &deltas,
        128,
    );

    // Hand oracle for the recording (not a self-compare): the source fired
    // 1 + 1 + 60 + 1 = 63 ticks with x == 1..=63; the 60 burst frames all
    // stamp the SAME advanced clock (the stall step's boundary target).
    let src = &rec.messages["/sr/source/out"];
    assert_eq!(src.len(), 63, "1 + 1 + 60 (catch-up burst) + 1 fires");
    for (k, frame) in src.iter().enumerate() {
        assert_eq!(frame_x(frame), (k + 1) as f64, "source counter oracle");
    }
    let burst_ts = WireHeader::read_from_buf(&src[10]).unwrap().timestamp_ns;
    let burst_frames = src
        .iter()
        .filter(|f| WireHeader::read_from_buf(f).unwrap().timestamp_ns == burst_ts)
        .count();
    assert_eq!(burst_frames, 60, "the stall step carries the whole burst");

    // The provisioning pre-scan: the BURSTY topic gets a raised floor
    // (60 + headroom), and the non-bursty relay topic is ABSENT — no
    // blanket max-provisioning (it keeps its topology-derived default).
    let floors = replay_engine::burst_provisioning(&RecordedMessages::from_owned_frames(
        rec.messages.clone(),
    ));
    let src_floor = floors
        .get("/sr/source/out")
        .expect("the bursty topic gets a floor");
    assert_eq!(
        src_floor.min_buffer, 64,
        "floor = measured burst (60) + headroom (4)"
    );
    assert!(
        !floors.contains_key("/sr/relay/out"),
        "the non-bursty relay topic keeps its default ceiling: {floors:?}"
    );

    // The headline: the full replay is byte-exact end-to-end. Without the
    // burst provisioning the depth-16 tap loses 44 recorded frames in the
    // stall step and the run dies exit-5 (`capture tap lost frames`).
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("catchup_burst.mcap");
    write_bag(&rec, &bag, None);

    let outcome = replay(&bag, source_relay_factories, None, None)
        .expect("burst replay must not trip the tap-loss tripwire");
    assert!(
        outcome.passed,
        "the catch-up burst must replay byte-exact: {:?}",
        outcome.violations
    );
    assert_eq!(outcome.ticks_replayed, deltas.len());
    assert!(outcome.trace_divergence.is_none());
    assert!(outcome.node_failures.is_empty());
}

// ===========================================================================
// MEMORY SCALER — the STEP/FIRE-COUNT peak-RSS scaling gate.
//
// Replay's PAYLOAD-BYTE cost is bounded by streaming the frames, but that says
// nothing about cost that scales with STEP/FRAME COUNT (as opposed to
// payload bytes). This gate does: it replays two bags at a 10× step-count ratio
// with a TINY constant payload (the `Vector3` source→relay graph — isolating
// the count axis from the byte axis) and asserts the MARGINAL peak RSS per step
// stays "span-index-sized". Each replay runs in its OWN subprocess (a
// replay-ONLY child, so the recording phase's in-process frames never mask the
// replay peak — the same two-phase split the manual probe below uses), which
// prints its `getrusage` peak; the parent builds both bags and diffs the two
// children's peaks.
//
// The marginal (bytes/step) subtracts the two legs, so the fixed process
// baseline (binary + iceoryx2 pools) CANCELS — what remains is what the extra
// 90k steps cost. With streaming replay that is the span-index-sized floor
// (the trace records + message spans + the boundary set) — hundreds of
// bytes/step. An eager replay ALSO carries a per-fire `String`
// pile (node id, both sides) + two `O(fire-count)` `Vec` spines + the
// never-cleared live trace — 300+ extra bytes/step — so the streaming code is
// dramatically below the eager marginal. The deterministic proof of the O(1)
// retained window is the `TraceDiffStream` bounded-retention unit tests in the
// engine; this is the end-to-end confidence gate + the reported measurement.
//
// Step counts are $CER_RSS_STEPS_SMALL / $CER_RSS_STEPS_BIG (default 2k/20k).
// ===========================================================================

/// This process's peak resident set in BYTES. `ru_maxrss` is bytes on macOS and
/// KiB on Linux — normalized here so the marginal assertion is one threshold on
/// both. Peak (high-water), so a replay-only child's value is its replay working
/// set + the fixed process baseline.
fn peak_rss_bytes() -> u64 {
    // SAFETY: `getrusage` fills a caller-owned `rusage`; zeroed init is valid.
    let maxrss = unsafe {
        let mut usage: libc::rusage = std::mem::zeroed();
        libc::getrusage(libc::RUSAGE_SELF, &mut usage);
        usage.ru_maxrss as u64
    };
    if cfg!(target_os = "linux") {
        maxrss * 1024 // KiB → bytes
    } else {
        maxrss // macOS: already bytes
    }
}

fn rss_steps(env: &str, default: usize) -> usize {
    std::env::var(env)
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(default)
}

/// Env var carrying the bag path to the replay-only RSS child.
const RSS_CHILD_BAG_ENV: &str = "CER_RSS_CHILD_BAG";

/// The replay-only subprocess: replays the bag named by [`RSS_CHILD_BAG_ENV`] and
/// prints its peak RSS. `#[ignore]` + the env guard keep it inert unless the
/// parent [`trace_channel_replay_rss_scales_sublinearly`] re-execs it.
#[test]
#[ignore = "subprocess child of trace_channel_replay_rss_scales_sublinearly"]
#[serial]
fn replay_rss_probe_child() {
    let Ok(bag) = std::env::var(RSS_CHILD_BAG_ENV) else {
        return; // not the re-exec'd child — no-op.
    };
    // Sample LIVE heap at every step (the fire tap runs inside the replay
    // loop) — retained per-step/per-frame structures are alive at EVERY
    // sample, while one-shot transients elsewhere (load, validation,
    // assembly) never pollute it. This is the gate's PRIMARY metric.
    let loop_max_live = std::sync::Arc::new(std::sync::atomic::AtomicIsize::new(0));
    let sink = loop_max_live.clone();
    let tap: replay_engine::FireTap = Box::new(move |_side, _tuple| {
        let live = LIVE_HEAP.load(std::sync::atomic::Ordering::SeqCst);
        sink.fetch_max(live, std::sync::atomic::Ordering::SeqCst);
    });
    let outcome = replay_inner(
        std::path::Path::new(&bag),
        source_relay_factories,
        None,
        None,
        Some(tap),
        RecordHealthReport::Absent,
        None,
        false,
    )
    .expect("child replay must run");
    assert!(
        outcome.passed,
        "child replay must pass: {:?}",
        outcome.violations
    );
    // The parent parses these lines (loop-max live heap = the tight retention
    // gate; peak live heap = the transient gate; peak RSS = the loose noise
    // backstop — see `LiveCountingAlloc` + the parent's gate comments).
    println!("PEAK_RSS_BYTES={}", peak_rss_bytes());
    println!(
        "PEAK_LIVE_HEAP_BYTES={}",
        PEAK_LIVE_HEAP.load(std::sync::atomic::Ordering::SeqCst)
    );
    println!(
        "LOOP_MAX_LIVE_BYTES={}",
        loop_max_live.load(std::sync::atomic::Ordering::SeqCst)
    );
}

/// Re-exec THIS test binary as a replay-only child on `bag` and return its peak
/// RSS (bytes). A fresh process ⇒ the replay peak is not contaminated by the
/// parent's bag-building frames.
/// (peak ru_maxrss, peak live-heap, loop-max live-heap) bytes from a
/// replay-only subprocess.
fn spawn_replay_rss_child(bag: &std::path::Path) -> (u64, u64, u64) {
    let exe = std::env::current_exe().expect("current_exe");
    let output = std::process::Command::new(exe)
        .args([
            "--exact",
            "replay_rss_probe_child",
            "--ignored",
            "--nocapture",
            "--test-threads=1",
        ])
        .env(RSS_CHILD_BAG_ENV, bag)
        .output()
        .expect("spawn replay RSS child");
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(
        output.status.success(),
        "replay RSS child failed (status {:?})\nstdout:\n{stdout}\nstderr:\n{}",
        output.status.code(),
        String::from_utf8_lossy(&output.stderr)
    );
    // Substring search (not line-start): libtest `--nocapture` prints the
    // progress line `test replay_rss_probe_child ... ` WITHOUT a trailing newline,
    // so the marker `println!` lands mid-line.
    let parse = |marker: &str| -> u64 {
        stdout
            .split(marker)
            .nth(1)
            .and_then(|rest| {
                let digits: String = rest.chars().take_while(char::is_ascii_digit).collect();
                digits.parse::<u64>().ok()
            })
            .unwrap_or_else(|| panic!("child did not print {marker}; stdout:\n{stdout}"))
    };
    (
        parse("PEAK_RSS_BYTES="),
        parse("PEAK_LIVE_HEAP_BYTES="),
        parse("LOOP_MAX_LIVE_BYTES="),
    )
}

#[test]
#[serial]
fn trace_channel_replay_rss_scales_sublinearly() {
    // Modest CI defaults (a 10× ratio — the marginal is stable across scales, so
    // a smaller sweep is representative); a manual/nightly run raises them via env
    // for a bigger measurement.
    let small = rss_steps("CER_RSS_STEPS_SMALL", 2_000);
    let big = rss_steps("CER_RSS_STEPS_BIG", 20_000);
    assert!(big > small, "big leg must have more steps");

    // Tiny CONSTANT payload (the 24-byte Vector3 source→relay graph): the two
    // legs differ ONLY in step/fire count, so the marginal isolates the
    // count-axis cost the memory scaler targets (Principle #13 — every byte is
    // real source→relay output, no fabricated data).
    let dir = tempfile::tempdir().unwrap();
    let bag_small = dir.path().join("rss_small.mcap");
    let bag_big = dir.path().join("rss_big.mcap");
    write_bag(
        &record_uniform(source_relay_yaml(), source_relay_factories, &[], small),
        &bag_small,
        None,
    );
    write_bag(
        &record_uniform(source_relay_yaml(), source_relay_factories, &[], big),
        &bag_big,
        None,
    );

    let (rss_small, live_small, loop_small) = spawn_replay_rss_child(&bag_small);
    let (rss_big, live_big, loop_big) = spawn_replay_rss_child(&bag_big);
    let extra_steps = (big - small) as f64;
    // saturating: a big leg BELOW the small leg (baseline jitter / freed-early
    // transients) means the marginal is ~0 — the strongest possible pass.
    let rss_marginal = rss_big.saturating_sub(rss_small) as f64 / extra_steps;
    let live_marginal = live_big.saturating_sub(live_small) as f64 / extra_steps;
    let loop_marginal = loop_big.saturating_sub(loop_small) as f64 / extra_steps;
    println!(
        "RSS scaling: small={small} steps -> rss {rss_small} B / peak-live {live_small} B \
         / loop-live {loop_small} B, big={big} steps -> rss {rss_big} B / peak-live {live_big} B \
         / loop-live {loop_big} B; marginals: rss {rss_marginal:.1}, peak-live \
         {live_marginal:.1}, loop-live {loop_marginal:.2} B/step over {} extra steps",
        big - small
    );

    // TIER 1 — THE retention gate: LIVE heap sampled INSIDE
    // the replay loop (per-step fire tap). Any structure retained per
    // step/frame is alive at every sample, so it lands here in full; one-shot
    // transients outside the loop (load, validation, assembly) do not. The
    // metric is deterministic (a counting allocator, not RSS) — measured
    // marginal ~0 B/step. Per-structure bite table (B/step this gate
    // must catch, at this bag's 3 trace records + 2 frames per step):
    //   span-index revert             ~32  (2 spans x 16 B)
    //   boundary-Vec revert           ~16
    //   validate by_step + target_set ~100+ (BTreeMap+HashSet per boundary)
    //   trace-Vec revert              ~120  (3 records x 40 B)
    //   seq-HashSet revert            ~96   (2 seqs x ~48 B)
    //   owned-frame Vecs revert       several hundred
    // Ceiling 8 B/step: bites EVERY row (smallest = 16) with 2x separation,
    // and sits ~8 B above the ~0 measured floor. (The FrameFeed walk-ahead
    // and TraceDiffStream windows are step-count-INDEPENDENT — pinned by
    // their own unit tests — so they cannot drift this marginal.)
    const LOOP_LIVE_CEILING_BYTES_PER_STEP: f64 = 8.0;
    assert!(
        loop_marginal < LOOP_LIVE_CEILING_BYTES_PER_STEP,
        "replay loop-live heap grew {loop_marginal:.2} B/step ({} steps: {loop_small} B -> {} \
         steps: {loop_big} B) — a per-step/per-frame structure is being retained \
         (< {LOOP_LIVE_CEILING_BYTES_PER_STEP} B/step; smallest known revert = the 16 B/step \
         boundary Vec).",
        small,
        big
    );

    // TIER 2 — the transient gate: PEAK live heap across the whole child.
    // Catches an O(steps) one-shot allocation anywhere in the replay path
    // (the class a MessageIndex content-parse is: ~51 B/step of
    // transient). Floor measured 0.0 B/step (with the arrival-order
    // bag layout the production recorder writes — see `write_bag`); ceiling
    // 64 B/step catches every known transient class with the whole ceiling
    // as headroom.
    const LIVE_HEAP_CEILING_BYTES_PER_STEP: f64 = 64.0;
    assert!(
        live_marginal < LIVE_HEAP_CEILING_BYTES_PER_STEP,
        "replay peak LIVE HEAP grew {live_marginal:.1} B/step ({} steps: {live_small} B -> {} \
         steps: {live_big} B) — an O(steps) transient allocation crept into the replay path \
         (< {LIVE_HEAP_CEILING_BYTES_PER_STEP} B/step).",
        small,
        big
    );

    // TIER 3 — loose ru_maxrss backstop (NOT a gate on hard heap — peak RSS is
    // dominated by evictable mapped-page touch ~400-650 B/step here and is not
    // portably tight-assertable): catches only a catastrophic
    // O(steps^2)-class regression that even the page-cache floor cannot absorb.
    const RSS_MARGINAL_CEILING_BYTES_PER_STEP: f64 = 4_096.0;
    assert!(
        rss_marginal < RSS_MARGINAL_CEILING_BYTES_PER_STEP,
        "replay peak RSS grew {rss_marginal:.1} B/step ({} steps: {rss_small} B -> {} steps: \
         {rss_big} B) — catastrophically above the mapped-page floor \
         (< {RSS_MARGINAL_CEILING_BYTES_PER_STEP} B/step backstop).",
        small,
        big
    );
}

// ===========================================================================
// MEMORY — manual peak-RSS probe (ignored; run under
// `/usr/bin/time -l`). NOT a CI assertion (peak RSS is not portably
// assertable). Two phases so the replay process's peak is not masked by the
// recording phase's owned frames: run `mem_probe_write_big_bag` once (writes
// the bag to $CER_MEM_BAG), then run `mem_probe_replay_big_bag` UNDER
// `/usr/bin/time -l` and read "maximum resident set size". The step count is
// $CER_MEM_STEPS (default 300_000). Every byte flowing through is REAL source
// → relay node output (Principle #13) — the probe just records many steps of a
// real graph to build a bag whose payload dwarfs the replay's working set.
// ===========================================================================

fn mem_probe_bag_path() -> std::path::PathBuf {
    std::env::var("CER_MEM_BAG")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|_| std::env::temp_dir().join("cer_mem_probe.mcap"))
}

fn mem_probe_steps() -> usize {
    std::env::var("CER_MEM_STEPS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(300_000)
}

#[test]
#[ignore = "manual memory probe — writes a large bag to $CER_MEM_BAG"]
#[serial]
fn mem_probe_write_big_bag() {
    let steps = mem_probe_steps();
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], steps);
    let bag = mem_probe_bag_path();
    write_bag(&rec, &bag, None);
    let size = std::fs::metadata(&bag).unwrap().len();
    println!(
        "mem-probe: wrote {steps} steps -> {} ({:.1} MiB on disk)",
        bag.display(),
        size as f64 / (1024.0 * 1024.0)
    );
}

#[test]
#[ignore = "manual memory probe — replay $CER_MEM_BAG under /usr/bin/time -l"]
#[serial]
fn mem_probe_replay_big_bag() {
    let bag = mem_probe_bag_path();
    let size = std::fs::metadata(&bag)
        .unwrap_or_else(|_| panic!("run mem_probe_write_big_bag first: {}", bag.display()))
        .len();
    let outcome = replay(&bag, source_relay_factories, None, None).expect("replay big bag");
    println!(
        "mem-probe: replayed {} ({:.1} MiB on disk): passed={} ticks={} topics={}/{}",
        bag.display(),
        size as f64 / (1024.0 * 1024.0),
        outcome.passed,
        outcome.ticks_replayed,
        outcome.topics_passed,
        outcome.topics_checked
    );
}

// ===========================================================================
// record_health.json CONSUMPTION (engine-side)
//
// The engine's replay-side behavior on the bag's `__cerulion/record_health.json`
// stamp (Option B "warn-and-attribute"). The stamp is injected DIRECTLY into
// `ReplayInputs.record_health` via the `replay_with_health` seam (the production
// gate reads it off the bag attachment — that read is pinned by the inline unit
// tests in `replay_cmd.rs`). Oracle-vector, never self-compare: each stamp is a
// hand-built `RecordHealth` with known counts and the resulting violations /
// exit are asserted against the decided semantics.
// ===========================================================================

/// Source-only factories for the overflow-tripwire recording (shared by the
/// lossy-attributed and clean-stays-exit-5 tests).
fn overflow_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![("source", Box::new(SourceNodeEntry::new()))])
}

/// A COMPLETE recording whose one-step catch-up burst (4200 frames) exceeds
/// iceoryx2's 4096 tap clamp — so on replay the capture tap overflows and the
/// recording-aware wire-sequence gap tripwire fires (the exit-5 harness-loss
/// path). The SAME recording drives the lossy-stamped (attributed exit 1) and
/// clean-stamped (stays exit 5) tests — the only difference is the injected
/// stamp. Crib of `capture_overflow_beyond_clamp_is_internal_error_not_violation`.
fn overflow_recording() -> Recording {
    let yaml = "name: ovh\nprefix: ovh\nnodes:\n\
        \x20 - id: source\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n";
    const BURST: u32 = 4200;
    let mut rec =
        record_reference_with_buffer(yaml, overflow_factories, &[], &[5, 5 * BURST as u64], 128);
    let frames = rec.messages.get_mut("/ovh/source/out").unwrap();
    let anchor = WireHeader::read_from_buf(&frames[0]).expect("anchor header");
    let survivor_seq = WireHeader::read_from_buf(&frames[1])
        .expect("survivor header")
        .sequence;
    let template = frames[1].clone();
    for (i, s) in ((anchor.sequence + 1)..survivor_seq).enumerate() {
        let mut f = template.clone();
        f[20..24].copy_from_slice(&s.to_le_bytes()); // wire sequence.
        let x = (s + 1) as f64; // hand oracle: x == seq + 1.
        f[WireHeader::SIZE..WireHeader::SIZE + 8].copy_from_slice(&x.to_le_bytes());
        frames.insert(1 + i, f);
    }
    assert_eq!(
        frames.len(),
        1 + BURST as usize,
        "the recording is complete (anchor + the whole burst)"
    );
    rec
}

/// Build a `Present` record-health stamp from `(topic, frames_lost, gap_events,
/// sequence_anomaly, multi_publisher)` rows + a global unwritten-drop count.
fn health_stamp(
    rows: &[(&str, u64, u64, bool, bool)],
    dropped_unwritten: u64,
) -> RecordHealthReport {
    let topics = rows
        .iter()
        .map(
            |&(t, frames_lost, gap_events, sequence_anomaly, multi_publisher)| {
                (
                    t.to_string(),
                    TopicHealth {
                        frames_recorded: 0, // not read by the consumer.
                        frames_lost,
                        gap_events,
                        multi_publisher,
                        sequence_anomaly,
                        first_seq: None,
                        last_seq: None,
                        baseline_resets_after_first: 0,
                        gap_detection_disabled_reason: None,
                        classify_calls: 0,
                        defer_count: 0,
                        staging_full_passes: 0,
                        // Not read by the consumer either.
                        tap_buffer_depth: None,
                        shm_pinned_bytes: None,
                        // Likewise not read by the consumer.
                        producer_labels: 0,
                        label_catch_up: false,
                        // The absorbance verdict describes
                        // the RECORDER's queues, which no replay verdict reads.
                        absorbance: None,
                        loss_counting_basis: None,
                    },
                )
            },
        )
        .collect();
    RecordHealthReport::Present(RecordHealth {
        version: RECORD_HEALTH_VERSION,
        dropped_unwritten,
        // The drive-loop observables describe the RECORDER's own loop,
        // which no replay verdict reads — left at their default so this helper
        // keeps building the stamp shape its callers assert on.
        drive_passes: 0,
        max_pass_duration_us: 0,
        // The cadence observables describe the recorder's loop too.
        drive_span_us: 0,
        drain_gaps: cerulion_bagd::DrainGapHistogram::default(),
        // Likewise a recorder-side statement.
        loss_counting_basis: None,
        topics,
    })
}

/// Assert `outcome` carries EXACTLY one violation: a `RecordSideTapLoss` on
/// `topic` whose class fields EQUAL the stamp's values (frames_lost /
/// gap_events / sequence_anomaly) and whose detail is the decided relabel text.
fn assert_sole_tap_loss(
    outcome: &ReplayOutcome,
    topic: &str,
    frames_lost: u64,
    gap_events: u64,
    sequence_anomaly: bool,
) {
    assert!(!outcome.passed, "a record-side-lossy topic must fail");
    assert_eq!(
        outcome.violations.len(),
        1,
        "exactly one attributed violation: {:?}",
        outcome.violations
    );
    let v = &outcome.violations[0];
    assert_eq!(v.topic, topic);
    match v.class {
        ViolationClass::RecordSideTapLoss {
            frames_lost: fl,
            gap_events: ge,
            sequence_anomaly: sa,
        } => {
            assert_eq!(
                (fl, ge, sa),
                (frames_lost, gap_events, sequence_anomaly),
                "the class fields carry the stamp's values verbatim"
            );
        }
        ref other => panic!("class must be RecordSideTapLoss, got {other:?}"),
    }
    assert!(
        v.detail.contains("record-side tap loss")
            && v.detail
                .contains("byte-exact verification impossible on this topic"),
        "the relabel detail carries the RULED text: {}",
        v.detail
    );
}

/// Rules 5a/5b/5d: a lossy-STAMPED topic whose capture tap overflows on
/// replay is ATTRIBUTED as an exit-1 `RecordSideTapLoss` — NOT the exit-5
/// harness tripwire (`result.is_ok()` is the mutation-detector: reverting the
/// rule-5d interception makes `drain` return `Err(Internal)` here), NOT a
/// plain byte/count label, and the up-front warn block fired.
#[test]
#[serial]
#[tracing_test::traced_test]
fn lossy_stamped_capture_gap_is_attributed_exit1_not_exit5() {
    let rec = overflow_recording();
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("ovh_lossy.mcap");
    write_bag(&rec, &bag, None);

    let stamp = health_stamp(&[("/ovh/source/out", 4072, 1, false, false)], 0);
    let outcome = replay_with_health(&bag, overflow_factories, None, stamp)
        .expect("a lossy-stamped tap gap is ATTRIBUTED (exit 1), never the exit-5 tripwire");
    assert_sole_tap_loss(&outcome, "/ovh/source/out", 4072, 1, false);
    assert!(
        logs_contain("RECORD-SIDE LOSS"),
        "the up-front warn block fired before verification"
    );
    assert!(
        logs_contain("record-side frame loss on this topic"),
        "the per-topic loss line fired"
    );
}

/// Rule 5d negative control: the SAME overflow recording with a CLEAN
/// stamp on the tripping topic STAYS exit 5 — the stamp does not explain a
/// genuine provisioning fault. The anti-tautology twin of the lossy-stamped arm above.
#[test]
#[serial]
fn clean_stamped_capture_gap_stays_exit5() {
    let rec = overflow_recording();
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("ovh_clean.mcap");
    write_bag(&rec, &bag, None);

    // Stamp present + PARSED, but the tripping topic is healthy (frames_lost 0).
    let stamp = health_stamp(&[("/ovh/source/out", 0, 0, false, false)], 0);
    let err = replay_with_health(&bag, overflow_factories, None, stamp)
        .expect_err("a clean-stamped provisioning fault stays exit 5");
    match &err {
        ReplayError::Internal { reason } => assert!(
            reason.contains("capture tap lost frames"),
            "got reason: {reason}"
        ),
        other => panic!("expected Internal (capture gap), got {other:?}"),
    }
    assert_eq!(
        err.exit_code(),
        5,
        "clean stamp -> genuine harness loss = exit 5"
    );
}

/// Rule 5e: a lossy stamp on a topic that would otherwise verify
/// BYTE-EXACT (zero real diff) still forces an exit-1 attributed violation —
/// the recording itself failed byte-exactness, so the replay cannot pass.
#[test]
#[serial]
fn lossy_stamp_forces_exit1_on_byte_exact_topic() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("forced.mcap");
    write_bag(&rec, &bag, None);

    // /sr/source/out lossy; /sr/relay/out clean. A plain replay of this bag
    // PASSES byte-exact (pinned by `happy_path_replays_byte_exact_and_passes`).
    let stamp = health_stamp(&[("/sr/source/out", 7, 2, false, false)], 0);
    let outcome = replay_with_health(&bag, source_relay_factories, None, stamp)
        .expect("forced-violation replay does not error");
    assert_sole_tap_loss(&outcome, "/sr/source/out", 7, 2, false);
    assert_eq!(outcome.topics_passed, 1, "the clean sibling still passed");
    assert_eq!(outcome.topics_checked, 2);
}

/// Rule 4: a HEALTHY stamp (all topics frames_lost 0) leaves a clean
/// replay passing (exit 0) and emits NO loud loss warn.
