/// Rule 2: an ABSENT stamp leaves replay behavior BYTE-IDENTICAL — a
/// genuinely lossy DATA recording still surfaces PLAIN data-mismatch labels
/// (NOT relabeled to RecordSideTapLoss) and the report marks the stamp absent.
#[test]
#[serial]
fn absent_stamp_replays_byte_identical_and_reports_absent() {
    let yaml = "name: ov2\nprefix: ov2\nnodes:\n\
        \x20 - id: source\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n";
    let make = || factories(vec![("source", Box::new(SourceNodeEntry::new()))]);
    let rec = record_reference(yaml, make, &[], &[5, 105]); // genuinely lossy: 1 + newest 16.
    assert_eq!(rec.messages["/ov2/source/out"].len(), 17);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("absent.mcap");
    write_bag(&rec, &bag, None);

    let report = dir.path().join("absent.json");
    let outcome = replay_with_health(&bag, make, Some(report.clone()), RecordHealthReport::Absent)
        .expect("absent-stamp lossy-data replay runs");
    assert!(!outcome.passed, "the lossy data still diffs");
    // PLAIN labels: the diverging frames are plain mismatches, NEVER relabeled.
    assert!(
        outcome
            .violations
            .iter()
            .all(|v| !matches!(v.class, ViolationClass::RecordSideTapLoss { .. })),
        "an absent stamp never attributes record-side loss: {:?}",
        outcome.violations
    );
    assert!(
        outcome
            .violations
            .iter()
            .any(|v| v.topic == "/ov2/source/out"),
        "the plain data mismatch names the topic"
    );
    // The report marks the stamp absent (pinned expectation, not a self-compare).
    let json: serde_json::Value = serde_json::from_slice(&std::fs::read(&report).unwrap()).unwrap();
    assert_eq!(json["record_health"]["status"], "absent");
}

/// Rule 3, engine half: a MALFORMED stamp is treated AS ABSENT by the
