    let run = || {
        let stamp = health_stamp(&[("/sr/source/out", 9, 3, false, false)], 0);
        let outcome = replay_with_health(&bag, source_relay_factories, None, stamp)
            .expect("attributed replay runs");
        serde_json::to_string(&outcome).expect("outcome serializes")
    };
