/// The rule-5e GLOBAL catch-all pin — a Present stamp
/// lossy ONLY via `dropped_unwritten` (all topics clean) over a byte-exact
/// replay yields EXACTLY one violation on `(recording)` with the aggregate
/// fields `{frames_lost: 7, gap_events: 0, sequence_anomaly: false}` and the
/// unwritten-drop wording. Reverting the catch-all block makes this replay
/// PASS (exit 0) — the mutation detector.
#[test]
#[serial]
fn global_unwritten_drop_catch_all_forces_exit1() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("global_drop.mcap");
    write_bag(&rec, &bag, None);

    let stamp = health_stamp(
        &[
            ("/sr/source/out", 0, 0, false, false),
            ("/sr/relay/out", 0, 0, false, false),
        ],
        7,
    );
    let outcome = replay_with_health(&bag, source_relay_factories, None, stamp)
        .expect("global-drop replay runs");
    assert!(
        !outcome.passed,
        "a lossy stamp must NEVER produce exit 0 (rule 5e)"
    );
    assert_eq!(
        outcome.violations.len(),
        1,
        "exactly one catch-all violation: {:?}",
        outcome.violations
    );
    let v = &outcome.violations[0];
    assert_eq!(v.topic, "(recording)");
    match v.class {
        ViolationClass::RecordSideTapLoss {
            frames_lost,
            gap_events,
            sequence_anomaly,
        } => assert_eq!(
            (frames_lost, gap_events, sequence_anomaly),
            (7, 0, false),
            "catch-all fields = the unwritten-drop count only"
        ),
        ref other => panic!("expected RecordSideTapLoss, got {other:?}"),
    }
    assert!(
        v.detail.contains("drained but never written to the bag"),
        "the true cause is named: {}",
        v.detail
    );
}

/// The NO-MASKING pin — a stamp lossy ONLY via a global
/// unwritten drop (all topics clean) plus a GENUINE byte divergence on a
/// clean-stamped produced topic keeps that topic's NATURAL class (ByteMismatch,
/// never RecordSideTapLoss) and adds NO `(recording)` entry (a non-empty
/// natural diff suppresses the catch-all — the genuine regression is never
/// masked by the stamp).
#[test]
#[serial]
fn global_drop_does_not_mask_genuine_divergence() {
    let mut rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    // Flip one payload byte of a recorded relay frame (crib of
    // `flipped_payload_byte_is_a_byte_mismatch_violation`): replay reproduces
    // the ORIGINAL byte -> a genuine ByteMismatch on /sr/relay/out.
    rec.messages.get_mut("/sr/relay/out").unwrap()[2][WireHeader::SIZE] ^= 0xFF;
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("no_mask.mcap");
    write_bag(&rec, &bag, None);

    let stamp = health_stamp(
        &[
            ("/sr/source/out", 0, 0, false, false),
            ("/sr/relay/out", 0, 0, false, false),
        ],
        5,
    );
    let outcome =
        replay_with_health(&bag, source_relay_factories, None, stamp).expect("no-mask replay runs");
    assert!(!outcome.passed);
    // The genuine divergence keeps its natural class.
    let relay: Vec<_> = outcome
        .violations
        .iter()
        .filter(|v| v.topic == "/sr/relay/out")
        .collect();
    assert_eq!(
        relay.len(),
        1,
        "the flipped topic diffs naturally: {:?}",
        outcome.violations
    );
    assert!(
        matches!(relay[0].class, ViolationClass::ByteMismatch { .. }),
        "a clean-stamped topic's genuine divergence is NEVER relabeled: {:?}",
        relay[0].class
    );
    // The catch-all is suppressed by the non-empty natural diff.
    assert!(
        outcome.violations.iter().all(|v| v.topic != "(recording)"),
        "no (recording) entry when a natural violation already fails the run: {:?}",
        outcome.violations
    );
}

/// A stamp marking an EXTERNAL (injected, not
/// graph-produced) topic lossy — with `dropped_unwritten: 0` and all produced
/// topics clean — fires the catch-all whose detail NAMES the unverified topic
/// with its counts (never the misleading "0 frame(s) dropped" line) and whose
/// fields aggregate per the documented rule.
#[test]
#[serial]
fn unverified_external_topic_loss_drives_honest_catch_all() {
    let steps = 4;
    let per_step: Vec<f64> = (0..steps).map(|k| (k * 10 + 1) as f64).collect();
    let externals = vec![ExternalDrive::singles("/xr/ext/cam", per_step)];
    let rec = record_uniform(ext_graph_yaml(), ext_relay_factories, &externals, steps);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("ext_lossy.mcap");
    write_bag(&rec, &bag, None);

    // The lossy topic is EXTERNAL: replay re-injects it (never verifies it), so
    // the per-topic relabel loop (produced only) cannot attribute the loss.
    let stamp = health_stamp(&[("/xr/ext/cam", 5, 2, false, false)], 0);
    let outcome =
        replay_with_health(&bag, ext_relay_factories, None, stamp).expect("ext-lossy replay runs");
    assert!(
        !outcome.passed,
        "a lossy stamp must NEVER produce exit 0, even when the loss is on an injected topic"
    );
    assert_eq!(
        outcome.violations.len(),
        1,
        "exactly one catch-all violation: {:?}",
        outcome.violations
    );
    let v = &outcome.violations[0];
    assert_eq!(v.topic, "(recording)");
    match v.class {
        ViolationClass::RecordSideTapLoss {
            frames_lost,
            gap_events,
            sequence_anomaly,
        } => assert_eq!(
            (frames_lost, gap_events, sequence_anomaly),
            (5, 2, false),
            "catch-all fields = the unverified topic's counts (dropped_unwritten 0 adds nothing)"
        ),
        ref other => panic!("expected RecordSideTapLoss, got {other:?}"),
    }
    assert!(
        v.detail.contains("/xr/ext/cam")
            && v.detail.contains("5 frame(s) lost at record")
            && v.detail.contains("unverified by replay"),
        "the detail names the TRUE cause (the unverified topic + its counts): {}",
        v.detail
    );
    assert!(
        !v.detail.contains("drained but never written to the bag"),
        "no misleading unwritten-drop line when dropped_unwritten is 0: {}",
        v.detail
    );
}

/// The rule-8 forged-stamp pin: a Present stamp whose
/// ONLY anomaly is a `multi_publisher` topic stamped INCONSISTENTLY lossy
/// (a correct bagd zeroes mp counts; a forged/buggy writer might not) must be
/// treated as NON-lossy end-to-end: `health_is_lossy` explicitly excludes mp
/// topics (matching both attributors' MultiPublisher precedence), so a
/// byte-exact replay passes (exit 0) with NO RecordSideTapLoss anywhere and NO
/// `(recording)` entry — and, critically, NO debug-build panic (a
/// catch-all firing with an empty cause list would trip its
/// debug_assert; this test runs in debug and would catch that).
#[test]
#[serial]
fn forged_multi_publisher_only_stamp_never_forces_exit1_or_panics() {
    let rec = record_uniform(source_relay_yaml(), source_relay_factories, &[], 4);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("forged_mp.mcap");
    write_bag(&rec, &bag, None);

    // The forged mp row: lossy counts AND multi_publisher=true (contradiction —
    // a correct bagd structurally zeroes these). All real topics clean, no drop.
    let stamp = health_stamp(
        &[
            ("/sr/source/out", 0, 0, false, false),
            ("/sr/relay/out", 0, 0, false, false),
            ("/forged/mp", 9, 4, true, true),
        ],
        0,
    );
    let outcome = replay_with_health(&bag, source_relay_factories, None, stamp)
        .expect("forged-mp-stamped replay runs (and does not panic)");
    assert!(
        outcome.passed,
        "an mp-only 'lossy' stamp never forces exit 1 (rule 8): {:?}",
        outcome.violations
    );
    assert!(outcome.violations.is_empty(), "no violation of any class");
    assert!(
        outcome.violations.iter().all(|v| v.topic != "(recording)"),
        "no (recording) catch-all entry"
    );
}

// ===========================================================================
// Multi-rank bag replay (per-rank demux + k-way merge)
// ===========================================================================

/// Period source firing every OTHER reference step (10 ms vs the 5 ms
/// `DELTA_MS` step) — the empty-rank-bucket edge: on its silent steps, its
/// rank contributes a boundary but ZERO fires to the per-step merge.
#[cerulion_node(period_ms = 10)]
#[derive(Default)]
struct HalfRateSourceNode {
    #[output]
    out: Vector3,
    counter: f64,
}

#[cerulion_node_impl]
impl HalfRateSourceNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.counter += 1.0;
        self.out.x = self.counter;
        Ok(())
    }
}

/// Three-source graph: `src_a1` + `src_a2` (recorded as rank 0) + `src_b`
/// (recorded as rank 1) — ALL at global level 0, so the merged within-level
/// order exercises the full `(level, rank, seq)` tiebreaker chain: two
/// same-rank fires ordered by `seq`, then the cross-rank `rank` tiebreak.
fn mp_three_source_yaml() -> &'static str {
    "name: mpgraph\nprefix: mp\nnodes:\n\
     \x20 - id: src_a1\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: src_a2\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: src_b\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn mp_three_source_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        ("src_a1", Box::new(SourceNodeEntry::new())),
        ("src_a2", Box::new(SourceNodeEntry::new())),
        ("src_b", Box::new(SourceNodeEntry::new())),
    ])
}

/// [`mp_three_source_yaml`] with a SLOW (10 ms) `src_b` — fires only on odd
/// reference steps, leaving rank 1's bucket EMPTY on even steps.
fn mp_slow_b_yaml() -> &'static str {
    "name: mpslow\nprefix: mp2\nnodes:\n\
     \x20 - id: src_a1\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: src_a2\n    type: source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: src_b\n    type: half_rate_source_node\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn mp_slow_b_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        ("src_a1", Box::new(SourceNodeEntry::new())),
        ("src_a2", Box::new(SourceNodeEntry::new())),
        ("src_b", Box::new(HalfRateSourceNodeEntry::new())),
    ])
}

/// The rank a node id is "recorded on" for the multi-rank transforms below.
fn mp_rank_of(id: &str) -> u32 {
    if id == "src_b" {
        1
    } else {
        0
    }
}

/// How the transformed per-rank trace records are laid out in the bag file.
enum MpLayout {
    /// ALL of rank 0's records, then all of rank 1's, … — the bagd ring-block
    /// drain shape (maximal scatter: every rank-1 step-S record sits in file
    /// order AFTER rank 0's final step).
    RankBlocks,
    /// Per-step batches, rank-interleaved: r0 step S, r1 step S, r0 step S+1 …
    /// — rank-1 records land BETWEEN rank-0 steps in file order (the
    /// batch-drain scattered-arrival case).
    PerStepBatches,
}

/// The transformed multi-rank artifacts, returned so the cross-pin test can
/// feed the SAME per-rank streams to the production `merge_partition_traces`.
struct MpBag {
    /// Per-rank manifest node-id tables (index == rank).
    tables: Vec<Vec<String>>,
    /// Per-rank record streams in per-rank emission order (boundary then that
    /// step's fires, per step) — exactly what was written, before layout.
    per_rank: Vec<Vec<TraceRingRecord>>,
}

/// Transform a MONOLITH [`Recording`] into a hand-built MULTI-RANK bag at
/// `path`: FIRE records are re-stamped with their node's rank (`reserved`) and
/// their `node_idx` REMAPPED into the rank's own manifest table; every
/// STEP_BOUNDARY is duplicated once per rank (same step + target — the shared
/// gating-clock trajectory of a lockstep multi-process run); one
/// `trace_manifest_rank{r}.json` attachment per rank; user frames unchanged.
/// `layout` controls the file-order scatter of the per-rank streams.
fn write_multi_rank_bag(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
) -> MpBag {
    write_multi_rank_bag_with(rec, rank_of, rank_count, layout, path, |_| {})
}

/// [`write_multi_rank_bag`] with a `tweak` hook over the demuxed per-rank
/// record streams (run AFTER the transform, BEFORE layout + write) — the
/// corruption/raggedness injector: skew a boundary target, truncate a
/// rank's tail, drop a head boundary.
fn write_multi_rank_bag_with(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    tweak: impl FnOnce(&mut Vec<Vec<TraceRingRecord>>),
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        layout,
        path,
        tweak,
        None,
        None,
        None,
        &[],
        ProducerAttributionFixture::default(),
        None,
        &[],
    )
}

/// [`write_multi_rank_bag_with`] plus the record-time producer
/// labels and the manifest `publishers` table that resolves them — the
/// multi-publisher steering fixture's constructor.
///
/// FREE-RUN, because that is the only coordination under which a cross-rank
/// topic is injected from the read log at all (a lockstep pass plans nothing —
/// `PassVerification::inert`), and steering is the whole point of the labels.
fn write_multi_rank_bag_with_producers(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    path: &std::path::Path,
    producers: ProducerAttributionFixture<'_>,
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        MpLayout::PerStepBatches,
        path,
        |_| {},
        None,
        Some(production_recorder_json(
            replay_engine::CoordinationMode::FreeRun,
        )),
        None,
        &[],
        producers,
        None,
        &[],
    )
}

/// [`write_multi_rank_bag_with`] with node
/// ids OMITTED from every rank manifest (their trace records dropped too) —
/// the unattributable-producer injector.
fn write_multi_rank_bag_unattributed(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    tweak: impl FnOnce(&mut Vec<Vec<TraceRingRecord>>),
    omit_from_manifests: &[&str],
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        layout,
        path,
        tweak,
        None,
        None,
        None,
        omit_from_manifests,
        ProducerAttributionFixture::default(),
        None,
        &[],
    )
}

/// [`write_multi_rank_bag_with`] plus a `__cerulion/flashback.json`
/// attachment DECLARING `anchor.resim_covered_through_ns` — the
/// declared-range-wins precedence injector (a declaration must always beat the
/// multi-rank derivation).
fn write_multi_rank_bag_with_declared_range(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    tweak: impl FnOnce(&mut Vec<Vec<TraceRingRecord>>),
    declared_through_ns: u64,
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        layout,
        path,
        tweak,
        None,
        None,
        Some(declared_through_ns),
        &[],
        ProducerAttributionFixture::default(),
        None,
        &[],
    )
}

/// [`write_multi_rank_bag_with`] plus a `recorder.json`
/// attachment stamping `coordination`, rendered by the PRODUCTION writer (see
/// [`write_bag_with_coordination`] for why it is not hand-built).
///
/// This is the crafted format-4 corpus's constructor: a multi-rank bag is the
/// only shape on which the free-run/lockstep distinction is observable at all.
fn write_multi_rank_bag_coordinated(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    tweak: impl FnOnce(&mut Vec<Vec<TraceRingRecord>>),
    coordination: replay_engine::CoordinationMode,
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        layout,
        path,
        tweak,
        None,
        Some(production_recorder_json(coordination)),
        None,
        &[],
        ProducerAttributionFixture::default(),
        None,
        &[],
    )
}

/// [`write_multi_rank_bag_coordinated`] plus VERBATIM extra attachments: the
/// seam the multi-rank REFUSAL pins use to give a two-rank bag the
/// `state_coverage.json` a real two-worker capture declares.
fn write_multi_rank_bag_coordinated_with_attachments(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    coordination: replay_engine::CoordinationMode,
    extra_attachments: &[(&str, &[u8])],
) -> MpBag {
    write_multi_rank_bag_impl(
        rec,
        rank_of,
        rank_count,
        layout,
        path,
        |_| {},
        None,
        Some(production_recorder_json(coordination)),
        None,
        &[],
        ProducerAttributionFixture::default(),
        None,
        extra_attachments,
    )
}

/// [`write_multi_rank_bag_with`] plus a per-rank manifest `inputs` OVERRIDE:
/// when `Some`, the closure's verbatim JSON replaces the
/// default per-rank filter for that rank's `inputs` key — the injector for a
/// node id appearing in MORE THAN ONE rank's table (a manifest anomaly the
/// verifier warns about and resolves last-wins).
#[allow(clippy::too_many_arguments)]
fn write_multi_rank_bag_impl(
    rec: &Recording,
    rank_of: impl Fn(&str) -> u32,
    rank_count: u32,
    layout: MpLayout,
    path: &std::path::Path,
    tweak: impl FnOnce(&mut Vec<Vec<TraceRingRecord>>),
    inputs_override: Option<&dyn Fn(u32) -> Option<serde_json::Value>>,
    // The `__cerulion/recorder.json` attachment (`None` writes
    // none — the unstamped shape, resolved as INFERRED lockstep).
    recorder_json: Option<Vec<u8>>,
    // A `__cerulion/flashback.json` attachment DECLARING
    // `anchor.resim_covered_through_ns` (`None` writes none — the `--record`
    // continuous-bag shape, which declares nothing).
    flashback_covered: Option<u64>,
    // Node ids OMITTED from every rank
    // manifest AND whose trace records are dropped — the degraded shape where
    // a produced topic's node appears in NO manifest (its fires cannot be
    // written either: their `node_idx` remap has no table entry, exactly as a
    // real bag missing the node's manifest carries no attributable fires).
    omit_from_manifests: &[&str],
    // The producer-attribution pair — see
    // [`ProducerAttributionFixture`]. `default()` writes neither, which is what
    // every earlier arm passes and is byte-identical to before.
    producers: ProducerAttributionFixture<'_>,
    // Per-RANK staging declaration override:
    // `{"capacities": {...}, "scalar": n}`, either key optional. `None` (every
    // pre-existing caller) writes what the ring declared. It exists for the
    // MIXED-REGIME shape, which no recording can produce: one rank stating
    // per-edge rims while another states a legacy global one.
    staging_override: Option<&dyn Fn(u32) -> Option<serde_json::Value>>,
    // One-rank free-run resume: VERBATIM extra attachments
    // (`(name, bytes)`), written after the manifests. `&[]` (every pre-existing
    // caller) writes none. The multi-rank REFUSAL pins need a bag that carries
    // the `state_coverage.json` a real two-worker capture declares, and this
    // writer had no seam for any attachment it did not know by name.
    extra_attachments: &[(&str, &[u8])],
) -> MpBag {
    // Per-rank manifest tables preserve the monolith's node order within each
    // rank (the per-rank recorder writes its own manifest in its own order).
    let mut tables: Vec<Vec<String>> = vec![Vec::new(); rank_count as usize];
    for id in &rec.node_ids {
        if omit_from_manifests.contains(&id.as_str()) {
            continue;
        }
        tables[rank_of(id) as usize].push(id.clone());
    }
    // Re-stamp + demux the monolith trace into per-rank streams.
    let mut per_rank: Vec<Vec<TraceRingRecord>> = vec![Vec::new(); rank_count as usize];
    for r in &rec.trace {
        match r.record_type {
            RECORD_TYPE_STEP_BOUNDARY => {
                for rank in 0..rank_count {
                    let mut b = *r;
                    b.reserved = rank;
                    per_rank[rank as usize].push(b);
                }
            }
            RECORD_TYPE_FIRE | RECORD_TYPE_READ_OUTCOME => {
                // A kind-6 READ-OUTCOME record's
                // `node_idx` is the CONSUMER, manifest-indexed exactly like a
                // FIRE's — same rank stamp + same per-rank-table remap.
                let id = &rec.node_ids[r.node_idx as usize];
                if omit_from_manifests.contains(&id.as_str()) {
                    continue;
                }
                let rank = rank_of(id);
                let mut f = *r;
                f.reserved = rank;
                f.node_idx = tables[rank as usize]
                    .iter()
                    .position(|t| t == id)
                    .expect("node id is in its rank table") as u32;
                per_rank[rank as usize].push(f);
            }
            other => panic!(
                "reference recordings carry only FIRE/BOUNDARY/READ-OUTCOME records, got {other}"
            ),
        }
    }
    // Injector hook (no-op for the plain writer).
    tweak(&mut per_rank);
    // File-order layout (the scatter under test).
    let ordered: Vec<TraceRingRecord> = match layout {
        MpLayout::RankBlocks => per_rank.concat(),
        MpLayout::PerStepBatches => {
            let max_step = rec.trace.iter().map(|r| r.step).max().unwrap_or(0);
            let mut out = Vec::new();
            for s in 0..=max_step {
                for stream in &per_rank {
                    out.extend(stream.iter().filter(|r| r.step == s).copied());
                }
            }
            out
        }
    };

    let topics: Vec<TopicSchema> = rec
        .messages
        .keys()
        .map(|t| TopicSchema {
            topic: t.clone(),
            schema_name: VECTOR3_SCHEMA.to_string(),
            schema_hash: 0,
            wire_fixed_size: 24,
        })
        .collect();
    let mut w = BagWriter::create(path, BagWriterConfig::default(), &topics).unwrap();
    let labels_channel = w.frame_producers_channel_id();
    let label_channels = producer_label_channels(&w, producers.labels);
    w.write_chunk(|c| {
        let max_len = rec.messages.values().map(Vec::len).max().unwrap_or(0);
        for k in 0..max_len {
            for (topic, frames) in &rec.messages {
                let Some(frame) = frames.get(k) else { continue };
                let hdr = WireHeader::read_from_buf(frame);
                let (seq, ts) = hdr.map(|h| (h.sequence, h.timestamp_ns)).unwrap_or((0, 0));
                c.write_message(topic, seq, ts, ts, &[&frame[..]])?;
            }
        }
        for (i, r) in ordered.iter().enumerate() {
            c.write_scheduler_trace(i as u32, r.fire_time_ns, r.fire_time_ns, r)?;
        }
        write_producer_labels(c, labels_channel, &label_channels, producers.labels)?;
        Ok(())
    })
    .unwrap();
    w.write_attachment(
        "graph.yaml",
        "application/yaml",
        0,
        0,
        rec.graph_yaml.as_bytes(),
    )
    .unwrap();
    for (rank, table) in tables.iter().enumerate() {
        let mut manifest_json = serde_json::json!({
            "rank": rank,
            "generation": 0,
            "node_ids": table,
        });
        // When the recording captured the read log,
        // each rank's manifest carries ITS OWN nodes' input lists (what the
        // per-rank bagd manifest stamps from that worker's ring). An
        // override closure can replace a rank's value verbatim
        // (the duplicate-node-id injector).
        // The manifest `publishers` table, written into EVERY
        // rank's manifest. The engine MERGES the tables across ranks into one
        // `token -> node/output` map, so which rank carries an entry cannot
        // change what a token resolves to — and writing it once per rank is
        // what a real per-rank recorder does with its own publishers.
        if let Some(publishers) = &producers.publishers {
            manifest_json["publishers"] = publishers.clone();
        }
        if let Some(value) = inputs_override.and_then(|f| f(rank as u32)) {
            manifest_json["inputs"] = value;
        } else if let Some(inputs) = &rec.input_names {
            let per_rank_inputs: std::collections::BTreeMap<&String, &Vec<String>> = inputs
                .iter()
                .filter(|(node, _)| table.contains(node))
                .collect();
            manifest_json["inputs"] = serde_json::json!(per_rank_inputs);
        }
        // The per-RANK staging declaration. `capacities` and
        // `scalar` are written independently, so a caller can state a per-edge
        // table on one rank and a legacy global scalar on another — the
        // MIXED-REGIME shape, which a recording cannot produce because one
        // recorder writes one regime.
        if let Some(value) = staging_override.and_then(|f| f(rank as u32)) {
            if let Some(caps) = value.get("capacities") {
                manifest_json["read_log_capacities"] = caps.clone();
            }
            if let Some(scalar) = value.get("scalar") {
                manifest_json["read_log_capacity"] = scalar.clone();
            }
        }
        let manifest = serde_json::to_vec(&manifest_json).unwrap();
        w.write_attachment(
            &format!("__cerulion/trace_manifest_rank{rank}.json"),
            "application/json",
            0,
            0,
            &manifest,
        )
        .unwrap();
    }
    if let Some(recorder) = &recorder_json {
        w.write_attachment(
            "__cerulion/recorder.json",
            "application/json",
            0,
            0,
            recorder,
        )
        .unwrap();
    }
    if let Some(through) = flashback_covered {
        // The minimal Flashback-manifest shape `capture_resim_covered_through_ns`
        // reads: `anchor.resim_covered_through_ns`.
        let manifest = serde_json::to_vec(&serde_json::json!({
            "anchor": { "resim_covered_through_ns": through }
        }))
        .unwrap();
        w.write_attachment(
            "__cerulion/flashback.json",
            "application/json",
            0,
            0,
            &manifest,
        )
        .unwrap();
    }
    for (name, bytes) in extra_attachments {
        w.write_attachment(name, "application/json", 0, 0, bytes)
            .unwrap();
    }
    w.finalize().unwrap();
    MpBag { tables, per_rank }
}

#[test]
#[serial]
fn two_rank_block_layout_replays_clean_and_merges_in_canonical_order() {
    // The headline multi-rank pin: a 2-rank bag in the RankBlocks layout
    // (maximal scatter — every rank-1 record sits after rank 0's LAST step)
    // replays CLEAN end-to-end, and the demuxed recorded fire order equals the
    // HAND-computed `(step, global_level, rank, seq)` oracle: per step
    // [src_a1 (r0, seq 0), src_a2 (r0, seq 1), src_b (r1, seq 0)].
    let steps = 5usize;
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    // Anchor the RECORDING to a hand oracle (not a self-compare).
    for k in 0..steps {
        assert_eq!(frame_x(&rec.messages["/mp/src_a1/out"][k]), (k + 1) as f64);
        assert_eq!(frame_x(&rec.messages["/mp/src_b/out"][k]), (k + 1) as f64);
    }

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_blocks.mcap");
    let mp = write_multi_rank_bag(&rec, mp_rank_of, 2, MpLayout::RankBlocks, &bag);
    assert_eq!(mp.tables[0], vec!["src_a1", "src_a2"]);
    assert_eq!(mp.tables[1], vec!["src_b"]);

    let (outcome, fires) = replay_with_tap(&bag, mp_three_source_factories);
    let outcome = outcome.expect("multi-rank replay runs");
    assert!(
        outcome.passed,
        "byte-exact multi-rank replay must pass: {:?}",
        outcome.violations
    );
    assert_eq!(outcome.ticks_replayed, steps);
    assert!(
        outcome.trace_divergence.is_none(),
        "canonical merge must match the monolith re-execution: {:?}",
        outcome.trace_divergence
    );

    // HAND oracle: all three sources are 5 ms Period nodes driven one period
    // per step, so step s fires at t = (s+1)*5ms, level 0, in
    // (rank, seq) order [a1, a2, b].
    let mut oracle: Vec<(u64, usize, String, u64)> = Vec::new();
    for s in 0..steps as u64 {
        let t = (s + 1) * 5_000_000;
        for id in ["src_a1", "src_a2", "src_b"] {
            oracle.push((s, 0, id.to_string(), t));
        }
    }
    let (rec_side, rep_side) = tap_sides(&fires);
    assert_eq!(rec_side, oracle, "demuxed recorded order == hand oracle");
    assert_eq!(rep_side, oracle, "monolith re-execution == hand oracle");
    // The monolith reference recording's own file order is the same sequence
    // (independent resolver — kills a transform bug that also warps the oracle).
    assert_eq!(resolved_fire_oracle(&rec), oracle);

    // CROSS-PIN (one source of ordering truth): the engine's INLINE
    // (level, rank, seq) comparator must equal the PRODUCTION
    // merge_partition_traces over the SAME per-rank streams written to the bag.
    use cerulion_core::scheduler::{merge_partition_traces, ProcessTrace, TraceEntry};
    let per_rank_entries: Vec<Vec<TraceEntry>> = mp
        .per_rank
        .iter()
        .enumerate()
        .map(|(rank, records)| {
            records
                .iter()
                .filter(|r| r.record_type == RECORD_TYPE_FIRE)
                .map(|r| TraceEntry {
                    node_id: Arc::from(mp.tables[rank][r.node_idx as usize].as_str()),
                    step: r.step,
                    fire_time_ns: r.fire_time_ns,
                    global_level: r.global_level as usize,
                    duration_ns: 0,
                    discarded: false,
                })
                .collect()
        })
        .collect();
    let process_traces: Vec<ProcessTrace<'_>> = per_rank_entries
        .iter()
        .enumerate()
        .map(|(rank, trace)| ProcessTrace { rank, trace })
        .collect();
    let merged = merge_partition_traces(&process_traces).expect("distinct ranks");
    let merged_proj: Vec<(u64, usize, String, u64)> = merged
        .iter()
        .map(|e| {
            (
                e.step,
                e.global_level,
                e.node_id.to_string(),
                e.fire_time_ns,
            )
        })
        .collect();
    assert_eq!(
        merged_proj, rec_side,
        "inline (step, level, rank, seq) merge == production merge_partition_traces"
    );

    // Determinism: a second replay of the same multi-rank bag is byte-identical.
    let (outcome2, fires2) = replay_with_tap(&bag, mp_three_source_factories);
    let outcome2 = outcome2.expect("second multi-rank replay runs");
    assert_eq!(
        serde_json::to_string(&outcome).unwrap(),
        serde_json::to_string(&outcome2).unwrap(),
        "two multi-rank replays must produce byte-identical outcomes"
    );
    assert_eq!(fires, fires2, "byte-identical fire streams across replays");
}

#[test]
#[serial]
fn two_rank_per_step_interleave_scattered_arrival_merges_correctly() {
    // The scattered-arrival case the coordinator's bagd model produces: rank-1
    // records land BETWEEN rank-0 steps in file order (per-step batch
    // interleave). The per-rank cursors must reassemble each step across the
    // scatter; the merged order equals the same hand oracle as the block
    // layout (layout must be invisible to the demux).
    let steps = 4usize;
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_interleave.mcap");
    write_multi_rank_bag(&rec, mp_rank_of, 2, MpLayout::PerStepBatches, &bag);

    let (outcome, fires) = replay_with_tap(&bag, mp_three_source_factories);
    let outcome = outcome.expect("interleaved multi-rank replay runs");
    assert!(outcome.passed, "must pass: {:?}", outcome.violations);
    assert!(outcome.trace_divergence.is_none());
    assert_eq!(outcome.ticks_replayed, steps);

    let mut oracle: Vec<(u64, usize, String, u64)> = Vec::new();
    for s in 0..steps as u64 {
        let t = (s + 1) * 5_000_000;
        for id in ["src_a1", "src_a2", "src_b"] {
            oracle.push((s, 0, id.to_string(), t));
        }
    }
    let (rec_side, rep_side) = tap_sides(&fires);
    assert_eq!(rec_side, oracle, "scattered arrival demuxes to the oracle");
    assert_eq!(rep_side, oracle);
}

#[test]
#[serial]
fn empty_rank_step_contributes_no_fires_without_stall_or_misorder() {
    // The empty-rank edge: src_b (rank 1) is a 10 ms Period node driven at
    // 5 ms per step, so it fires ONLY on odd steps — on even steps rank 1
    // contributes a boundary and ZERO fires. The merge must neither stall on
    // the empty bucket nor misorder the surviving rank-0 fires.
    let steps = 4usize;
    let rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    // Anchor: b fired exactly on steps 1 and 3 (frames x = 1.0, 2.0).
    let b_frames = &rec.messages["/mp2/src_b/out"];
    assert_eq!(b_frames.len(), 2, "slow source fires every other step");
    assert_eq!(frame_x(&b_frames[0]), 1.0);
    assert_eq!(frame_x(&b_frames[1]), 2.0);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_empty_rank.mcap");
    write_multi_rank_bag(&rec, mp_rank_of, 2, MpLayout::PerStepBatches, &bag);

    let (outcome, fires) = replay_with_tap(&bag, mp_slow_b_factories);
    let outcome = outcome.expect("empty-rank multi-rank replay runs");
    assert!(outcome.passed, "must pass: {:?}", outcome.violations);
    assert!(outcome.trace_divergence.is_none());
    assert_eq!(outcome.ticks_replayed, steps, "no stall on empty buckets");

    // HAND oracle: a1 + a2 fire every step at t = (s+1)*5ms; b fires only on
    // odd steps, at its period boundary (== that step's advanced clock).
    let mut oracle: Vec<(u64, usize, String, u64)> = Vec::new();
    for s in 0..steps as u64 {
        let t = (s + 1) * 5_000_000;
        oracle.push((s, 0, "src_a1".to_string(), t));
        oracle.push((s, 0, "src_a2".to_string(), t));
        if s % 2 == 1 {
            oracle.push((s, 0, "src_b".to_string(), t));
        }
    }
    let (rec_side, rep_side) = tap_sides(&fires);
    assert_eq!(rec_side, oracle, "empty buckets skip cleanly, order intact");
    assert_eq!(rep_side, oracle);
}

// ===========================================================================
// Cross-rank boundary AGREEMENT (validate_step_boundaries
// phase 2 — refused BEFORE the first replay step, exit 2)
// ===========================================================================

#[test]
#[serial]
fn skewed_shared_step_boundary_is_refused_exit_2_before_any_replay_step() {
    // Oracle-vector: a 2-rank bag whose rank-1 STEP_BOUNDARY at shared step 2
    // is skewed +1 ns must be refused with the agreement error naming the
    // step, both ranks, and BOTH values — and BEFORE any replay step ran (the
    // fire tap observes nothing: phase 2 precedes the loop). Deleting the
    // phase-2 check makes this bag replay (the skew is invisible to every
    // other gate: rank-1's stream stays non-decreasing, its fires stay ≤ its
    // boundaries, and checks 3+4 only read rank-0 targets).
    let steps = 5usize;
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_skewed_boundary.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::RankBlocks,
        &bag,
        |per_rank| {
            let skewed = per_rank[1]
                .iter_mut()
                .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == 2)
                .expect("rank 1 has a step-2 boundary");
            skewed.fire_time_ns += 1; // 15_000_000 -> 15_000_001
        },
    );

    let (outcome, fires) = replay_with_tap(&bag, mp_three_source_factories);
    let err = outcome.expect_err("skewed shared-step boundary must refuse");
    match &err {
        ReplayError::RecordingInconsistent { detail } => {
            assert!(
                detail.contains("cross-rank boundary disagreement at step 2"),
                "names the step: {detail}"
            );
            assert!(
                detail.contains("rank 0") && detail.contains("rank 1"),
                "names both ranks: {detail}"
            );
            assert!(
                detail.contains("15000000") && detail.contains("15000001"),
                "names both values: {detail}"
            );
        }
        other => panic!("expected RecordingInconsistent (agreement), got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2, "a bag fault is exit 2, never exit 6");
    // Phase-ordering pin: the refusal fired BEFORE the first replay step —
    // the fire tap (fed only inside the replay loop) observed NOTHING.
    assert!(
        fires.is_empty(),
        "agreement refusal must precede any replay step, but the tap saw {} fires",
        fires.len()
    );
}

#[test]
#[serial]
fn ragged_tail_shorter_rank0_stream_is_tolerated_and_replays_clean() {
    // The recorder's shutdown contract tolerates ragged TAILS: mp_record_e2e
    // (`mp_record_e2e_one_bag_rank_stamped_lockstep_and_manifests`, assertion
    // (e)) asserts cross-rank equality ONLY on steps present in BOTH ranks
    // (`t1.get(step)` guard) and never pins equal-length streams — a worker
    // can exit between quanta at SIGINT. Model it: rank 0 stopped after step
    // 2 while rank 1 recorded through step 3. The agreement check must pass
    // over the shared prefix (same phase-2 path the negative arms refuse
    // through) and the replay window is rank 0's stream (3 steps); rank 1's
    // trailing records fall outside it and are never pulled.
    let steps = 4usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    // Trim the recorded frames to the rank-0 window (ts <= step-2 target,
    // 15 ms) — the frames a 3-step re-execution reproduces.
    for frames in rec.messages.values_mut() {
        frames.retain(|f| {
            WireHeader::read_from_buf(f)
                .map(|h| h.timestamp_ns <= 15_000_000)
                .unwrap_or(false)
        });
    }
    assert_eq!(rec.messages["/mp2/src_a1/out"].len(), 3);
    assert_eq!(
        rec.messages["/mp2/src_b/out"].len(),
        1,
        "slow b fired once by 15 ms"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_tail.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            // Rank 0 fell silent after step 2 (boundary + its fires dropped);
            // rank 1 keeps its full 0..=3 stream — the ragged tail.
            per_rank[0].retain(|r| r.step <= 2);
        },
    );

    let (outcome, fires) = replay_with_tap(&bag, mp_slow_b_factories);
    let outcome = outcome.expect("ragged-tail bag must replay (tail tolerated)");
    assert!(outcome.passed, "must pass: {:?}", outcome.violations);
    assert!(outcome.trace_divergence.is_none());
    assert_eq!(
        outcome.ticks_replayed, 3,
        "replay window == rank 0's boundary stream, not rank 1's longer one"
    );

    // HAND oracle over the 3-step window: a1 + a2 every step; slow b at step 1.
    let mut oracle: Vec<(u64, usize, String, u64)> = Vec::new();
    for s in 0..3u64 {
        let t = (s + 1) * 5_000_000;
        oracle.push((s, 0, "src_a1".to_string(), t));
        oracle.push((s, 0, "src_a2".to_string(), t));
        if s == 1 {
            oracle.push((s, 0, "src_b".to_string(), t));
        }
    }
    let (rec_side, rep_side) = tap_sides(&fires);
    assert_eq!(rec_side, oracle, "rank 1's trailing records never pulled");
    assert_eq!(rep_side, oracle);
    // A DERIVED range with nothing beyond it is DROPPED, not
    // reported — this arm's frames were trimmed to the rank-0 window, so a
    // `covered_range` here would be report noise on every already-shipping
    // clean multi-rank bag (the byte-identity claim). Pins the derived+empty
    // early return; a DECLARED range still always reports.
    assert_eq!(
        outcome.covered_range, None,
        "a clean multi-rank lockstep bag reports no covered range"
    );
}

/// THE HEADLINE: a peer rank's final-step FRAME past rank 0's last
/// boundary replays CLEAN under the derived covered range.
///
/// The shape `mp_split_pair_e2e_test` produces: at SIGINT a
/// departing rank's barrier participant `Drop` opens the barrier, so rank 1
/// completes one more step than rank 0 — its ring carries boundary+fires for
/// step 3 (the boundary gate tolerates the peer-longer tail explicitly) and
/// its topic carries a frame stamped step 3's target, which matches NOTHING in
/// rank 0's authoritative stream. Frames stamp their step's boundary target
/// exactly, so the margin is zero by construction and this bag exits 2
/// ("matches NO recorded STEP_BOUNDARY target") without the derived
/// range: one engine, two gates, disagreeing about one tolerated window
/// (the ragged-tail class).
///
/// This is `ragged_tail_shorter_rank0_stream_is_tolerated_and_replays_clean`
/// WITHOUT that test's frame trim: rank 1's step-3 frame stays in the bag, as
/// a real recorder writes it. Assertions close each way the tolerance could be
/// hollow: it COMPLETES (exit 0, the defect itself); the replay window is
/// still rank 0's (a "fix" that replayed rank 1's longer window would move the
/// clock); the range is REPORTED as DERIVED with the trailing frame counted
/// (never silent, never claimed as a declaration); the verdict is CLEAN (the
/// deduction reached the diff — no MissingMessages for the trailing frame);
/// and the rendered note names the CAUSE — a healthy multi-process shutdown —
/// not the user's recording.
#[test]
#[serial]
fn mp_peer_longer_tail_frame_replays_clean_with_derived_covered_range() {
    let steps = 4usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    // Rank-0 topics: trim to the rank-0 window (<= step-2 target, 15 ms) — a
    // rank-0 worker that stopped after step 2 committed nothing later (its
    // boundary is written to its ring BEFORE its frames commit, so its own
    // frames can never out-run its own stream).
    for (topic, frames) in rec.messages.iter_mut() {
        if topic != "/mp2/src_b/out" {
            frames.retain(|f| {
                WireHeader::read_from_buf(f)
                    .map(|h| h.timestamp_ns <= 15_000_000)
                    .unwrap_or(false)
            });
        }
    }
    // Rank 1 (src_b) keeps its FULL frame set: fired at steps 1 and 3, so its
    // step-3 frame is stamped 20 ms — one step past rank 0's last boundary.
    assert_eq!(
        rec.messages["/mp2/src_b/out"].len(),
        2,
        "slow b fired at steps 1 and 3"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_peer_longer_tail.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            // Rank 0 fell silent after step 2; rank 1 keeps its full 0..=3
            // stream — the tolerated peer-longer ragged tail.
            per_rank[0].retain(|r| r.step <= 2);
        },
    );

    let outcome = replay(&bag, mp_slow_b_factories, None, None)
        .expect("a peer-longer tail frame is a shutdown artifact, not corruption");
    assert_clean_verdict(&outcome, "peer-longer tail");
    assert_eq!(
        outcome.ticks_replayed, 3,
        "the replay window is still rank 0's boundary stream"
    );
    let range = outcome
        .covered_range
        .as_ref()
        .expect("the derived range is reported, never silent");
    assert!(
        range.derived,
        "the reader derived this range; the bag declared nothing"
    );
    assert_eq!(
        range.through_ns, 15_000_000,
        "the derived range is rank 0's LAST boundary target, not rank 1's longer stream's"
    );
    assert_eq!(
        range.trailing_frames.get("/mp2/src_b/out").copied(),
        Some(1),
        "the step-3 frame is in the bag and outside the range: {:?}",
        range.trailing_frames
    );
    assert_eq!(range.trailing_frames.len(), 1, "no other topic has a tail");

    // Never silent, and the note names the CAUSE (a healthy mp shutdown) with
    // the DERIVED wording — never the declared-capture wording, never a word
    // that blames the user's recording.
    let verdict = replay_engine::render_verdict(&outcome, &bag);
    assert!(
        verdict.contains("cut independently at shutdown"),
        "the derived note names its cause: {verdict}"
    );
    assert!(
        verdict.contains("/mp2/src_b/out (1)"),
        "the note names the trailing topic and count: {verdict}"
    );
    assert!(
        !verdict.contains("this capture's resume covered"),
        "a derived range must not render as a declared one: {verdict}"
    );
    assert!(
        !verdict.contains("re-record"),
        "a healthy recording is never told to re-record: {verdict}"
    );
}

/// The tail is UNBOUNDED — a `--peer-loss continue` survivor
/// out-stepping a dead rank 0 for many steps is the same tolerated shape, so
/// the derived range must forgive a WIDE tail, not one quantum of slack.
///
/// Kills any bounded-slack implementation: rank 1 records nine steps past
/// rank 0's end and five trailing frames, all forgiven and all counted.
#[test]
#[serial]
fn mp_peer_longer_tail_is_unbounded_not_one_quantum() {
    let steps = 12usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    for (topic, frames) in rec.messages.iter_mut() {
        if topic != "/mp2/src_b/out" {
            frames.retain(|f| {
                WireHeader::read_from_buf(f)
                    .map(|h| h.timestamp_ns <= 15_000_000)
                    .unwrap_or(false)
            });
        }
    }
    // Slow b fires on odd steps 1,3,5,7,9,11 → six frames, five past 15 ms.
    assert_eq!(rec.messages["/mp2/src_b/out"].len(), 6);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_peer_longer_wide_tail.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            per_rank[0].retain(|r| r.step <= 2);
        },
    );

    let outcome = replay(&bag, mp_slow_b_factories, None, None)
        .expect("a nine-step survivor tail is the same tolerated shape as a one-step one");
    assert_clean_verdict(&outcome, "wide peer-longer tail");
    assert_eq!(outcome.ticks_replayed, 3);
    let range = outcome
        .covered_range
        .as_ref()
        .expect("derived range reported");
    assert!(range.derived);
    assert_eq!(range.through_ns, 15_000_000);
    assert_eq!(
        range.trailing_frames.get("/mp2/src_b/out").copied(),
        Some(5),
        "all five trailing frames forgiven AND counted: {:?}",
        range.trailing_frames
    );
}

/// The derived forgiveness is SCOPED to PEER-OWNED topics —
/// a RANK-0-owned topic's frame one step past rank 0's last recorded boundary
/// still refuses exit 2, in the same bag whose peer tail is being tolerated.
///
/// Reachability adjudication (why refusing is right): a rank-0 frame past
/// rank 0's own last boundary is UNREACHABLE on any finalized
/// continuous-recording bag — the
/// worker pushes STEP_BOUNDARY(k) into its own ring BEFORE any step-k
/// publish, the recorder's writer drains rings only AFTER the batch's tap
/// frames were consumed, finalize runs a ring-only tail drain, and the one
/// early-ring-cut path (a ring overrun) deliberately un-finalizes the bag.
/// So this shape is a hand-edit (or a future recorder regression that broke
/// the batch discipline the scoping depends on — in which case a LOUD refusal
/// here is the tripwire), never a shutdown artifact. Without the scoping,
/// forgiving it would mask exactly that corruption class, which is
/// what this arm pins.
#[test]
#[serial]
fn mp_derived_forgiveness_is_scoped_to_peer_owned_topics() {
    let steps = 4usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    // Trim ONLY src_a2 to the rank-0 window; src_a1 (RANK-0-owned) keeps its
    // genuine step-3 frame stamped 20 ms — one step past rank 0's truncated
    // boundary stream, the exact forged/incoherent shape. src_b (rank 1)
    // keeps its full set — its 20 ms frame is a legitimate peer tail.
    let frames = rec.messages.get_mut("/mp2/src_a2/out").unwrap();
    frames.retain(|f| {
        WireHeader::read_from_buf(f)
            .map(|h| h.timestamp_ns <= 15_000_000)
            .unwrap_or(false)
    });
    assert_eq!(
        rec.messages["/mp2/src_a1/out"].len(),
        4,
        "a1 keeps its 20 ms frame"
    );
    assert_eq!(
        rec.messages["/mp2/src_b/out"].len(),
        2,
        "b keeps its 20 ms tail"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_rank0_tail_forged.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            per_rank[0].retain(|r| r.step <= 2);
        },
    );

    let err = replay(&bag, mp_slow_b_factories, None, None)
        .expect_err("a rank-0 frame past rank 0's own stream is never a shutdown artifact");
    match &err {
        ReplayError::RecordingInconsistent { detail } => assert!(
            detail.contains("matches NO recorded STEP_BOUNDARY target")
                && detail.contains("frame 3")
                && detail.contains("/mp2/src_a1/out"),
            "the fault names the rank-0 topic's tail frame, got: {detail}"
        ),
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
}

/// A produced topic whose node appears in NO
/// rank manifest gets NO forgiveness — the `derived_tail_topics` filter's
/// `None` arm is the ONLY guard on this path, and this arm pins it.
///
/// Under lockstep `build_rank_plans` synthesizes ONE full-graph manifest, so
/// the free-run unattributable-node refusal never runs here: a bag whose
/// per-rank trace manifests omit a producing node reaches
/// `resolve_covered_range` with `produced_topic_ranks[topic] == None`, and a
/// check that cannot attribute must not forgive. The bag: src_b omitted from
/// every manifest (its fires dropped with it — a real bag missing the node's
/// manifest carries no attributable fires), rank 0's stream truncated to step
/// 2, src_b's topic still carrying its 20 ms frame past rank 0's last
/// boundary. Flipping the filter to forgive
/// unattributables (`match rank { Some(0) => None, _ => Some(topic) }`)
/// forgives the frame and this arm's `expect_err` panics.
#[test]
#[serial]
fn mp_an_unattributable_producers_tail_frame_is_not_forgiven() {
    let steps = 4usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    for (topic, frames) in rec.messages.iter_mut() {
        if topic != "/mp2/src_b/out" {
            frames.retain(|f| {
                WireHeader::read_from_buf(f)
                    .map(|h| h.timestamp_ns <= 15_000_000)
                    .unwrap_or(false)
            });
        }
    }
    assert_eq!(
        rec.messages["/mp2/src_b/out"].len(),
        2,
        "src_b keeps its 20 ms frame past rank 0's truncated stream"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_unattributable_producer.mcap");
    write_multi_rank_bag_unattributed(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            per_rank[0].retain(|r| r.step <= 2);
        },
        &["src_b"],
    );

    let err = replay(&bag, mp_slow_b_factories, None, None)
        .expect_err("a check that cannot attribute a producer must not forgive its tail");
    match &err {
        ReplayError::RecordingInconsistent { detail } => assert!(
            detail.contains("matches NO recorded STEP_BOUNDARY target")
                && detail.contains("/mp2/src_b/out"),
            "the fault names the unattributable topic's tail frame, got: {detail}"
        ),
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
}

/// THE ANTI-MASKING CONTROL: the derived range forgives the TAIL,
/// never a frame INSIDE it — a tampered mid-recording stamp still refuses
/// exit 2, in the same bag whose peer-longer tail is being tolerated.
///
/// Frames stamp their step's boundary target, so a torn/hand-edited mid-bag
/// batch produces stamps at or below the last boundary that match nothing —
/// exactly what check 3 exists to catch, and exactly what a tail-only
/// forgiveness can never reach.
#[test]
#[serial]
fn mp_derived_range_still_refuses_a_mid_bag_frame_matching_no_boundary() {
    let steps = 4usize;
    let mut rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    for (topic, frames) in rec.messages.iter_mut() {
        if topic != "/mp2/src_b/out" {
            frames.retain(|f| {
                WireHeader::read_from_buf(f)
                    .map(|h| h.timestamp_ns <= 15_000_000)
                    .unwrap_or(false)
            });
        }
    }
    // Tamper src_a1's SECOND frame to 7 ms — inside the derived range (15 ms),
    // matching no boundary target (5, 10, 15, …), monotonicity preserved
    // (5 < 7 < 15) so the only gate that can refuse it is check 3 at full
    // strength inside the range.
    let frames = rec.messages.get_mut("/mp2/src_a1/out").unwrap();
    frames[1][24..32].copy_from_slice(&7_000_000u64.to_le_bytes());

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_torn_inside_range.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            per_rank[0].retain(|r| r.step <= 2);
        },
    );

    let err = replay(&bag, mp_slow_b_factories, None, None)
        .expect_err("the derived range forgives the TAIL, never a frame inside it");
    match &err {
        ReplayError::RecordingInconsistent { detail } => assert!(
            detail.contains("matches NO recorded STEP_BOUNDARY target")
                && detail.contains("frame 1")
                && detail.contains("/mp2/src_a1/out"),
            "the fault names the mid-bag frame, got: {detail}"
        ),
        other => panic!("expected RecordingInconsistent, got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
}

/// A DECLARED range always beats the derivation, and the
/// clamp/refusal contract is untouched on a multi-rank bag.
///
/// The bag declares 15 ms while its trace's last rank-0 boundary is 20 ms —
/// an UNDERSTATEMENT, clamped UP exactly as on a single-rank capture — and
/// the report must say DECLARED (`derived == false`), because the bag really
/// did make this claim.
#[test]
#[serial]
fn mp_declared_range_wins_over_the_derivation() {
    let steps = 4usize;
    let rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_declared_range.mcap");
    write_multi_rank_bag_with_declared_range(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |_| {},
        15_000_000,
    );

    let outcome = replay(&bag, mp_slow_b_factories, None, None)
        .expect("a declared understatement is clamped, never refused");
    assert_clean_verdict(&outcome, "declared range on a multi-rank bag");
    let range = outcome
        .covered_range
        .as_ref()
        .expect("a declared range is always reported");
    assert!(
        !range.derived,
        "the bag DECLARED this range; the reader must not claim to have derived it"
    );
    assert_eq!(
        range.through_ns, 20_000_000,
        "the clamp-up to the trace's own last boundary holds on a multi-rank bag"
    );
    assert!(
        range.trailing_frames.is_empty(),
        "nothing falls outside the clamped range"
    );
}

#[test]
#[serial]
fn ragged_head_late_starting_peer_is_refused_exit_2() {
    // "Tails only": every worker's ring is armed BEFORE GO (the step-0 capture
    // contract — mp_record_e2e pins 0-based gap-free boundary streams per
    // rank), so a peer stream STARTING late is corruption, not shutdown
    // raggedness. Refused naming both first steps, before any replay step.
    let steps = 3usize;
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_head.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            // Drop ONLY rank 1's step-0 boundary: its stream becomes {1, 2} —
            // still consecutive + non-decreasing (phase 1 passes), but late.
            per_rank[1].retain(|r| !(r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == 0));
        },
    );

    let (outcome, fires) = replay_with_tap(&bag, mp_three_source_factories);
    let err = outcome.expect_err("late-starting peer stream must refuse");
    match &err {
        ReplayError::RecordingInconsistent { detail } => {
            assert!(
                detail.contains("start apart"),
                "names the head-mismatch class: {detail}"
            );
            assert!(
                detail.contains("rank 0's first STEP_BOUNDARY is step 0")
                    && detail.contains("rank 1's is step 1"),
                "names both first steps: {detail}"
            );
        }
        other => panic!("expected RecordingInconsistent (ragged head), got {other:?}"),
    }
    assert_eq!(err.exit_code(), 2);
    assert!(fires.is_empty(), "refusal precedes any replay step");
}

// ===========================================================================
// Rank-aware divergence tuples (additive diagnostics)
// ===========================================================================

#[test]
#[serial]
fn two_rank_divergence_tuple_carries_the_diverging_rank() {
    // Oracle-vector: tamper rank 1's step-2 FIRE time (-1 ns) in an otherwise
    // clean 2-rank bag. The divergence lands on src_b — rank 1's stream — and
    // the report must SAY so: both tuples carry rank 1, the detail names
    // "(rank 1)" (the diagnostic convention), and the --report JSON
    // serializes the additive `"rank":1` field.
    let steps = 4usize;
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_rank_divergence.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            let f = per_rank[1]
                .iter_mut()
                .find(|r| r.record_type == RECORD_TYPE_FIRE && r.step == 2)
                .expect("rank 1 fires at step 2");
            f.fire_time_ns -= 1; // 15_000_000 -> 14_999_999 (still <= boundary)
        },
    );

    let outcome = replay(&bag, mp_three_source_factories, None, None).expect("replay runs");
    let div = outcome
        .trace_divergence
        .as_ref()
        .expect("tampered rank-1 fire time must structurally diverge");
    // Per-step canonical order is [a1(r0), a2(r0), b(r1)] → the tampered b at
    // step 2 sits at position 2*3 + 2 = 8.
    assert_eq!(div.position, 8, "divergence at rank 1's step-2 fire");
    let recorded = div.recorded.as_ref().expect("recorded side present");
    let replayed = div.replayed.as_ref().expect("replayed side present");
    assert_eq!(recorded.node_id, "src_b");
    assert_eq!(
        recorded.rank,
        Some(1),
        "the recorded tuple names the rank whose stream diverged"
    );
    assert_eq!(
        replayed.rank,
        Some(1),
        "the replayed tuple carries the node's recording-ownership rank"
    );
    assert!(
        div.detail.contains("(rank 1)"),
        "detail names the rank (the diagnostic convention): {}",
        div.detail
    );
    // The --report JSON serializes the ADDITIVE rank field.
    let json = serde_json::to_string(&div).unwrap();
    assert!(
        json.contains("\"rank\":1"),
        "report JSON carries the additive rank field: {json}"
    );
}

#[test]
#[serial]
fn ragged_tail_over_fire_is_tolerated_not_a_divergence() {
    // A ragged tail is TOLERATED, not reported as an exit-6 divergence:
    // rank 0's stream runs LONGER than rank 1's (rank 1 fell silent after step
    // 2), so the monolith re-execution legitimately re-fires src_b at step 3
    // while the recording lacks it. The structural over-fire that produces IS
    // the SAME tolerated window the boundary gate accepts, so the trace gate
    // CLEARS it (rather than reporting exit 6) — which makes the trace
    // gate AGREE with the frame gate. Data stays byte-clean (frames intact),
    // and the tolerance is RECORDED in the report (never silent).
    //
    // This fixture is classified as the fire-less-final-step shape, and the arm pins that
    // wording. `src_b` is a HALF-RATE node (it fires at steps 1 and 3), so
    // rank 1's last recorded step — step 2 — banked a boundary and no fires. That
    // is the fire-less-final-step shape byte for byte: nothing in the recording
    // distinguishes "step 2 ran and src_b's period simply did not hit" from "the
    // worker exited between banking boundary 2 and running step 2's fires",
    // because only a SUCCESSOR boundary can prove a step completed and rank 1 has
    // none. So the window opens after step 1 rather than step 2 — one step wider —
    // and the note names that cause instead of the peer-tail one.
    //
    // The widening is INERT here, which is why this stays a ragged-tail arm: src_b's
    // period means the monolith fires nothing at step 2, so the tolerated set is
    // still exactly `{step 3}` and the fire count below pins it (a regression that
    // widened the SKIP set, not just the window, would fail that assertion). The
    // peer-tail wording stays pinned by the three sibling arms whose final
    // recorded step DOES bank a fire (`..._two_step_wide_interleaved_...` and the
    // two held-input arms), all of which use the every-step `src_b`.
    let steps = 4usize;
    let rec = record_uniform(mp_slow_b_yaml(), mp_slow_b_factories, &[], steps);
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_tail_divergence.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            // Rank 1 exited between quanta after step 2: drop its step-3
            // boundary AND its step-3 fire (src_b fires at steps 1 and 3).
            per_rank[1].retain(|r| r.step <= 2);
        },
    );

    let outcome = replay(&bag, mp_slow_b_factories, None, None).expect("replay runs");
    // Frames are all present (untouched) so the DATA side is clean; the
    // ragged tail's over-fire is TOLERATED, not a divergence → EXIT 0.
    assert!(
        outcome.passed,
        "the ragged-tail over-fire must be tolerated (exit 0): trace={:?} violations={:?}",
        outcome.trace_divergence, outcome.violations
    );
    assert!(
        outcome.trace_divergence.is_none(),
        "the tail re-fire is tolerated, NOT reported as a structural divergence: {:?}",
        outcome.trace_divergence
    );
    assert!(outcome.violations.is_empty(), "{:?}", outcome.violations);
    // The tolerance is recorded (never silent): a STRUCTURAL note naming rank 1,
    // its recorded end (step 2), the re-fired node, and the
    // fire-less-final-step cause rather than the peer-tail one (see the header).
    assert_eq!(
        outcome.tolerated_ragged_tails.len(),
        1,
        "exactly the one structural tail tolerance is recorded: {:?}",
        outcome.tolerated_ragged_tails
    );
    let note = &outcome.tolerated_ragged_tails[0];
    assert!(
        note.contains("structural")
            && note.contains("rank 1")
            && note.contains("ends at step 2")
            && note.contains("'src_b'")
            && note.contains("no fires behind it"),
        "the structural tolerance note attributes the tail: {note}"
    );
    assert!(
        note.contains("across steps 3..=3 (1 fire(s))"),
        "the WINDOW widened by one step but the tolerated SET did not — src_b's \
         period fires nothing at step 2: {note}"
    );
    // THIS fixture is why the note may not assert a shutdown: `src_b` is
    // half-rate, so its final recorded step is quiet because the node's period
    // said so — a HEALTHY graceful stop. A note claiming "the worker shut down"
    // would be affirmatively wrong here.
    assert!(
        note.contains(
            "either the step ran and fired nothing, or the worker shut down between the \
             step boundary and the step's fires — the recording cannot tell which"
        ),
        "the cause is an either/or, never an assertion the recording cannot support: {note}"
    );
}

#[test]
#[serial]
fn ragged_tail_two_step_wide_interleaved_re_fire_is_tolerated_not_exit_6() {
    // THE INTERLEAVED-TAIL SHAPE (`mp_recorded_bag_replays_to_exit_0_multi_rank`):
    // the simple over-fire tolerance (the test above) clears a PURE trailing
    // over-fire (recorded side exhausted). But a ≥2-step ragged tail makes the
    // short rank's re-fires INTERLEAVE against the longer rank's LATER recorded
    // entries in the (step, global_level, rank, seq) k-way merge — the recorded
    // stream has rank 0's step-S+1 fire next while replay legitimately emits
    // rank 1's re-fired step-S tail fire first. Compared naively that surfaces as a TUPLE
    // mismatch (recorded src_a1@step4 vs replayed src_b@step3) and returns
    // exit 6 — a flake. The comparator skips
    // the in-window re-fires → exit 0.
    //
    // Reverting the `is_tail_refire` skip in `TraceDiffStream`
    // (advance + the feed_step trailing-skip) makes this exit 6.
    let steps = 5usize; // rank 0 records steps 0..=4.
    let rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_tail_2step.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| {
            // Rank 1 exited between quanta after step 2 — drop its step-3 AND
            // step-4 trace (boundaries + fires): a TWO-step ragged tail. Rank 0
            // keeps its full 0..=4 stream (auth = 4, tail_width(rank 1) = 2), so
            // the monolith re-fires src_b at BOTH step 3 and step 4 — the
            // interleave a post-hoc clear never catches. Frames are left
            // untouched (byte-clean data side) to ISOLATE the trace-order flake.
            per_rank[1].retain(|r| r.step <= 2);
        },
    );

    let outcome = replay(&bag, mp_three_source_factories, None, None).expect("replay runs");
    assert!(
        outcome.passed,
        "the 2-step ragged tail's interleaved re-fires must be tolerated (exit 0): \
         trace={:?} violations={:?}",
        outcome.trace_divergence, outcome.violations
    );
    assert!(
        outcome.trace_divergence.is_none(),
        "the interleaved tail re-fire is tolerated, NOT an exit-6 structural divergence: {:?}",
        outcome.trace_divergence
    );
    assert!(outcome.violations.is_empty(), "{:?}", outcome.violations);
    assert_eq!(
        outcome.ticks_replayed, 5,
        "replay window == rank 0's 5-step boundary stream"
    );
    // The tolerance is recorded once for rank 1, naming BOTH re-fired steps (the
    // 2-step tail: src_b re-fired at steps 3 AND 4).
    assert_eq!(
        outcome.tolerated_ragged_tails.len(),
        1,
        "one aggregated structural tolerance for the one ragged rank: {:?}",
        outcome.tolerated_ragged_tails
    );
    let note = &outcome.tolerated_ragged_tails[0];
    assert!(
        note.contains("structural")
            && note.contains("rank 1")
            && note.contains("ended at step 2")
            && note.contains("'src_b'")
            && note.contains("2 fire(s) across steps 3..=4")
            && note.contains("ragged shutdown tail"),
        "the structural tolerance note names the 2-step interleaved tail: {note}"
    );
}

// ===========================================================================
// The FRAME diff tolerates the ragged-shutdown-tail re-fire the trace
// gate tolerates. Oracle-based; the ragged tail is crafted to MIRROR the real
// SIGINT shape (rank 1's trace tail AND its produced frames both truncated).
// ===========================================================================

#[test]
#[serial]
fn ragged_tail_re_fire_tolerated_across_both_gates_replays_clean() {
    // THE headline ragged-tail pin: a 2-rank bag whose rank-1 (src_b) recorded
    // stream ends ONE step before rank 0's — trace tail AND frames both
    // truncated, exactly the SIGINT shape. The monolith re-fires src_b past the
    // recording's end, producing ONE extra trailing frame on /mp/src_b/out. The
    // trace gate clears the over-fire AND the frame diff tolerates the trailing
    // extra → EXIT 0, with BOTH tolerances recorded.
    let steps = 4usize; // src_b (rank 1) fires every step 0..=3.
    let mut rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    assert_eq!(rec.messages["/mp/src_b/out"].len(), 4);
    // SIGINT dropped rank 1's step-3 FRAME (the tap shut down with the worker).
    rec.messages.get_mut("/mp/src_b/out").unwrap().truncate(3);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_both_gates.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        // …and rank 1's step-3 trace (boundary + fire): the whole step is gone.
        |per_rank| per_rank[1].retain(|r| r.step <= 2),
    );

    let outcome = replay(&bag, mp_three_source_factories, None, None).expect("replay runs");
    assert!(
        outcome.passed,
        "the ragged-tail re-fire is tolerated at BOTH gates (exit 0): trace={:?} violations={:?}",
        outcome.trace_divergence, outcome.violations
    );
    assert!(outcome.trace_divergence.is_none());
    assert!(outcome.violations.is_empty(), "{:?}", outcome.violations);
    assert_eq!(
        outcome.ticks_replayed, steps,
        "replay ran rank 0's full window"
    );
    // BOTH tolerances recorded: the structural over-fire clear AND the frame
    // trailing-extra tolerance, the latter naming the topic + rank + counts.
    let frame_note = outcome
        .tolerated_ragged_tails
        .iter()
        .find(|n| n.starts_with("frame:"))
        .unwrap_or_else(|| {
            panic!(
                "a frame tolerance note is recorded: {:?}",
                outcome.tolerated_ragged_tails
            )
        });
    assert!(
        frame_note.contains("1 trailing frame(s) on '/mp/src_b/out'")
            && frame_note.contains("rank 1")
            && frame_note.contains("recorded 3, replay produced 4"),
        "the frame note names the topic, rank, and counts: {frame_note}"
    );
    assert!(
        outcome
            .tolerated_ragged_tails
            .iter()
            .any(|n| n.starts_with("structural:") && n.contains("rank 1")),
        "the structural over-fire clear is also recorded: {:?}",
        outcome.tolerated_ragged_tails
    );
    // The verdict renders the tolerance (transparency).
    let verdict = replay_engine::render_verdict(&outcome, &bag);
    assert!(
        verdict.contains("NOTE: ragged-tail tolerance:") && verdict.contains("/mp/src_b/out"),
        "the PASS verdict surfaces the tolerance:\n{verdict}"
    );
}

#[test]
#[serial]
fn mid_stream_extra_frame_is_not_tolerated_despite_a_ragged_tail() {
    // Scoping guard: a ragged tail exists (rank 1 trace truncated), but the
    // extra frame is MID-stream (a dropped step-1 src_b frame), NOT trailing.
    // A mid-stream extra shifts every later frame and trips the byte diff, so
    // the tolerance's `byte_violation.is_none()` guard REFUSES it — the run
    // FAILS with extra-messages (+ a byte mismatch), never masked by the tail.
    let steps = 4usize;
    let mut rec = record_uniform(
        mp_three_source_yaml(),
        mp_three_source_factories,
        &[],
        steps,
    );
    // Drop the MIDDLE (step-1) src_b frame → recorded [0,2,3], replay [0,1,2,3].
    rec.messages.get_mut("/mp/src_b/out").unwrap().remove(1);

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("mp_ragged_midstream.mcap");
    write_multi_rank_bag_with(
        &rec,
        mp_rank_of,
        2,
        MpLayout::PerStepBatches,
        &bag,
        |per_rank| per_rank[1].retain(|r| r.step <= 2), // a ragged tail IS present
    );

    let outcome = replay(&bag, mp_three_source_factories, None, None).expect("replay runs");
    assert!(
        !outcome.passed,
        "a MID-stream extra must NOT be tolerated even with a ragged tail present"
    );
    let src_b: Vec<_> = outcome
        .violations
        .iter()
        .filter(|v| v.topic == "/mp/src_b/out")
        .collect();
    assert!(
        src_b
            .iter()
            .any(|v| matches!(v.class, ViolationClass::ExtraMessages { .. })),
        "the mid-stream extra surfaces as extra-messages: {:?}",
        outcome.violations
    );
    assert!(
        src_b
            .iter()
            .any(|v| matches!(v.class, ViolationClass::ByteMismatch { .. })),
        "the shifted frames trip the byte diff: {:?}",
        outcome.violations
    );
    assert!(
        !outcome
            .tolerated_ragged_tails
            .iter()
            .any(|n| n.starts_with("frame:") && n.contains("/mp/src_b/out")),
        "the mid-stream extra is NOT frame-tolerated: {:?}",
        outcome.tolerated_ragged_tails
    );
}

