#[test]
#[serial]
fn a_torn_anchor_refuses_rather_than_applying_a_short_image() {
    // A lost record makes the anchor un-reassemblable. The reader reports it
    // TORN and the plan refuses — never a silently short image.
    let dir = tempfile::tempdir().unwrap();
    let mid = make_mid_run(&checkpoint_reference(), CP_FIRST_STEP);
    // A blob spanning two records, with the FINAL one dropped.
    let big = {
        let mut b = anchor_blob(CHECKPOINT_SHAPE, CP_FIRST_STEP);
        b.resize(cerulion_core::state_ring::STATE_RECORD_PAYLOAD + 64, 0);
        b
    };
    let mut records = state_records(CHECKPOINT_RUN, CP_FIRST_STEP - 1, CHECKPOINT_NODE_IDX, &big);
    assert!(records.len() > 1, "the fixture blob really spans records");
    records.pop();
    let bag = dir.path().join("torn.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &records,
        Some(&checkpoint_coverage(1, Some(CHECKPOINT_NODE_IDX))),
        None,
    );
    let err = replay(&bag, checkpoint_factories, None, None).expect_err("a torn anchor refuses");
    assert_eq!(err.exit_code(), 2, "{err}");
    assert!(err.to_string().contains("torn"), "{err}");
}

