// ===========================================================================
// Three resume-seam shapes that must never yield a confident verdict
//
// Each arm below is a SHAPE the resume seam accepts and must handle correctly:
// a boundary-target TIE between the anchor step and the first resumed one, a
// node the resumed suffix never executes, and a `Period` node whose next fire
// falls outside the suffix. Mishandled, each produces a CONFIDENT verdict about an
// execution that never happened — the class the engine exists to refuse.
// ===========================================================================

/// A `state_coverage.json` naming SEVERAL nodes at their ring indices.
///
/// [`checkpoint_coverage`]'s one-node sibling: the two-node arms below need a
/// manifest that attributes BOTH `node_idx`es, and a hand-written JSON that
/// failed to parse would read as an ABSENT manifest and make every arm here
/// pass for the wrong reason.
fn coverage_for_nodes(nodes: &[(&str, u32)]) -> Vec<u8> {
    let mut map = std::collections::BTreeMap::new();
    for (node, idx) in nodes {
        map.insert(
            (*node).to_string(),
            StateNodeCoverage {
                ring: "r0".to_string(),
                node_idx: Some(*idx),
                anchors_complete: 1,
                ..StateNodeCoverage::default()
            },
        );
    }
    serde_json::to_vec(&StateCoverage {
        version: cerulion_bagd::STATE_COVERAGE_VERSION,
        attached_mid_run: true,
        armed: None,
        rings_declared: 1,
        ranks_discovered: Vec::new(),
        ranks_missing: Vec::new(),
        rings_unavailable: Default::default(),
        records: 0,
        head_records_discarded: 0,
        malformed_records: 0,
        foreign_run_records: 0,
        nodes: map,
        unattributed_indices: Default::default(),
    })
    .expect("state coverage serializes")
}

// --- The anchor-tie prefix split ------------------------------

/// The TIE recording's per-step gating advance.
///
/// Step 3 advances the clock by ZERO, which
/// `validate_step_boundaries` explicitly blesses ("equal consecutive targets
/// are legal (a 0-delta wall step)") — so the anchor step (2) and the first
/// RESUMED step (3) carry the SAME boundary target, and the anchor step's own
/// frame is stamped with the resume clock.
const CP_TIE_DELTAS: [u64; CP_STEPS] = [DELTA_MS, DELTA_MS, DELTA_MS, 0, DELTA_MS, DELTA_MS];

/// A mid-run checkpoint bag over [`CP_TIE_DELTAS`].
fn write_tie_checkpoint_bag(dir: &tempfile::TempDir) -> (std::path::PathBuf, Recording) {
    let rec = record_reference(checkpoint_yaml(), checkpoint_factories, &[], &CP_TIE_DELTAS);
    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("tie.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            // The counter published 0,1,2 over steps 0..2, so its state AFTER
            // the anchor step is 3 — the same hand oracle the healthy arm uses.
            &anchor_blob(CHECKPOINT_SHAPE, CP_FIRST_STEP),
        ),
        Some(&checkpoint_coverage(1, Some(CHECKPOINT_NODE_IDX))),
        None,
    );
    (bag, rec)
}

#[test]
#[serial]
fn a_boundary_tie_at_the_resume_step_does_not_demand_unreproducible_frames() {
    // The anchor step and the first RESUMED step share a boundary target, so
    // the anchor step's own frame carries `anchor_clock_ns` verbatim. A split
    // by `timestamp < anchor_clock_ns` files that frame as POST-anchor and the
    // replay then demands a frame produced by a step it never executes —
    // reported as a MissingMessages/byte divergence against an UNCHANGED graph.
    let dir = tempfile::tempdir().unwrap();
    let (bag, rec) = write_tie_checkpoint_bag(&dir);

    // The hand oracle for the fixture: five frames, and the THIRD (the anchor
    // step's) is stamped identically to the first resumed step's target.
    let frames = rec
        .messages
        .get(CP_TOPIC)
        .expect("the fixture graph produces exactly one topic");
    let stamps: Vec<u64> = frames
        .iter()
        .map(|f| {
            WireHeader::read_from_buf(f)
                .expect("frame parses")
                .timestamp_ns
        })
        .collect();
    let anchor_clock = rec
        .trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("the reference run recorded a boundary for the resume step");
    let prev_target = rec
        .trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP_FIRST_STEP - 1)
        .map(|r| r.fire_time_ns)
        .expect("the reference run recorded a boundary for the anchor step");
    assert_eq!(
        prev_target, anchor_clock,
        "the fixture must really TIE the anchor step's target to the resume step's"
    );
    assert_eq!(
        stamps.iter().filter(|s| **s < anchor_clock).count(),
        CP_FIRST_STEP as usize - 1,
        "and the tie must really put one pre-anchor frame ON the resume clock: {stamps:?}"
    );
    let xs: Vec<f64> = frames.iter().map(|f| frame_x(f)).collect();
    assert_eq!(
        xs,
        vec![0.0, 1.0, 2.0, 3.0, 4.0],
        "the reference run is the oracle this arm is read against"
    );

    let outcome = replay(&bag, checkpoint_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.passed,
        "a tied boundary must not manufacture a divergence: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    // Three frames belong to steps 0..2 — the two below the resume clock AND
    // the anchor step's own, which is stamped ON it.
    assert_eq!(
        resume.skipped_prefix_frames.get(CP_TOPIC).copied(),
        Some(CP_FIRST_STEP as usize),
        "the anchor step's frame is part of the prefix, tie or no tie"
    );
    // The seed moves with the split: the last pre-anchor frame carried 2.
    let seed = resume
        .sequence_seeds
        .get(CP_TOPIC)
        .expect("a re-executed topic is seeded");
    assert_eq!(seed.seed, CP_FIRST_STEP as u32);
}

/// Rewrite ONE recorded frame's wire `timestamp_ns` in place.
///
/// Models a FOREIGN-clock external publisher, which is what an external topic's
/// stamps actually are — `Injector`'s own note says so ("external wire
/// timestamps are foreign-clock, so a timestamp-based walk stop would be
/// unsound"). The in-process harness publishes externals through a publisher on
/// the GRAPH's clock, which stamps each at the pre-step reading; before a
/// 0-delta step that reading IS the step's own target, and
/// `Injector::inject_up_to`'s window is a strict `< target`, so a
/// harness-stamped frame is the one value the injector can never serve at the
/// step the recording drained it on. Restamping it below the target is what a
/// real foreign publisher's clock would have written, and it is the ONLY way to
/// build the mixed-band fixture below in this harness.
///
/// Only the header is touched; the payload — the diff's actual oracle — is
/// untouched, and the produced side is not rewritten at all.
fn restamp_frame(rec: &mut Recording, topic: &str, idx: usize, ts_ns: u64) {
    let frame = rec
        .messages
        .get_mut(topic)
        .unwrap_or_else(|| panic!("the recording carries topic '{topic}'"))
        .get_mut(idx)
        .unwrap_or_else(|| panic!("topic '{topic}' has a frame at index {idx}"));
    let mut header = WireHeader::read_from_buf(frame).expect("the frame parses");
    header.timestamp_ns = ts_ns;
    header.write_to_buf(&mut frame[..WireHeader::SIZE]);
}

#[test]
#[serial]
fn a_frame_committed_by_the_tied_first_resumed_step_stays_on_the_post_anchor_side() {
    // The OTHER half of the tie split, and the one the sibling arm above cannot
    // reach.
    //
    // Its fixture ties the anchor step's target to the first resumed step's,
    // but the node that produces on that topic is a `Period` node — and a
    // 0-delta step advances no time, so no `Period` node can EVER be newly due
    // on one (it either fired at the anchor step, which pushed its deadline
    // past `now`, or it was not due at a `now` the tied step shares). Its tie
    // band is therefore PURELY prefix-side, `tie_commits` stays 0, and the
    // correct answer coincides exactly with what an implementation that files
    // the WHOLE equal-stamped band into the prefix produces.
    //
    // A DATA-triggered node has no such bar: its trigger is an arrival, not the
    // clock, so it fires on the 0-delta step like any other. That makes the
    // band MIXED — one frame from the anchor step (prefix side) and one from
    // the first resumed step (post side), sharing a timestamp to the
    // nanosecond — and the split has to cut in the MIDDLE of it. That cut is
    // the whole of `tie_commits`: "the recorded steps sharing that target can
    // have committed at most `tie_commits` frames on the topic". Over-deduct by
    // one and the replay files a frame it is ABOUT TO RE-PRODUCE as prefix,
    // then reports the frame it published as an extra one — a divergence
    // against an unchanged graph, which is the class the seam exists to
    // refuse.
    //
    // It also drives the only branch that reads INSIDE the band from both
    // sides at once: with `0 < cut < len`, the seed's lower rung is
    // `at_anchor[cut - 1]` (the anchor step's own frame) and its upper rung is
    // `at_anchor[cut]` (the resumed step's), neither of which is the band's
    // edge.
    let per_step: Vec<f64> = (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect();
    let ext_topic = "/xr/ext/cam";
    let out_topic = "/xr/relay/out";
    let externals = vec![ExternalDrive::singles(ext_topic, per_step.clone())];
    let mut rec = record_reference(
        ext_graph_yaml(),
        ext_relay_factories,
        &externals,
        &CP_TIE_DELTAS,
    );

    let target_at = |rec: &Recording, step: u64| -> u64 {
        rec.trace
            .iter()
            .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == step)
            .unwrap_or_else(|| panic!("the reference run recorded a boundary for step {step}"))
            .fire_time_ns
    };
    let anchor_clock = target_at(&rec, CP_FIRST_STEP);
    assert_eq!(
        target_at(&rec, CP_FIRST_STEP - 1),
        anchor_clock,
        "the fixture must really TIE the anchor step's target to the resume step's"
    );

    // The hand oracle for the recording, stated before anything is rewritten:
    // the relay published once per step, `ext + 100` each time, and the THIRD
    // and FOURTH frames share the tied stamp — one from each side of the split.
    let recorded: Vec<(u32, u64, f64)> = rec.messages[out_topic]
        .iter()
        .map(|f| {
            let h = WireHeader::read_from_buf(f).expect("frame parses");
            (h.sequence, h.timestamp_ns, frame_x(f))
        })
        .collect();
    assert_eq!(
        recorded,
        (0..CP_STEPS)
            .map(|k| (k as u32, target_at(&rec, k as u64), per_step[k] + 100.0))
            .collect::<Vec<_>>(),
        "hand oracle: one relay frame per step, `ext + 100`, stamped at its step's target"
    );
    assert_eq!(
        recorded
            .iter()
            .filter(|(_, ts, _)| *ts == anchor_clock)
            .map(|(seq, ..)| *seq)
            .collect::<Vec<_>>(),
        vec![CP_FIRST_STEP as u32 - 1, CP_FIRST_STEP as u32],
        "the band must really be MIXED — the anchor step's frame AND the first \
         resumed step's, sharing the tied stamp: {recorded:?}"
    );

    // The first resumed step's INPUT: recorded on the graph's own clock, so it
    // carries the tied target verbatim and the injector's `< target` window
    // could never serve it. Restamped one millisecond below, the value a
    // foreign publisher's clock would have written.
    let ext_stamp = anchor_clock - 1_000_000;
    restamp_frame(&mut rec, ext_topic, CP_FIRST_STEP as usize, ext_stamp);

    // The tap attaches mid-step-2, so the bag carries EXACTLY the external
    // frames the three replayed steps consume — the `Recorder::setup` shape the
    // sibling external arm uses, and what keeps the first replayed step's
    // injection window from also serving three earlier inputs.
    let attach_ns = target_at(&rec, CP_FIRST_STEP - 2) + 1_000_000;
    assert!(
        attach_ns < ext_stamp,
        "the tap must attach BEFORE the restamped input, or the arm tests nothing"
    );
    let mid = make_mid_run_with_tap_attach(&rec, CP_FIRST_STEP, attach_ns);
    let ext_kept: Vec<u64> = mid.messages[ext_topic]
        .iter()
        .map(|f| {
            WireHeader::read_from_buf(f)
                .expect("frame parses")
                .timestamp_ns
        })
        .collect();
    assert_eq!(
        ext_kept,
        vec![ext_stamp, anchor_clock, target_at(&rec, CP_FIRST_STEP + 1)],
        "exactly one external input per replayed step, each strictly below that \
         step's target"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("tie_commit.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            // The anchor exists so `plan_restore` can answer FromAnchor at
            // all; its bytes are the relay's own capture, so applying it is a
            // no-op on the addend and this arm still pins only the split.
            &relay_anchor_blob(),
        ),
        Some(&coverage_naming(
            "relay",
            cerulion_bagd::STATE_COVERAGE_VERSION,
            1,
            Some(CHECKPOINT_NODE_IDX),
        )),
        None,
    );

    let outcome = replay(&bag, ext_relay_factories, None, None).expect("the mid-run bag replays");
    assert!(
        outcome.passed,
        "the frame the FIRST RESUMED step committed is re-produced by the replay, so \
         it must stay on the post-anchor side of the split: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert_eq!(outcome.topics_checked, 1, "only the relay output is diffed");
    assert_eq!(outcome.topics_passed, 1);

    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(resume.first_replay_step, CP_FIRST_STEP);
    // THE pin. The bag's relay frames are the four from the tap attach on
    // (stamps tied, tied, +1 step, +2 steps); exactly ONE of them — the anchor
    // step's — is prefix. Deducting the whole band instead would say 2.
    assert_eq!(
        resume.skipped_prefix_frames.get(out_topic).copied(),
        Some(1),
        "the tied band is SPLIT: the anchor step's frame is prefix, the first \
         resumed step's is not: {:?}",
        resume.skipped_prefix_frames
    );
    assert_eq!(
        resume.skipped_prefix_frames.get(ext_topic).copied(),
        None,
        "an external topic is never skipped: {:?}",
        resume.skipped_prefix_frames
    );
    // The seed reads the split from INSIDE the band: the last pre-anchor frame
    // is the anchor step's, carrying `CP_FIRST_STEP - 1`, so the re-executed
    // publisher resumes at `CP_FIRST_STEP` and re-publishes the tied frame the
    // first resumed step owns.
    let seed = resume
        .sequence_seeds
        .get(out_topic)
        .expect("a re-executed topic is seeded");
    assert_eq!(
        seed.seed, CP_FIRST_STEP as u32,
        "seeding off the band's LOWER edge would restart the publisher a whole \
         band too low and byte-mismatch every frame it goes on to publish"
    );
}

#[test]
#[serial]
fn a_topic_whose_recording_opens_at_the_anchor_clock_seeds_from_inside_the_band() {
    // The band's OTHER in-band read, found by mutating the arm above: the seed
    // ladder's rung (ii) is `at_anchor[cut]`, and it is consulted only when
    // rung (i) — the last frame at-or-below the anchor — is absent.
    //
    // `cut > 0` implies `at_anchor[cut - 1]` exists, so rung (i) is present
    // whenever the split cuts inside the band, which makes rung (ii) inert in
    // the mixed-band arm above. It becomes the DECIDING rung on exactly one
    // shape: `cut == 0` (the whole band belongs to the resumed steps) AND the
    // bag carries nothing below the anchor clock — a recorder whose tap opened
    // ON the anchor instant, so the topic's very first recorded frame is one
    // the replay is about to re-produce. Reading `first_seq_above` there — the
    // frame AFTER the band — seeds the publisher one too high and byte-
    // mismatches every frame it goes on to publish, and no other arm detects it
    // (checked directly against the rest of the binary).
    //
    // No tie here: uniform steps, so the band is the first resumed step's own
    // frames and the split must deduct NOTHING.
    let per_step: Vec<f64> = (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect();
    let ext_topic = "/xr/ext/cam";
    let out_topic = "/xr/relay/out";
    let externals = vec![ExternalDrive::singles(ext_topic, per_step.clone())];
    let mut rec = record_uniform(ext_graph_yaml(), ext_relay_factories, &externals, CP_STEPS);

    let targets: Vec<u64> = (0..CP_STEPS as u64)
        .map(|step| {
            rec.trace
                .iter()
                .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == step)
                .unwrap_or_else(|| panic!("the reference run recorded a boundary for step {step}"))
                .fire_time_ns
        })
        .collect();
    let target_at = |step: u64| targets[step as usize];
    let anchor_clock = target_at(CP_FIRST_STEP);
    assert_ne!(
        target_at(CP_FIRST_STEP - 1),
        anchor_clock,
        "this arm is the NON-tie shape — a tie would put an anchor-step frame in \
         the band and give rung (i) something to read"
    );

    // The tap must open ABOVE the anchor step's own frame (so the produced topic
    // carries nothing below the anchor clock) and BELOW the input the first
    // resumed step consumes. Those two are recorded at the SAME instant — the
    // anchor step's target — because the harness stamps an external on the
    // graph's clock, so the input is restamped into the gap between the two
    // targets first. See `restamp_frame`: a foreign publisher's clock is where
    // an external topic's stamps really come from.
    let ext_stamp = target_at(CP_FIRST_STEP - 1) + 1_000_000;
    assert!(
        target_at(CP_FIRST_STEP - 1) < ext_stamp && ext_stamp < anchor_clock,
        "the restamped input must land strictly between the two targets"
    );
    restamp_frame(&mut rec, ext_topic, CP_FIRST_STEP as usize, ext_stamp);
    let mid = make_mid_run_with_tap_attach(&rec, CP_FIRST_STEP, ext_stamp);
    let kept: Vec<(u32, u64, f64)> = mid.messages[out_topic]
        .iter()
        .map(|f| {
            let h = WireHeader::read_from_buf(f).expect("frame parses");
            (h.sequence, h.timestamp_ns, frame_x(f))
        })
        .collect();
    assert_eq!(
        kept,
        (CP_FIRST_STEP as usize..CP_STEPS)
            .map(|k| (k as u32, target_at(k as u64), per_step[k] + 100.0))
            .collect::<Vec<_>>(),
        "hand oracle: the bag opens on the first resumed step's frame, `ext + 100`, \
         and carries NOTHING below the anchor clock"
    );

    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("anchor_open.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            // The relay's own capture — see `relay_anchor_blob`. Applying it is
            // a no-op on the addend, so this arm still pins only the seed rung.
            &relay_anchor_blob(),
        ),
        Some(&coverage_naming(
            "relay",
            cerulion_bagd::STATE_COVERAGE_VERSION,
            1,
            Some(CHECKPOINT_NODE_IDX),
        )),
        None,
    );

    let outcome = replay(&bag, ext_relay_factories, None, None).expect("the mid-run bag replays");
    assert!(
        outcome.passed,
        "a topic whose recording opens ON the anchor clock re-publishes its first \
         recorded frame, so the seed is that frame's own sequence: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    // Nothing is deducted: every frame in the band belongs to a replayed step.
    assert_eq!(
        resume.skipped_prefix_frames.get(out_topic).copied(),
        None,
        "an untied band is entirely post-anchor: {:?}",
        resume.skipped_prefix_frames
    );
    let seed = resume
        .sequence_seeds
        .get(out_topic)
        .expect("a re-executed topic is seeded");
    assert_eq!(
        seed.seed, CP_FIRST_STEP as u32,
        "the seed is the BAND's own first sequence, not the one after it"
    );
    assert_eq!(
        seed.rung, "first-frame-after-anchor",
        "and it must be reached on rung (ii) — on rung (i) this arm would pin \
         nothing the mixed-band arm above does not already pin"
    );
}

// --- Findings 2 + 3: a two-node graph with a SPARSE `Period` node ---------

/// The two-node fixture's node ids and resolved topics.
const CP2_COUNTER: &str = "counter";
const CP2_SLOW: &str = "slow";
const CP2_COUNTER_TOPIC: &str = "/cp2/counter/out";
const CP2_SLOW_TOPIC: &str = "/cp2/slow/out";
/// `slow`'s `Period` interval, in ms. Chosen so its ONLY fire in the reference
/// run lands ON the anchor step and none lands in the resumed suffix.
const CP2_SLOW_PERIOD_MS: u64 = 30;
/// Steps in the two-node reference run (targets 5..40 ms).
const CP2_STEPS: usize = 8;
/// The step its bags resume at: the suffix is steps 6..7 (targets 35, 40 ms),
/// a window `slow`'s 30 ms grid does not touch.
const CP2_FIRST_STEP: u64 = 6;

fn cp2_yaml() -> &'static str {
    "name: cp2\nprefix: cp2\nnodes:\n\
     \x20 - id: counter\n    type: counter\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: slow\n    type: slow\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn cp2_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        (
            CP2_COUNTER,
            Box::new(CounterEntry::new()) as Box<dyn NodeEntry>,
        ),
        (
            CP2_SLOW,
            Box::new(CounterEntry::with_period(CP2_SLOW_PERIOD_MS)) as Box<dyn NodeEntry>,
        ),
    ])
}

/// [`cp2_factories`] with `slow` declaring NO restorable state.
fn cp2_factories_slow_stateless() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        (
            CP2_COUNTER,
            Box::new(CounterEntry::new()) as Box<dyn NodeEntry>,
        ),
        (
            CP2_SLOW,
            Box::new(CounterEntry::stateless_with_period(CP2_SLOW_PERIOD_MS)) as Box<dyn NodeEntry>,
        ),
    ])
}

/// [`cp2_factories`] with `counter` — the node the suffix DOES execute —
/// declaring no restorable state.
fn cp2_factories_counter_stateless() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        (
            CP2_COUNTER,
            Box::new(CounterEntry::stateless()) as Box<dyn NodeEntry>,
        ),
        (
            CP2_SLOW,
            Box::new(CounterEntry::with_period(CP2_SLOW_PERIOD_MS)) as Box<dyn NodeEntry>,
        ),
    ])
}

fn cp2_reference() -> Recording {
    record_reference(cp2_yaml(), cp2_factories, &[], &[DELTA_MS; CP2_STEPS])
}

/// A mid-run two-node bag. `slow_anchor` says whether the recording carries an
/// anchor for the node the suffix never executes.
fn write_cp2_bag(
    dir: &tempfile::TempDir,
    name: &str,
    slow_anchor: bool,
    rec: &Recording,
) -> std::path::PathBuf {
    let mid = make_mid_run(rec, CP2_FIRST_STEP);
    let bag = dir.path().join(name);
    let mut records = state_records(
        CHECKPOINT_RUN,
        CP2_FIRST_STEP - 1,
        0,
        // `counter` published 0..5 over steps 0..5, so its state after the
        // anchor step is 6.
        &anchor_blob(CHECKPOINT_SHAPE, CP2_FIRST_STEP),
    );
    let mut named: Vec<(&str, u32)> = vec![(CP2_COUNTER, 0)];
    if slow_anchor {
        // `slow` published once (its 30 ms fire, at the anchor step), so its
        // state after that step is 1.
        records.extend(state_records(
            CHECKPOINT_RUN,
            CP2_FIRST_STEP - 1,
            1,
            &anchor_blob(CHECKPOINT_SHAPE, 1),
        ));
        named.push((CP2_SLOW, 1));
    }
    write_checkpoint_bag(
        &mid,
        &bag,
        &records,
        Some(&coverage_for_nodes(&named)),
        None,
    );
    bag
}

/// The shape assertions every two-node arm reads against, asserted ONCE here so
/// each arm states only what it is about.
fn assert_cp2_reference_shape(rec: &Recording) {
    let counter: Vec<f64> = rec.messages[CP2_COUNTER_TOPIC]
        .iter()
        .map(|f| frame_x(f))
        .collect();
    assert_eq!(
        counter,
        (0..CP2_STEPS).map(|k| k as f64).collect::<Vec<_>>(),
        "`counter` fires once per step"
    );
    let slow: Vec<f64> = rec.messages[CP2_SLOW_TOPIC]
        .iter()
        .map(|f| frame_x(f))
        .collect();
    assert_eq!(
        slow,
        vec![0.0],
        "`slow` fires exactly once in the whole run"
    );
    let slow_stamp = WireHeader::read_from_buf(&rec.messages[CP2_SLOW_TOPIC][0])
        .expect("frame parses")
        .timestamp_ns;
    let anchor_clock = rec
        .trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP2_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("boundary for the resume step");
    assert!(
        slow_stamp < anchor_clock,
        "and that one fire is BEFORE the resume clock ({slow_stamp} vs {anchor_clock}), so the \
         suffix carries no fire for it at all"
    );
    assert!(
        !rec.trace.iter().any(|r| r.record_type == RECORD_TYPE_FIRE
            && r.step >= CP2_FIRST_STEP
            && rec.node_ids[r.node_idx as usize] == CP2_SLOW),
        "the suffix really records no `slow` fire"
    );
}

#[test]
#[serial]
fn a_period_node_with_no_fire_in_the_suffix_keeps_its_recorded_schedule() {
    // The resume baseline map is built from recorded FIRE records,
    // so a `Period` node that does not fire in the suffix is OMITTED — and
    // `add_node`'s fresh `clock.now_ns() + interval` baseline (taken at build,
    // when the clock still reads 0) then sits BELOW the anchor clock, so the
    // first resumed step fires it. One unrecorded fire, on a graph nobody
    // changed.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp2_reference();
    assert_cp2_reference_shape(&rec);
    let bag = write_cp2_bag(&dir, "cp2_sched.mcap", true, &rec);

    let outcome = replay(&bag, cp2_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.trace_divergence.is_none(),
        "a node the recording never fires in the suffix must not fire in the replay: {:?}",
        outcome.trace_divergence
    );
    assert!(
        outcome.passed,
        "{:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert_eq!(outcome.ticks_replayed, CP2_STEPS - CP2_FIRST_STEP as usize);
}

#[test]
#[serial]
fn a_node_the_resumed_suffix_never_executes_does_not_veto_the_restore() {
    // `RestoreRequest::required_nodes` is DEFINED as "every node the
    // replay will EXECUTE"; a resume that passed every node in the graph would
    // refuse a recording that covers everything the suffix runs for a node
    // that never runs.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp2_reference();
    assert_cp2_reference_shape(&rec);
    let bag = write_cp2_bag(&dir, "cp2_inert.mcap", false, &rec);

    let outcome = replay(&bag, cp2_factories, None, None)
        .expect("an anchor covering every EXECUTED node is enough");
    assert!(
        outcome.passed,
        "{:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(resume.restored_nodes, vec![CP2_COUNTER.to_string()]);
}

#[test]
#[serial]
fn a_zero_tick_resume_executes_nothing_and_so_demands_no_state() {
    // The bag-time-bound half: `--duration 0` covers no bag time,
    // so it executes no step (the half-open window `[epoch, epoch)` is empty),
    // and so no
    // node's state is read and none can be missing. The CONTROL is the same bag
    // UNBOUNDED, which must still refuse by name.
    let dir = tempfile::tempdir().unwrap();
    let mid = make_mid_run(&checkpoint_reference(), CP_FIRST_STEP);
    let bag = dir.path().join("zero_tick.mcap");
    write_checkpoint_bag(&mid, &bag, &[], None, None);

    let outcome = replay(&bag, checkpoint_factories, Some(0), None)
        .expect("a 0-tick resume executes nothing, so nothing needs restoring");
    assert_eq!(outcome.ticks_replayed, 0);

    let err = replay(&bag, checkpoint_factories, None, None)
        .expect_err("the SAME bag unbounded still refuses");
    assert_eq!(err.exit_code(), 2, "{err}");
    assert!(err.to_string().contains("no anchor recorded"), "{err}");
}

#[test]
#[serial]
fn strict_state_judges_the_executed_nodes_and_only_those() {
    // The control, both directions in one body over ONE graph: the flag
    // must still refuse when the node the suffix RUNS declares no state, and
    // must not refuse for one it never runs.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp2_reference();
    assert_cp2_reference_shape(&rec);
    let bag = write_cp2_bag(&dir, "cp2_strict.mcap", true, &rec);

    let ok = replay_inner(
        &bag,
        cp2_factories_slow_stateless,
        None,
        None,
        None,
        RecordHealthReport::Absent,
        None,
        true,
    )
    .expect("--strict-state ignores a node the suffix never executes");
    let resume = ok.resume.expect("still a resume");
    assert!(
        resume.nodes_without_state.is_empty(),
        "an inert node is not part of the coverage the flag judges: {:?}",
        resume.nodes_without_state
    );

    let err = replay_inner(
        &bag,
        cp2_factories_counter_stateless,
        None,
        None,
        None,
        RecordHealthReport::Absent,
        None,
        true,
    )
    .expect_err("--strict-state still refuses an EXECUTED node with no state");
    assert_eq!(err.exit_code(), 2, "{err}");
    assert!(err.to_string().contains(CP2_COUNTER), "{err}");
}

// ===========================================================================
// The FRAMEWORK SECTION of the anchor blob, end to end
// ===========================================================================
//
// A resume restores a node's own fields; everything ELSE about the
// resumed graph was once derived from the trace. The framework section states the scheduler's
// own view instead, and these arms pin the two consumers that changes:
//
//  * the `Period` baseline, which was read off the recorded FIRE records
//    at a cost: the trace is also what the exit-6 comparator
//    judges against, so a baseline taken from it makes a divergence at exactly
//    that first fire undetectable. The section OUTRANKS it.
//  * a `Sync` node's half-satisfied alignment, which is scheduler state and so
//    reaches no node's `restore_state` at all.
//
// Every arm is read against the reference run's own recorded values, and each
// pair carries an arm whose two candidate implementations produce DIFFERENT
// answers — a baseline the trace also happens to supply pins nothing.

use cerulion_core::state::VecSink;
use cerulion_core::state_restore::{AnchorBlob as WsAnchorBlob, NodeFrameworkState};
use std::collections::BTreeMap;

/// A framed anchor blob CARRYING a framework section: the framed header (magic
/// ++ shape ++ section length), the section, then the node's own payload.
///
/// Built through the production writer rather than by hand because these arms
/// are about the ENGINE's use of the section; its BYTES are pinned by hand in
/// `cerulion_core`'s `state_restore_test`.
///
/// For a HAND-WRITTEN `NodeEntry` fixture only — [`CounterEntry`], whose
/// `state_shape()` returns [`CHECKPOINT_SHAPE`] and whose `restore_state` takes
/// a bare `u64`. A `#[cerulion_node]` fixture takes
/// [`node_anchor_blob_with_framework`] instead, for the reasons spelled out
/// there.
fn anchor_blob_with_framework(
    shape: u64,
    payload: Option<u64>,
    framework: &NodeFrameworkState,
) -> Vec<u8> {
    let mut sink = VecSink::new();
    WsAnchorBlob::write_header_with_framework(shape, framework, &mut sink)
        .expect("the framing fits an unbounded sink");
    let mut out = sink.into_inner();
    if let Some(count) = payload {
        out.extend_from_slice(&count.to_le_bytes());
    }
    out
}

/// [`anchor_blob_with_framework`] for a `#[cerulion_node]` fixture: the shape
/// header AND the payload both come from the node's own type.
///
/// The framework sibling of [`relay_anchor_blob`], and it exists for the same
/// reason. A macro node DECLARES state: its
/// `NodeEntry::state_shape` forwards the struct's derived
/// `CerulionState::STATE_SHAPE`, and its `restore_state` decodes the payload
/// field by field and then refuses trailing bytes. So the arbitrary
/// [`CHECKPOINT_SHAPE`] is not a shape any of these nodes could have been
/// captured with, and an anchor stamped with it is refused before the
/// arm reaches the framework-section seam it is actually about.
///
/// `state` is the node's state AT THE ANCHOR STEP, which each call site states
/// in its own words the way `write_cp3_bag` already states its `Period` nodes'
/// counters — the anchor is only valid if it carries what a recorder taking it
/// there would have captured.
fn node_anchor_blob_with_framework<T: cerulion_core::state::CerulionState>(
    state: &T,
    framework: &NodeFrameworkState,
) -> Vec<u8> {
    let mut sink = VecSink::new();
    WsAnchorBlob::write_header_with_framework(T::STATE_SHAPE, framework, &mut sink)
        .expect("the framing fits an unbounded sink");
    state
        .cer_capture(&mut sink)
        .expect("the node's state fits an unbounded sink");
    sink.into_inner()
}

/// A `Period` node's section: a deadline and nothing else.
fn period_section(next_fire_ns: u64) -> NodeFrameworkState {
    NodeFrameworkState {
        next_fire_ns: Some(next_fire_ns),
        ..Default::default()
    }
}

/// The single-counter checkpoint bag, with a framed anchor whose section
/// declares `next_fire_ns`.
fn write_checkpoint_bag_with_deadline(
    dir: &tempfile::TempDir,
    count_at_anchor: u64,
    next_fire_ns: u64,
) -> std::path::PathBuf {
    let rec = checkpoint_reference();
    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("cp_ws2c.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            &anchor_blob_with_framework(
                CHECKPOINT_SHAPE,
                Some(count_at_anchor),
                &period_section(next_fire_ns),
            ),
        ),
        Some(&checkpoint_coverage(1, Some(CHECKPOINT_NODE_IDX))),
        None,
    );
    bag
}

/// The gating-clock target of the first step a `CP_FIRST_STEP` resume executes.
fn cp_anchor_clock_ns(rec: &Recording) -> u64 {
    rec.trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("the reference run recorded a boundary for the resume step")
}

#[test]
#[serial]
fn a_recorded_next_fire_deadline_outranks_the_recorded_fire_trace() {
    // THE un-seeding pin, and the one arm here whose two candidate
    // implementations disagree.
    //
    // The trace-derived path seeds the counter's baseline from its first recorded FIRE, which
    // is the anchor clock itself — so the node is due immediately and fires on
    // all three resumed steps. This bag's framework section instead states a
    // deadline BEYOND the recorded suffix, so a replay that adopts it fires the
    // node ZERO times and diverges loudly.
    //
    // The value is deliberately off the node's own 5 ms grid AND above the last
    // recorded target, so neither the trace rung nor
    // `restore_period_schedule`'s phase-preserving re-advance can land on it by
    // coincidence: the trace says 20 ms, a re-phase from the origin says 20 ms,
    // and only reading the section says 37 ms.
    let dir = tempfile::tempdir().unwrap();
    let rec = checkpoint_reference();
    let anchor_clock = cp_anchor_clock_ns(&rec);
    assert_eq!(anchor_clock, 20_000_000, "the fixture's resume clock");
    let last_target = rec
        .trace
        .iter()
        .filter(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY)
        .map(|r| r.fire_time_ns)
        .max()
        .expect("the reference run recorded boundaries");
    assert_eq!(last_target, 30_000_000);

    let beyond_the_suffix = 37_000_000;
    assert!(beyond_the_suffix > last_target);
    let bag = write_checkpoint_bag_with_deadline(&dir, CP_FIRST_STEP, beyond_the_suffix);

    let outcome = replay(&bag, checkpoint_factories, None, None).expect("mid-run replay runs");
    assert!(
        !outcome.passed,
        "a deadline past the recorded suffix must silence the node — a PASS here \
         means the recorded FIRE trace supplied the baseline and the framework \
         section was ignored"
    );
    assert!(
        outcome
            .violations
            .iter()
            .any(|v| v.topic == CP_TOPIC && matches!(v.class, ViolationClass::MissingTopic)),
        "the silenced node produces NONE of the three recorded frames: {:?}",
        outcome.violations
    );

    // And the report says WHERE the baseline came from, so an operator reading
    // a divergence can tell a state-driven schedule from a trace-driven one.
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(resume.framework_nodes, vec![CP_NODE.to_string()]);
    assert_eq!(
        resume.period_baselines_from_state,
        vec![CP_NODE.to_string()],
        "the node's deadline came from recorded scheduler state"
    );
}

#[test]
#[serial]
fn a_framework_section_that_states_the_true_deadline_replays_byte_exact() {
    // The healthy direction of the same seam. SCOPE: this arm does NOT
    // discriminate adoption from the trace rung — a truthful section agrees
    // with the trace by construction, which is the whole reason the arm above
    // has to lie to be probative. What it pins is that reading the section
    // changes NOTHING when it agrees, and that the report names it.
    let dir = tempfile::tempdir().unwrap();
    let rec = checkpoint_reference();
    // The live scheduler's own value at the anchor: the node fired at 15 ms on
    // a 5 ms period, so its next deadline is 20 ms — which is also the instant
    // the resumed clock is placed at, so it is due immediately.
    let bag = write_checkpoint_bag_with_deadline(&dir, CP_FIRST_STEP, cp_anchor_clock_ns(&rec));

    let outcome = replay(&bag, checkpoint_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.passed,
        "{:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert!(outcome.trace_divergence.is_none());
    assert_eq!(outcome.ticks_replayed, CP_STEPS - CP_FIRST_STEP as usize);

    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(resume.framework_nodes, vec![CP_NODE.to_string()]);
    assert_eq!(
        resume.period_baselines_from_state,
        vec![CP_NODE.to_string()]
    );
    assert!(
        resume.backlog_admission.is_empty(),
        "a graph with no undrained backlog admits nothing"
    );
}

#[test]
#[serial]
fn a_pre_ws2c_anchor_reports_no_framework_state_and_replays_as_it_always_did() {
    // BACK-COMPAT, stated where it is checkable: the v1 blob every bag
    // recorded before the framework section existed decodes to NO section, so both
    // report fields are empty and the Period baseline still comes from the FIRE
    // trace. Byte-for-byte the trace-derived path.
    let dir = tempfile::tempdir().unwrap();
    let bag = write_healthy_checkpoint_bag(&dir, CP_FIRST_STEP);
    let outcome = replay(&bag, checkpoint_factories, None, None).expect("mid-run replay runs");
    assert!(outcome.passed, "{:?}", outcome.violations);

    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert!(
        resume.framework_nodes.is_empty(),
        "a v1 anchor states nothing about the scheduler"
    );
    assert!(
        resume.period_baselines_from_state.is_empty(),
        "so the baseline is the FIRE trace's, exactly as before"
    );
    assert!(resume.backlog_admission.is_empty());
}

#[test]
#[serial]
fn a_framework_section_this_build_cannot_read_refuses_rather_than_replaying() {
    // A section is not optional-if-unreadable: "the recording states nothing"
    // and "the recording states something this build cannot parse" are
    // different facts, and quietly treating the second as the first would
    // resume on a schedule nobody checked while reporting success.
    let dir = tempfile::tempdir().unwrap();
    let rec = checkpoint_reference();
    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("cp_bad_section.mcap");
    // A well-framed v2 blob whose section declares a version this build has no
    // layout for.
    let mut blob = anchor_blob_with_framework(
        CHECKPOINT_SHAPE,
        Some(CP_FIRST_STEP),
        &period_section(20_000_000),
    );
    let section_start = 20; // magic(8) ++ shape(8) ++ section length(4)
    blob[section_start..section_start + 4].copy_from_slice(&0u32.to_le_bytes());
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            &blob,
        ),
        Some(&checkpoint_coverage(1, Some(CHECKPOINT_NODE_IDX))),
        None,
    );

    let err = replay(&bag, checkpoint_factories, None, None).expect_err("unreadable section");
    let text = err.to_string();
    assert!(text.contains(CP_NODE), "names the node: {text}");
    assert!(
        text.contains("framework section"),
        "names what it could not read: {text}"
    );
    assert_eq!(
        err.exit_code(),
        2,
        "an unreadable recording is not-replay-grade (exit 2), not a data violation"
    );
}

// --- A half-satisfied `Sync` alignment across a resume ---------------------

/// A bounded-sync consumer of two sparse sources. Its whole observable is that
/// it fired: `out.x` counts its fires.
#[cerulion_node(sync_window_ms = 50)]
#[derive(Default)]
struct FusionNode {
    #[input(trigger)]
    a: Vector3,
    #[input(trigger)]
    b: Vector3,
    #[output]
    out: Vector3,
    fires: f64,
}

#[cerulion_node_impl]
impl FusionNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.fires += 1.0;
        self.out.x = self.fires;
        Ok(())
    }
}

const CP3_A: &str = "a_src";
const CP3_B: &str = "b_src";
const CP3_FUSION: &str = "fusion";
const CP3_A_TOPIC: &str = "/cp3/a_src/out";
const CP3_B_TOPIC: &str = "/cp3/b_src/out";
const CP3_FUSION_TOPIC: &str = "/cp3/fusion/out";
/// `a_src`'s period: one fire, at 30 ms — the anchor step.
const CP3_A_PERIOD_MS: u64 = 30;
/// `b_src`'s period: one fire, at 40 ms — inside the resumed suffix.
const CP3_B_PERIOD_MS: u64 = 40;
/// Steps in the reference run (targets 5..40 ms).
const CP3_STEPS: usize = 8;
/// The step its bags resume at: the suffix is steps 6..7 (35 and 40 ms).
const CP3_FIRST_STEP: u64 = 6;

fn cp3_yaml() -> &'static str {
    "name: cp3\nprefix: cp3\nnodes:\n\
     \x20 - id: a_src\n    type: counter\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: b_src\n    type: counter\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: fusion\n    type: fusion\n    inputs:\n      - name: a\n        source: a_src/out\n      - name: b\n        source: b_src/out\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn cp3_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        (
            CP3_A,
            Box::new(CounterEntry::with_period(CP3_A_PERIOD_MS)) as Box<dyn NodeEntry>,
        ),
        (
            CP3_B,
            Box::new(CounterEntry::with_period(CP3_B_PERIOD_MS)) as Box<dyn NodeEntry>,
        ),
        (
            CP3_FUSION,
            Box::new(FusionNodeEntry::new()) as Box<dyn NodeEntry>,
        ),
    ])
}

fn cp3_reference() -> Recording {
    record_reference(cp3_yaml(), cp3_factories, &[], &[DELTA_MS; CP3_STEPS])
}

/// The shape every `cp3` arm reads against, asserted once so each arm states
/// only what it is about.
fn assert_cp3_reference_shape(rec: &Recording) {
    let stamps = |topic: &str| -> Vec<u64> {
        rec.messages[topic]
            .iter()
            .map(|f| {
                WireHeader::read_from_buf(f)
                    .expect("frame parses")
                    .timestamp_ns
            })
            .collect()
    };
    assert_eq!(
        stamps(CP3_A_TOPIC),
        vec![30_000_000],
        "`a_src` fires exactly once, at the anchor step"
    );
    assert_eq!(
        stamps(CP3_B_TOPIC),
        vec![40_000_000],
        "`b_src` fires exactly once, in the resumed suffix"
    );
    assert_eq!(
        stamps(CP3_FUSION_TOPIC),
        vec![40_000_000],
        "and the fusion fires exactly once, when /b completes the alignment /a \
         opened one step BEFORE the resume"
    );
    let anchor_clock = rec
        .trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP3_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("boundary for the resume step");
    assert_eq!(anchor_clock, 35_000_000);
    assert!(
        30_000_000 < anchor_clock,
        "the /a arrival that satisfies half the window is PRE-anchor, so the \
         resumed replay never sees it again — the whole point of the fixture"
    );
}

/// A `cp3` bag. `sync_state` is what the fusion node's framework section says
/// about its half-satisfied alignment.
fn write_cp3_bag(
    dir: &tempfile::TempDir,
    name: &str,
    rec: &Recording,
    sync_state: BTreeMap<String, u64>,
) -> std::path::PathBuf {
    let mid = make_mid_run(rec, CP3_FIRST_STEP);
    let bag = dir.path().join(name);
    let anchor_step = CP3_FIRST_STEP - 1;
    let mut records = Vec::new();
    // `a_src` published once, so its counter is 1, and its next 30 ms deadline
    // is 60 ms — beyond the suffix, which is why it never fires again.
    records.extend(state_records(
        CHECKPOINT_RUN,
        anchor_step,
        0,
        &anchor_blob_with_framework(CHECKPOINT_SHAPE, Some(1), &period_section(60_000_000)),
    ));
    // `b_src` has not published yet, so its counter is 0 and its first 40 ms
    // deadline is still ahead.
    records.extend(state_records(
        CHECKPOINT_RUN,
        anchor_step,
        1,
        &anchor_blob_with_framework(CHECKPOINT_SHAPE, Some(0), &period_section(40_000_000)),
    ));
    // The fusion's own state is its fire counter, and `assert_cp3_reference_shape`
    // pins its ONE fire at 40 ms — inside the suffix — so at the anchor step it
    // has fired zero times and `Default` IS its captured state. Everything else
    // the recording knows about it is in the framework section, which is what
    // these arms are about.
    records.extend(state_records(
        CHECKPOINT_RUN,
        anchor_step,
        2,
        &node_anchor_blob_with_framework(
            &FusionNode::default(),
            &NodeFrameworkState {
                next_fire_ns: None,
                pending_data_count: 0,
                sync_input_timestamps: sync_state,
                // A `Sync` node has no per-message FIFO input, and it says so
                // (an EMPTY table, not an absent one).
                input_service: Some(BTreeMap::new()),
            },
        ),
    ));
    write_checkpoint_bag(
        &mid,
        &bag,
        &records,
        Some(&coverage_for_nodes(&[
            (CP3_A, 0),
            (CP3_B, 1),
            (CP3_FUSION, 2),
        ])),
        None,
    );
    bag
}

#[test]
#[serial]
fn a_half_satisfied_sync_alignment_survives_the_resume() {
    // A half-satisfied alignment, as a replay: a fusion node checkpointed with
    // /a arrived and /b not resumes with /a STILL arrived, so the /b that lands
    // one step later completes the window and the node FIRES exactly where the
    // recording says it did.
    //
    // /a's only arrival is PRE-anchor and its producer's next deadline is
    // beyond the suffix, so nothing in the resumed replay can re-supply it —
    // the restored timestamp is the only thing that can put that fire back.
    //
    // # The oracle is the FIRE, and the residual is stated rather than hidden
    //
    // MEASURED here: the restore puts the SCHEDULE back and it cannot put the
    // node's INPUT DATA back. A trigger input's held frame is transport state,
    // not scheduler state — no anchor carries it, and /a's recorded frame is on
    // a graph-PRODUCED topic, which a replay re-creates by re-executing its
    // producer rather than by injecting (and that producer does not fire again
    // in this suffix). So the restored node fires and its generated body then
    // collapses on the unserved input (a body waits rather than
    // fabricating a value), publishing nothing.
    //
    // That is strictly closer to the recording than not firing at all — one
    // divergence class instead of two, and the remaining one names the real
    // cause — but it is NOT a clean resume, and this arm asserts both halves so
    // nobody reads it as one. Serving that frame is the same missing capability
    // the backlog admission needs; see `resolve_backlog_admission`.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp3_reference();
    assert_cp3_reference_shape(&rec);
    let bag = write_cp3_bag(
        &dir,
        "cp3_sync.mcap",
        &rec,
        [(CP3_A_TOPIC.to_string(), 30_000_000u64)]
            .into_iter()
            .collect(),
    );

    let outcome = replay(&bag, cp3_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.trace_divergence.is_none(),
        "the restored alignment must reproduce the recorded fusion fire: {:?}",
        outcome.trace_divergence
    );
    assert_eq!(outcome.ticks_replayed, CP3_STEPS - CP3_FIRST_STEP as usize);
    // The residual, pinned: the fire happened, the frame did not.
    assert!(
        outcome
            .violations
            .iter()
            .any(|v| v.topic == CP3_FUSION_TOPIC
                && matches!(v.class, ViolationClass::MissingTopic)),
        "the fired node's body still has no /a data to publish from: {:?}",
        outcome.violations
    );
    assert!(
        outcome
            .violations
            .iter()
            .all(|v| v.topic == CP3_FUSION_TOPIC),
        "and nothing ELSE diverges — the two sources replay byte-exact: {:?}",
        outcome.violations
    );

    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.framework_nodes,
        vec![CP3_A.to_string(), CP3_B.to_string(), CP3_FUSION.to_string()],
        "every node's anchor carries a section"
    );
    assert_eq!(
        resume.period_baselines_from_state,
        vec![CP3_A.to_string(), CP3_B.to_string()],
        "only the two Period nodes state a deadline"
    );
}

#[test]
#[serial]
fn a_sync_alignment_the_recording_does_not_state_leaves_the_node_waiting() {
    // The ANTI-TAUTOLOGY twin, and the mutation oracle for the arm above: the
    // SAME bag with an EMPTY sync section. Nothing else differs — same frames,
    // same anchors, same deadlines — so the ONE thing that can change the
    // verdict is whether the alignment was restored.
    //
    // Without it the fusion node needs BOTH inputs again and /a never arrives,
    // so the recorded fire does not happen at all: a STRUCTURAL trace
    // divergence (exit 6) naming the node, on top of the same missing frame.
    // Dropping `restore_sync_input_timestamps` collapses the arm above onto
    // this one.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp3_reference();
    assert_cp3_reference_shape(&rec);
    let bag = write_cp3_bag(&dir, "cp3_nosync.mcap", &rec, BTreeMap::new());

    let outcome = replay(&bag, cp3_factories, None, None).expect("mid-run replay runs");
    let divergence = outcome
        .trace_divergence
        .as_ref()
        .expect("an un-restored alignment loses the recorded fire entirely");
    assert_eq!(
        divergence.recorded.as_ref().map(|f| f.node_id.as_str()),
        Some(CP3_FUSION),
        "and the divergence names the node whose alignment was not restored: {:?}",
        divergence
    );
    assert!(
        divergence.replayed.is_none(),
        "the replay produced no fire to put opposite it: {divergence:?}"
    );
    assert!(!outcome.passed);
}

// --- The backlog claim, checked against what the recording holds -----------

const CP4_EXT_TOPIC: &str = "/xr/ext/cam";

/// The `ext_graph_yaml` relay bag, resumed, with a framework section claiming
/// `pending` undrained arrivals on its ONE wired input and stating `service` as
/// that input's service-cursor table.
fn write_backlog_bag(
    dir: &tempfile::TempDir,
    name: &str,
    rec: &Recording,
    pending: u64,
    service: Option<BTreeMap<String, Option<u32>>>,
) -> std::path::PathBuf {
    let mid = make_mid_run(rec, CP_FIRST_STEP);
    let bag = dir.path().join(name);
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            CHECKPOINT_NODE_IDX,
            // The relay's own capture (its `addend`, unchanged for the length
            // of the run — see `relay_anchor_blob`), so applying the anchor is
            // a no-op on the replayed frames and these arms read only the
            // section's `pending_data_count`.
            &node_anchor_blob_with_framework(
                &ext_relay_state(),
                &NodeFrameworkState {
                    next_fire_ns: None,
                    pending_data_count: pending,
                    sync_input_timestamps: BTreeMap::new(),
                    input_service: service.clone(),
                },
            ),
        ),
        Some(&coverage_naming(
            "relay",
            cerulion_bagd::STATE_COVERAGE_VERSION,
            1,
            Some(CHECKPOINT_NODE_IDX),
        )),
        None,
    );
    bag
}

/// The relay reference run, plus how many of its external frames the recording
/// holds at or before the resume clock — the denominator the backlog
/// shortfall gate compares a claim against.
fn backlog_reference() -> (Recording, u32) {
    let per_step: Vec<f64> = (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect();
    let rec = record_uniform(
        ext_graph_yaml(),
        ext_relay_factories,
        &[ExternalDrive::singles(CP4_EXT_TOPIC, per_step)],
        CP_STEPS,
    );
    let anchor_clock = rec
        .trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("boundary for the resume step");
    let available = rec.messages[CP4_EXT_TOPIC]
        .iter()
        .filter(|f| {
            WireHeader::read_from_buf(f)
                .expect("frame parses")
                .timestamp_ns
                <= anchor_clock
        })
        .count();
    // Derived from the recording rather than hardcoded, so a change to the
    // reference run cannot silently make the arms below vacuous.
    assert!(
        available >= 2,
        "the fixture must hold enough pre-anchor input frames to cover a claim"
    );
    (rec, available as u32)
}

// --- The mid-run resume SERVICE CURSOR cap -----------------------

/// The gating-clock value `resolve_resume` anchors at — `target(CP_FIRST_STEP)`,
/// the first boundary the head-step gate admitted.
fn cp_anchor_clock(rec: &Recording) -> u64 {
    rec.trace
        .iter()
        .find(|r| r.record_type == RECORD_TYPE_STEP_BOUNDARY && r.step == CP_FIRST_STEP)
        .map(|r| r.fire_time_ns)
        .expect("boundary for the resume step")
}

/// The LEADING pre-anchor band of `topic`, as wire `sequence`s — the walk the
/// engine performs, written out by hand here so every assertion below is
/// against a number derived from the RECORDING rather than one read back off
/// the code under test.
fn pre_anchor_sequences(rec: &Recording, topic: &str, anchor_clock: u64) -> Vec<u32> {
    let mut out = Vec::new();
    for frame in &rec.messages[topic] {
        let Some(header) = WireHeader::read_from_buf(frame) else {
            break;
        };
        if header.timestamp_ns >= anchor_clock {
            break;
        }
        out.push(header.sequence);
    }
    out
}

/// The TRUTHFUL service cursor for an `ext_graph_yaml`-shaped relay: the wire
/// `sequence` of the last external frame the RECORDED run actually READ before
/// the anchor.
///
/// DERIVED from the recording's own two channels rather than hardcoded, and
/// that is what keeps these arms correct as the read discipline moves: the relay
/// publishes `inp.x + 100`, so the LAST pre-anchor output names the input value
/// it read, and the external channel names that value's sequence. A fixture
/// that hardcoded "the relay had read 3 frames" would silently become a lie the
/// moment a step served a different number of frames.
fn relay_service_cursor(
    rec: &Recording,
    ext_topic: &str,
    out_topic: &str,
    anchor_clock: u64,
) -> u32 {
    let last_read_value = rec.messages[out_topic]
        .iter()
        .filter(|f| {
            WireHeader::read_from_buf(f)
                .expect("a recorded output frame parses")
                .timestamp_ns
                < anchor_clock
        })
        .map(|f| frame_x(f) - 100.0)
        .next_back()
        .expect("the reference run fires at least once before the anchor");
    let (seq, _) = rec.messages[ext_topic]
        .iter()
        .filter_map(|f| WireHeader::read_from_buf(f).map(|h| (h.sequence, frame_x(f))))
        .find(|(_, x)| (*x - last_read_value).abs() < f64::EPSILON)
        .expect("the value the relay read is one of the recorded external frames");
    seq
}

/// A one-input service-cursor table, as the checkpoint anchor carries it.
fn service_table(input: &str, cursor: Option<u32>) -> Option<BTreeMap<String, Option<u32>>> {
    Some([(input.to_string(), cursor)].into_iter().collect())
}

#[test]
#[serial]
fn a_partially_read_pre_anchor_band_resumes_byte_exact_from_its_service_cursor() {
    // THE arm. `Injector::inject_up_to`'s window at the first replayed step is
    // `wire timestamp < anchor_clock_ns`, so that step injects the WHOLE
    // pre-anchor band the bag carries. Under per-message FIFO the resumed
    // consumer then walks that band from its OLDEST frame instead of collapsing
    // it into one newest-frame read, so every produced frame of the suffix
    // shifts and the whole replay reports a `ByteMismatch` the candidate did
    // not cause. The service cursor states where the recorded run's reading had
    // got to, so only the frames it had NOT read are re-injected.
    //
    // NOT a "parked backlog" fixture, deliberately: whether a burst is still
    // sitting in the queue at the anchor depends on how many frames one step
    // serves, which is exactly what is in flux. What the cap keys on is a
    // PARTIALLY READ band, and the plain one-frame-per-step drive produces one
    // deterministically under any such rule — the frame published between the
    // anchor step and the first replayed step is stamped below the anchor clock
    // (so it is in the band) and had not been read (so the cursor stops short of
    // it). Nothing here asserts how many frames a step serves.
    let dir = tempfile::tempdir().unwrap();
    let (rec, _) = backlog_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    let cursor = relay_service_cursor(&rec, CP4_EXT_TOPIC, "/xr/relay/out", anchor_clock);
    let already_read = band.iter().take_while(|s| **s <= cursor).count();

    // The fixture's own preconditions, so harness drift fails as a harness
    // failure rather than inverting the verdict.
    assert!(
        already_read > 0 && already_read < band.len(),
        "this arm needs a PARTIALLY read band — read {already_read} of {} \
         (sequences {band:?}, cursor {cursor})",
        band.len()
    );

    let bag = write_backlog_bag(
        &dir,
        "partial.mcap",
        &rec,
        0,
        service_table("inp", Some(cursor)),
    );
    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.passed,
        "a resume that stops re-injecting what the recording says was already \
         read must be byte-exact: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert!(
        outcome.trace_divergence.is_none(),
        "and it must mint no extra fire: {:?}",
        outcome.trace_divergence
    );

    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read,
        [(CP4_EXT_TOPIC.to_string(), already_read)]
            .into_iter()
            .collect::<BTreeMap<_, _>>(),
        "the cap is stated on the map, so a run that merely happened to pass \
         cannot satisfy this"
    );
    assert!(
        resume.service_cursor_notes.is_empty(),
        "a fully stated cursor needs no caveat: {:?}",
        resume.service_cursor_notes
    );
    assert!(
        !resume.skipped_prefix_frames.contains_key(CP4_EXT_TOPIC),
        "the EXTERNAL skip is a different fact and must not be reported as a \
         produced-topic prefix: {:?}",
        resume.skipped_prefix_frames
    );

    // The hand oracle, computed from the drive rather than read back off the
    // bag: `per_step[k] = k * 10 + 1` and the relay adds 100, so the frames the
    // replay must reproduce are the post-anchor steps' outputs.
    let replayed_window: Vec<f64> = rec.messages["/xr/relay/out"]
        .iter()
        .filter(|f| WireHeader::read_from_buf(f).expect("header").timestamp_ns >= anchor_clock)
        .map(|f| frame_x(f))
        .collect();
    assert_eq!(
        replayed_window,
        (CP_FIRST_STEP as usize..CP_STEPS)
            .map(|k| (k * 10 + 1) as f64 + 100.0)
            .collect::<Vec<_>>(),
        "hand oracle: ext + 100 for every step at or after the anchor clock"
    );
}

/// The relay reference run with NOTHING published before the first replayed
/// step, so its whole pre-anchor band had already been read at the anchor.
fn fully_read_reference() -> Recording {
    let per_step: Vec<Vec<f64>> = (0..CP_STEPS)
        .map(|k| {
            if k as u64 == CP_FIRST_STEP {
                Vec::new()
            } else {
                vec![(k * 10 + 1) as f64]
            }
        })
        .collect();
    record_uniform(
        ext_graph_yaml(),
        ext_relay_factories,
        &[ExternalDrive {
            topic: CP4_EXT_TOPIC.to_string(),
            per_step,
        }],
        CP_STEPS,
    )
}

#[test]
#[serial]
fn a_fully_read_pre_anchor_band_admits_no_frames_and_mints_no_extra_fire() {
    // The "no frames admitted" case. The recorded run
    // published nothing between the anchor step and the first replayed one, so
    // every frame below the anchor clock had been read and the first replayed
    // step must inject NOTHING — injecting the whole band would fire the
    // relay on a step the recording holds no fire for.
    //
    // Two properties, and both matter: the skip covers the WHOLE band (the
    // arithmetic), and the replay is byte-exact with no structural trace
    // divergence (the extra fire the band would otherwise mint).
    let dir = tempfile::tempdir().unwrap();
    let rec = fully_read_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    let cursor = relay_service_cursor(&rec, CP4_EXT_TOPIC, "/xr/relay/out", anchor_clock);
    let already_read = band.iter().take_while(|s| **s <= cursor).count();
    assert!(
        !band.is_empty() && already_read == band.len(),
        "this arm needs a FULLY read band — read {already_read} of {} \
         (sequences {band:?}, cursor {cursor})",
        band.len()
    );

    let bag = write_backlog_bag(
        &dir,
        "drained.mcap",
        &rec,
        0,
        service_table("inp", Some(cursor)),
    );
    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.passed,
        "a fully drained input must admit nothing and still replay byte-exact: \
         {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert!(
        outcome.trace_divergence.is_none(),
        "an admitted band would mint a fire on a step the recording holds none \
         for: {:?}",
        outcome.trace_divergence
    );
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read,
        [(CP4_EXT_TOPIC.to_string(), band.len())]
            .into_iter()
            .collect::<BTreeMap<_, _>>(),
        "the whole band is skipped"
    );
}

/// A reference run whose ENTIRE pre-anchor band is ONE burst — four frames
/// published back to back before step 1, so they share a wire timestamp and
/// differ only in `sequence`.
fn one_timestamp_burst_reference() -> Recording {
    let mut per_step: Vec<Vec<f64>> = vec![Vec::new(); CP_STEPS];
    per_step[1] = vec![1.0, 2.0, 3.0, 4.0];
    per_step[CP_STEPS - 2] = vec![41.0];
    per_step[CP_STEPS - 1] = vec![51.0];
    record_uniform(
        ext_graph_yaml(),
        ext_relay_factories,
        &[ExternalDrive {
            topic: CP4_EXT_TOPIC.to_string(),
            per_step,
        }],
        CP_STEPS,
    )
}

#[test]
#[serial]
fn a_burst_sharing_one_wire_timestamp_is_capped_by_sequence_not_by_time() {
    // Every frame of one burst is loaned at the SAME pre-step gating clock, so
    // a cap keyed on the last served TIMESTAMP cannot split a burst: it skips
    // the whole thing or none of it. Only a `sequence` can name a frame inside
    // one. That is why the cursor is a frame IDENTITY.
    //
    // The cursor here is HAND-STAMPED to the burst's second frame rather than
    // derived, because the number this arm pins is the WALK's, not the
    // recording's: how many frames one step happens to serve is exactly what
    // must not be baked in. So it asserts the SKIP and says nothing about the
    // verdict — an over- or under-claiming cursor is a fixture parameter, and
    // asserting `passed` on top of one would pin how the reference run read the
    // burst.
    let dir = tempfile::tempdir().unwrap();
    let rec = one_timestamp_burst_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    assert_eq!(
        band.len(),
        4,
        "the whole pre-anchor band is the burst: {band:?}"
    );
    let stamps: std::collections::BTreeSet<u64> = rec.messages[CP4_EXT_TOPIC]
        .iter()
        .take(4)
        .map(|f| WireHeader::read_from_buf(f).expect("header").timestamp_ns)
        .collect();
    assert_eq!(
        stamps.len(),
        1,
        "the burst must share ONE wire timestamp, or this arm cannot tell a \
         sequence-keyed cap from a time-keyed one: {stamps:?}"
    );

    let bag = write_backlog_bag(
        &dir,
        "burst.mcap",
        &rec,
        0,
        service_table("inp", Some(band[1])),
    );
    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CP4_EXT_TOPIC),
        Some(&2usize),
        "a cursor at the burst's SECOND frame skips exactly two — a time-keyed \
         cap would skip 0 or 4: {:?}",
        resume.pre_anchor_frames_already_read
    );

    // THE INJECTION ORACLE. The assertion above reads the REPORT, and a
    // resolver that computes the skip, reports it, and then hands the injector
    // the whole band satisfies it exactly — a report-only arm cannot see
    // that class (a variant using `insert` instead of `max` survives a
    // report-only arm).
    //
    // The relay forwards one output per input it is served, so the REPLAYED
    // frame count on its output topic counts the band frames the injector
    // really served. The recording carries 2 post-anchor outputs; a skip of 2
    // re-serves the burst's surviving half, so the replay produces 2 + 2 = 4.
    // A skip that is reported and NOT applied re-serves all four and produces
    // 6. MEASURED: `ExtraMessages { recorded: 2, replayed: 4 }`.
    //
    // This says nothing about how the reference run read the burst — the
    // arithmetic is the CAP's, which is what the hand-stamped cursor makes it
    // safe to assert.
    let extra = outcome
        .violations
        .iter()
        .find_map(|v| match v.class {
            ViolationClass::ExtraMessages { recorded, replayed } if v.topic == "/xr/relay/out" => {
                Some((recorded, replayed))
            }
            _ => None,
        })
        .expect("re-serving the burst's surviving half must show as extra output frames");
    assert_eq!(
        extra,
        (2, 4),
        "the injector must serve exactly the POST-cursor suffix: the recording's \
         2 post-anchor outputs plus the 2 band frames the cap left — a skip that \
         is reported and not applied re-serves all four and produces 6"
    );

    // And the complement, on the SAME fixture: a cursor at the burst's LAST
    // frame skips the WHOLE band, so nothing is re-served and the replay
    // matches the recording exactly. Without it, "the suffix is served" is
    // satisfied by an injector that always serves the whole band (which is what
    // the first leg's 4 would then be), and the pair brackets the cap on both
    // sides with one fixture.
    let all_bag = write_backlog_bag(
        &dir,
        "burst_all.mcap",
        &rec,
        0,
        service_table("inp", Some(band[3])),
    );
    let all = replay(&all_bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    let all_resume = all.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        all_resume.pre_anchor_frames_already_read.get(CP4_EXT_TOPIC),
        Some(&4usize),
        "a cursor at the burst's LAST frame skips the whole band: {:?}",
        all_resume.pre_anchor_frames_already_read
    );
    assert!(
        all.passed && all.violations.is_empty(),
        "and with nothing re-served the replay matches the recording: {:?}",
        all.violations
    );
}

/// A reference run whose pre-anchor burst OVERFLOWS the consumer's queue, so
/// the recorded run itself EVICTED the oldest frames (`drop_oldest`) — the
/// depth-plus-two shape, which evicts under any fires-per-step drain model
/// (the overflow happens at PUBLISH time, before any drain can run).
/// The consumer is RATE-CAPPED, and that is what leaves a queued SUFFIX for the
/// arm to be about.
///
/// The burst drain fires a `Data` node once per queued frame WITHIN the
/// step, up to `DATA_PENDING_CARRY_CLAMP` (64), so an undeferred relay handed a
/// depth+2 burst serves every frame its queue retained in that one step — the
/// cursor then covers the WHOLE band, nothing is left to re-inject, and the
/// arm's "still leave live's queued suffix" premise is false. (MEASURED: skip
/// 12 of a 12-frame band. A suffix exists only when the
/// scheduler serves one frame per step and carries the rest, which the burst
/// drain does not do.)
///
/// [`ThrottledRelayNode`] restores it by declaration rather than by luck: one
/// fire per step, so the recorded run genuinely still had frames queued at the
/// anchor. The EVICTION is untouched by the choice — it happens at PUBLISH
/// time, when the depth+2 burst overflows the depth-`DEFAULT_CONSUMER_DEPTH`
/// queue, before any drain model can matter.
fn eviction_reference() -> Recording {
    let depth = cerulion_core::graph::topology::DEFAULT_CONSUMER_DEPTH;
    let mut per_step: Vec<Vec<f64>> = vec![Vec::new(); CP_STEPS];
    per_step[1] = (1..=depth as u64 + 2).map(|v| v as f64).collect();
    record_uniform(
        throttled_graph_yaml(),
        throttled_relay_factories,
        &[ExternalDrive {
            topic: CP4_EXT_TOPIC.to_string(),
            per_step,
        }],
        CP_STEPS,
    )
}

#[test]
#[serial]
fn an_evicting_burst_resumes_byte_exact_and_the_skip_covers_the_evicted_frames() {
    // Why the leading-run walk is EXACT under `drop_oldest`.
    // The recorded run's queue evicted its oldest frames, which were never
    // SERVED, yet they sit at the FRONT of the recorded band with sequences
    // below the cursor: the leading-run walk skips them along with the served
    // ones, and that is correct, because the resumed consumer must read
    // exactly what the live one still had queued. A walk that skipped only
    // "frames the tick read" would re-inject the evicted head and shift every
    // suffix read.
    //
    // Everything is DERIVED from the recording (cursor from the last
    // pre-anchor output, served count from the output channel), so the arm
    // holds under any fires-per-step drain model; the burst is depth + 2, so
    // the eviction itself is model-independent too (it happens at publish
    // time). The one assertion that makes this the EVICTION arm and not a
    // restatement of the partial-read one: the skip is STRICTLY LARGER than
    // the number of frames the tick served.
    let dir = tempfile::tempdir().unwrap();
    let rec = eviction_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    let depth = cerulion_core::graph::topology::DEFAULT_CONSUMER_DEPTH;
    assert_eq!(
        band.len(),
        depth + 2,
        "the whole burst is in the band: {band:?}"
    );

    // The recorded run really evicted the two oldest frames: no output ever
    // carries their values (ext + 100). A depth other than the declared
    // constant would fail here as a harness failure, not a silent pass.
    let outputs: Vec<f64> = rec.messages["/xr/relay/out"]
        .iter()
        .map(|f| frame_x(f))
        .collect();
    for evicted in [101.0, 102.0] {
        assert!(
            !outputs.contains(&evicted),
            "the fixture must really evict its two oldest frames; outputs {outputs:?}"
        );
    }

    let cursor = relay_service_cursor(&rec, CP4_EXT_TOPIC, "/xr/relay/out", anchor_clock);
    let skip = band.iter().take_while(|s| **s <= cursor).count();
    let served_pre_anchor = rec.messages["/xr/relay/out"]
        .iter()
        .filter(|f| {
            WireHeader::read_from_buf(f)
                .expect("output parses")
                .timestamp_ns
                < anchor_clock
        })
        .count();
    assert!(
        served_pre_anchor < skip,
        "the eviction discriminator: the skip ({skip}) must cover MORE than \
         the {served_pre_anchor} frames the tick served — the difference is \
         the evicted head"
    );
    assert!(
        skip < band.len(),
        "and still leave live's queued suffix to re-inject: {skip} of {}",
        band.len()
    );

    let bag = write_throttled_backlog_bag(
        &dir,
        "eviction.mcap",
        &rec,
        0,
        service_table("inp", Some(cursor)),
    );
    let outcome = replay(&bag, throttled_relay_factories, None, None).expect("mid-run replay runs");
    assert!(
        outcome.passed,
        "admitted survivors == live's queue at the anchor, so the resumed \
         suffix is byte-exact: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
    assert!(outcome.trace_divergence.is_none());
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CP4_EXT_TOPIC),
        Some(&skip),
        "the stated cap covers served + evicted-below-cursor: {:?}",
        resume.pre_anchor_frames_already_read
    );
}

#[test]
#[serial]
fn a_pre_anchor_band_walk_stops_at_a_frame_with_no_parseable_header() {
    // A headerless frame names no sequence and no timestamp, and
    // `Injector::inject_up_to` serves it UNCONDITIONALLY so it cannot be
    // stranded. So the band walk stops there: nothing past it may be skipped,
    // whatever the cursor says.
    //
    // The cursor is set ABOVE the whole band on purpose — a working sequence
    // gate would then skip everything — so the only thing that can produce a
    // short answer is the headerless stop. That is the discriminator the
    // sibling burst arm cannot provide.
    let dir = tempfile::tempdir().unwrap();
    let (mut rec, _) = backlog_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    assert!(
        band.len() > 2,
        "the band must extend past the junk frame: {band:?}"
    );
    rec.messages
        .get_mut(CP4_EXT_TOPIC)
        .expect("the driven run recorded the input channel")
        .insert(2, vec![0xAA, 0xBB, 0xCC]);

    let bag = write_backlog_bag(
        &dir,
        "headerless.mcap",
        &rec,
        0,
        service_table("inp", Some(u32::MAX)),
    );
    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CP4_EXT_TOPIC),
        Some(&2usize),
        "the walk stops at the unparseable frame even though the cursor covers \
         every frame behind it: {:?}",
        resume.pre_anchor_frames_already_read
    );
    assert!(
        resume
            .service_cursor_notes
            .get(CP4_EXT_TOPIC)
            .is_some_and(|n| n.contains("no parseable wire header")),
        "and it SAYS the band it placed is a floor: {:?}",
        resume.service_cursor_notes
    );
}

#[test]
#[serial]
fn a_frame_stamped_on_the_anchor_clock_is_outside_the_band_whatever_the_cursor_says() {
    // The band's clock boundary is `>=`, never `>`, and it is load-bearing in
    // the conservative direction: the first replayed step's injection window
    // is strictly `< anchor_clock_ns`, so a frame stamped EXACTLY on the
    // anchor clock is served by a LATER step — it is a POST-anchor frame, and
    // the cap must not be able to swallow it no matter what the cursor
    // claims. `restamp_frame` builds the tie the same way the produced-side
    // tie arms do.
    //
    // The cursor is hand-stamped ABOVE the on-clock frame's sequence — a
    // fixture parameter, like the burst arm's — because a derived cursor can
    // never cover a frame the pre-anchor run had not read; only an
    // over-claiming one makes the boundary observable in the map. So this arm
    // asserts the SKIP and says nothing about the verdict.
    let dir = tempfile::tempdir().unwrap();
    let (mut rec, _) = backlog_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let band_before = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    assert_eq!(
        band_before.len(),
        4,
        "the fixture's full band: {band_before:?}"
    );
    restamp_frame(&mut rec, CP4_EXT_TOPIC, 3, anchor_clock);
    let band = pre_anchor_sequences(&rec, CP4_EXT_TOPIC, anchor_clock);
    assert_eq!(
        band.len(),
        3,
        "the restamped frame must leave the band: {band:?}"
    );

    let bag = write_backlog_bag(
        &dir,
        "on_clock.mcap",
        &rec,
        0,
        service_table("inp", Some(band_before[3])),
    );
    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CP4_EXT_TOPIC),
        Some(&3usize),
        "the cap stops at the anchor clock even though the cursor covers the \
         on-clock frame — a `>`-boundary walk would skip 4: {:?}",
        resume.pre_anchor_frames_already_read
    );
}

#[test]
#[serial]
fn a_pre_cursor_bag_keeps_its_whole_band_and_names_the_resume_as_the_cause() {
    // A recording that states no
    // service cursor — every pre-cursor anchor — replays on
    // EXACTLY the shipped behaviour: the whole pre-anchor band is re-injected
    // and the resumed consumer re-processes it.
    //
    // It is a degrade and not a refusal, deliberately, and not
    // "no claim ⇒ admit zero" either. Refusing would remove replay capability
    // from every bag whose recorder stated no claim; admitting zero would STARVE
    // the first replayed step of the input the recorded run really did drain
    // there, which surfaces as missing frames blamed on the user's code — the
    // exact misattribution the injection scoping exists to prevent. So the
    // frames are served, and the report says the divergence is the RESUME's.
    let dir = tempfile::tempdir().unwrap();
    let (rec, _) = backlog_reference();
    let bag = write_backlog_bag(&dir, "no_cursor.mcap", &rec, 0, None);

    let outcome = replay(&bag, ext_relay_factories, None, None).expect("mid-run replay runs");
    assert!(
        !outcome.passed,
        "a bag that states nothing still re-processes its band, and the verdict \
         must state the divergence rather than absorb it"
    );
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert!(
        resume.pre_anchor_frames_already_read.is_empty(),
        "nothing may be capped on a claim the recording never made: {:?}",
        resume.pre_anchor_frames_already_read
    );
    let note = resume
        .service_cursor_notes
        .get(CP4_EXT_TOPIC)
        .expect("the uncapped band is named");
    assert!(
        note.contains("states nothing") && note.contains("RESUME artifact"),
        "the note must name the resume, not the candidate: {note}"
    );
    assert!(
        note.contains("relay") && note.contains("inp"),
        "and name the consumer and input it could not place: {note}"
    );
}

#[test]
#[serial]
#[tracing_test::traced_test]
fn an_anchor_that_owed_fires_is_reported_as_a_resume_artifact_not_applied() {
    // `pending_data_count` is decided-but-unrun fires. Nothing restores them —
    // the scheduler exposes no setter, and Principle #7 forbids adding one (the
    // fire sequence derives from queue content, and a seeded counter is a
    // second source of fires with no frame behind it). Nor can it be
    // reproduced: the DEFER that produced the count is not restored either, so
    // a resumed node is not re-deferred.
    //
    // So it is neither applied nor refused — it is REPORTED, and said out loud,
    // because it is the one piece of evidence in the bag that the first
    // replayed fires may differ for a reason the replayed code did not cause.
    //
    // # The claim is HARVESTED, not invented, and that is what makes this arm
    //   able to assert a verdict at all
    //
    // Stamping a hand-picked `3` onto a reference run driven one frame per step
    // would not do. MEASURED, that run's true count is ZERO at
    // every boundary — an undeferred `Data` node fires `min(pending, CLAMP)` and
    // subtracts it, so the arithmetic leaves no remainder — so such a bag describes
    // a state the run was never in, and the arm could make no claim about
    // `outcome.passed` because there is no telling
    // what a replay of a fabricated state should do.
    //
    // Here the count comes off the run's own `NodeHandle::pending_data_count`,
    // the SAME observable production reads at the SAME instant (the end-of-step
    // anchor point), so the bag states what really happened — and the verdict
    // becomes assertable: the frames the recorded run had parked were never
    // SERVED, so the cursor does not cover them, so they are re-injected and the
    // resumed relay walks the identical band and republishes the identical
    // bytes. MEASURED: `passed`, zero violations, no trace divergence.
    //
    // # Why the SEPARATE drain discipline
    //
    // A non-zero count needs a MID-BURST DEFER (see [`ThrottledRelayNode`]), and
    // on the Unified default a deferred refill takes the `refilled_unfired`
    // branch — it sets `data_backlog_hint` and leaves the count at zero, which
    // is exactly why a pending-keyed cap cannot work and the cap is a service
    // cursor. Separate signals one arrival per popped frame, so a throttle's
    // giveback puts a real remainder back. Both are shipping disciplines; this
    // arm needs the one where the state under test EXISTS, and it drives the
    // recording AND the replay through the same one, because a bag recorded
    // under one discipline and replayed under the other compares two runs.
    let _discipline = DrainDisciplineGuard::separate();
    let dir = tempfile::tempdir().unwrap();
    let rec = throttled_backlog_reference();
    let pending = rec.pending_after["relay"][(CP_FIRST_STEP - 1) as usize];
    assert!(
        pending > 0,
        "the fixture must PARK a backlog, or this arm tests the reporting of a \
         state the run was never in: {:?}",
        rec.pending_after
    );
    let anchor_clock = cp_anchor_clock(&rec);
    let cursor = relay_service_cursor(&rec, CP4_EXT_TOPIC, "/xr/relay/out", anchor_clock);
    let bag = write_throttled_backlog_bag(
        &dir,
        "pending.mcap",
        &rec,
        pending,
        service_table("inp", Some(cursor)),
    );

    let outcome = replay(&bag, throttled_relay_factories, None, None).expect("mid-run replay runs");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.anchor_pending_fires,
        [("relay".to_string(), pending)]
            .into_iter()
            .collect::<BTreeMap<_, _>>(),
        "the owed fires are reported per node, at the count the run really \
         parked: {:?}",
        resume.anchor_pending_fires
    );
    assert!(
        logs_contain("decided-but-unrun"),
        "and said out loud BEFORE the verdict, so an operator reading a \
         divergence knows the resume could not reproduce this node's deferral"
    );
    // The RESTORED claim. It is not decoration: it says the count is REPORTED
    // and not APPLIED — an implementation that seeded `pending_data_count` from
    // the anchor would fire the resumed node for frames that are also
    // re-injected, and this would fail on the doubled output.
    assert!(
        outcome.passed,
        "a truthful anchor resumes clean — the parked frames were never served, \
         so they are re-injected and re-walked: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
}

#[test]
#[serial]
fn a_backlog_the_recording_cannot_cover_refuses_with_both_counts() {
    // The backlog shortfall gate: the anchor says the
    // consumer was holding more frames than the recording carries before it,
    // so nothing a replay does can put it back in the state it was captured
    // in. Refused by name rather than replayed to a confident wrong verdict.
    let dir = tempfile::tempdir().unwrap();
    let (rec, available) = backlog_reference();
    let claim = u64::from(available) + 1;
    let bag = write_backlog_bag(&dir, "cp4_short.mcap", &rec, claim, None);

    let err = replay(&bag, ext_relay_factories, None, None).expect_err("uncoverable backlog");
    let text = err.to_string();
    assert!(text.contains(CP4_EXT_TOPIC), "names the topic: {text}");
    assert!(
        text.contains(&claim.to_string()) && text.contains(&available.to_string()),
        "names BOTH counts, so an operator can see the size of the gap: {text}"
    );
    assert_eq!(
        err.exit_code(),
        2,
        "a recording that cannot cover its own claim is not replay-grade"
    );
}

/// A stateless two-input bounded-sync consumer: its output is a function of
/// its inputs alone, so a resumed replay reproduces it with nothing restored.
///
/// The unattributable-claim arm needs a consumer with SEVERAL wired inputs
/// whose FIRST one is INJECTED — a multi-input node whose first input happens
/// to be graph-produced is dropped for a different reason and cannot tell an
/// implementation that withholds from one that guesses. (Measured: with
/// `cp3`'s fusion, whose first input IS produced,
/// an implementation that just guesses the first input passes the whole binary.)
#[cerulion_node(sync_window_ms = 50)]
#[derive(Default)]
struct SumFusionNode {
    #[input(trigger)]
    a: Vector3,
    #[input(trigger)]
    b: Vector3,
    #[output]
    out: Vector3,
}

#[cerulion_node_impl]
impl SumFusionNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.out.x = self.a.x + self.b.x;
        Ok(())
    }
}

const CP5_NODE: &str = "fusion";
const CP5_A_TOPIC: &str = "/x5/ext/a";
const CP5_B_TOPIC: &str = "/x5/ext/b";
const CP5_FUSION_TOPIC: &str = "/x5/fusion/out";

fn cp5_yaml() -> &'static str {
    "name: cp5\nprefix: x5\nnodes:\n\
     \x20 - id: fusion\n    type: sum_fusion\n    inputs:\n      - name: a\n        source: /x5/ext/a\n      - name: b\n        source: /x5/ext/b\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn cp5_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![(
        CP5_NODE,
        Box::new(SumFusionNodeEntry::new()) as Box<dyn NodeEntry>,
    )])
}

fn cp5_reference() -> Recording {
    record_uniform(
        cp5_yaml(),
        cp5_factories,
        &[
            ExternalDrive::singles(
                CP5_A_TOPIC,
                (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect(),
            ),
            ExternalDrive::singles(
                CP5_B_TOPIC,
                (0..CP_STEPS).map(|k| (k * 100 + 7) as f64).collect(),
            ),
        ],
        CP_STEPS,
    )
}

/// The TRUTHFUL service-cursor table for `cp5`'s Sync fusion node: per TRIGGER
/// input, the wire `sequence` of the last frame the RECORDED run's tick read
/// before the anchor.
///
/// A Sync trigger input is per-message FIFO, so its node states this
/// table exactly as a data-trigger consumer does — [`relay_service_cursor`] is
/// the one-input twin, and `state_anchor_boundary_iox2_test::
/// a_per_set_sync_nodes_anchor_states_a_cursor_for_every_trigger_input` is the
/// production pin that a real anchor really carries it.
///
/// DERIVED from the recording rather than hardcoded, on the same reasoning as
/// the relay twin: the fusion node publishes `a.x + b.x`, so the LAST pre-anchor
/// OUTPUT names the SET it read, and the two external channels name that set's
/// members. A fixture that hardcoded "it had read three sets" would silently
/// become a lie the moment a step served a different number of them.
fn cp5_service_cursors(rec: &Recording, anchor_clock: u64) -> BTreeMap<String, Option<u32>> {
    let last_read_sum = rec.messages[CP5_FUSION_TOPIC]
        .iter()
        .filter(|f| {
            WireHeader::read_from_buf(f)
                .expect("a recorded output frame parses")
                .timestamp_ns
                < anchor_clock
        })
        .map(|f| frame_x(f))
        .next_back()
        .expect("the reference run fires at least once before the anchor");
    // Both channels are driven one frame per step, so a SET is one frame from
    // each at the same index — the pair whose values sum to what the tick
    // published.
    let members = |topic: &str| -> Vec<(u32, f64)> {
        rec.messages[topic]
            .iter()
            .filter_map(|f| WireHeader::read_from_buf(f).map(|h| (h.sequence, frame_x(f))))
            .collect()
    };
    let (a, b) = (members(CP5_A_TOPIC), members(CP5_B_TOPIC));
    let idx = (0..a.len().min(b.len()))
        .find(|i| ((a[*i].1 + b[*i].1) - last_read_sum).abs() < f64::EPSILON)
        .expect("the set the fusion node read is one of the recorded pairs");
    [
        ("a".to_string(), Some(a[idx].0)),
        ("b".to_string(), Some(b[idx].0)),
    ]
    .into_iter()
    .collect()
}

#[test]
#[serial]
fn a_backlog_a_recording_cannot_attribute_to_one_topic_is_withheld() {
    // `pending_data_count` is ONE counter per node and a claim is per TOPIC.
    // For a consumer with several wired inputs the count is a SUM over
    // unrelated queues that no recorded fact splits — so it is withheld, the
    // same answer `seed_publisher_sequence` gives a multi-publisher topic,
    // rather than guessed onto one of them.
    //
    // BOTH of this node's inputs are INJECTED and both are recorded, so an
    // implementation that guessed the first would produce a real admission —
    // and with a count no recording could cover, a shortfall REFUSAL. The
    // correct answer is an empty admission and an otherwise untouched replay,
    // which is also the anti-tautology half: a withheld claim is not a refused
    // one, and it changes nothing else.
    //
    // The section states the two inputs' SERVICE CURSORS because
    // per-set delivery made them real (`cp5_service_cursors`), and the two claims are
    // independent by design: the cursor caps the pre-anchor INJECTION per
    // topic, `pending_data_count` claims a per-node BACKLOG, and this arm is
    // about the second being unattributable while the first is stated
    // perfectly well.
    let dir = tempfile::tempdir().unwrap();
    let rec = cp5_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let cursors = cp5_service_cursors(&rec, anchor_clock);
    // The fixture's own precondition, so harness drift fails as a harness
    // failure rather than inverting the verdict: the cursors must name a
    // PARTIALLY read band on each input, which is the only shape in which the
    // cap is doing anything at all.
    for (topic, input) in [(CP5_A_TOPIC, "a"), (CP5_B_TOPIC, "b")] {
        let band = pre_anchor_sequences(&rec, topic, anchor_clock);
        let cursor = cursors[input].expect("the recorded run served this input before the anchor");
        let already_read = band.iter().take_while(|s| **s <= cursor).count();
        assert!(
            already_read > 0 && already_read < band.len(),
            "'{topic}' must carry a PARTIALLY read pre-anchor band — read \
             {already_read} of {} (sequences {band:?}, cursor {cursor})",
            band.len()
        );
    }
    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("cp5_multi_input_claim.mcap");
    write_checkpoint_bag(
        &mid,
        &bag,
        &state_records(
            CHECKPOINT_RUN,
            CP_FIRST_STEP - 1,
            0,
            // `SumFusionNode` declares only ports, so its capture is EMPTY —
            // the one macro shape whose payload really is zero bytes. The shape
            // header is still its own, and still checked.
            &node_anchor_blob_with_framework(
                &SumFusionNode::default(),
                &NodeFrameworkState {
                    next_fire_ns: None,
                    // Far beyond anything either input's recording could cover:
                    // attributed to a topic, this refuses the whole replay.
                    pending_data_count: 9_999,
                    sync_input_timestamps: BTreeMap::new(),
                    // A per-set Sync node's trigger inputs ARE
                    // per-message FIFO, so a truthful section states a cursor
                    // for each of them — see `cp5_service_cursors`. An
                    // EMPTY table here would be wrong: under
                    // the service-cursor reader rules it is the positive claim "this node
                    // has no per-message FIFO input"; per-set delivery makes
                    // that claim false, and the engine acts on it exactly as
                    // written (`ConsumerKind::Latest` keeps the whole
                    // pre-anchor band, which the matcher then re-serves one
                    // fire per re-served SET).
                    input_service: Some(cursors),
                },
            ),
        ),
        Some(&coverage_naming(
            CP5_NODE,
            cerulion_bagd::STATE_COVERAGE_VERSION,
            1,
            Some(0),
        )),
        None,
    );

    let outcome =
        replay(&bag, cp5_factories, None, None).expect("the claim is withheld, not refused");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert!(
        resume.backlog_admission.is_empty(),
        "an unattributable count must produce no admission: {:?}",
        resume.backlog_admission
    );
    assert_eq!(
        resume.framework_nodes,
        vec![CP5_NODE.to_string()],
        "the section itself was still read"
    );
    assert!(
        outcome.passed,
        "and a withheld claim changes nothing else: {:?} / {:?}",
        outcome.violations, outcome.trace_divergence
    );
}

#[test]
#[serial]
fn a_backlog_on_a_topic_the_recording_never_captured_is_refused_not_dropped() {
    // The shortfall gate's sharpest case, and the one an early cut of this
    // work SKIPPED as "nothing to admit": the recording says a consumer was
    // holding frames on a topic it captured NONE of.
    //
    // That is not an exemption from the gate — it is the gate. No replay can
    // put that consumer back in the state it was captured in, and dropping the
    // claim turns a refusal into a silent pass. Measured: re-adding the skip
    // passes every other arm in this binary.
    //
    // The fixture is a REAL recorder shape: the run is driven normally, and the
    // recording carries the relay's OUTPUT channel but not its INPUT one — a
    // tap set that missed a topic. So the seed ladder is satisfied (the
    // produced topic has frames either side of the anchor) and the claimed
    // input topic scans to zero.
    let dir = tempfile::tempdir().unwrap();
    let (mut rec, _) = backlog_reference();
    rec.messages
        .shift_remove(CP4_EXT_TOPIC)
        .expect("the driven run recorded the input channel");
    let bag = write_backlog_bag(&dir, "cp4_unrecorded.mcap", &rec, 3, None);

    let err = replay(&bag, ext_relay_factories, None, None).expect_err("uncoverable backlog");
    let text = err.to_string();
    assert!(text.contains(CP4_EXT_TOPIC), "names the topic: {text}");
    assert!(
        text.contains(" 3 frame(s)") && text.contains(" 0 frame(s)"),
        "names the claim AND the zero the recording holds: {text}"
    );
    assert_eq!(err.exit_code(), 2);
}

// --- Topics the cap must NOT place, and topics two consumers share -

/// A data-trigger node with a NON-trigger latest-value CONTEXT input, so one
/// external topic can carry a per-message FIFO reader and a drain-to-latest one
/// at the same time — the ordinary "a camera feeds a detector and a monitor"
/// shape.
#[cerulion_node]
#[derive(Default)]
struct ContextRelayNode {
    #[input(trigger)]
    tick: Vector3,
    #[input]
    ctx: Vector3,
    #[output]
    out: Vector3,
}

#[cerulion_node_impl]
impl ContextRelayNode {
    fn tick(&mut self) -> Result<(), NodeError> {
        self.out.x = self.tick.x + self.ctx.x;
        Ok(())
    }
}

const CO_CAM: &str = "/xc/ext/cam";
const CO_TICK: &str = "/xc/ext/tick";

fn co_consumer_yaml() -> &'static str {
    "name: coc\nprefix: xc\nnodes:\n\
     \x20 - id: relay\n    type: relay_node\n    inputs:\n      - name: inp\n        source: /xc/ext/cam\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n\
     \x20 - id: watcher\n    type: context_relay_node\n    inputs:\n      - name: tick\n        source: /xc/ext/tick\n      - name: ctx\n        source: /xc/ext/cam\n    outputs:\n      - name: out\n        schema: geometry_msgs/Vector3\n"
}

fn co_consumer_factories() -> IndexMap<String, Box<dyn NodeEntry>> {
    factories(vec![
        (
            "relay",
            Box::new(RelayNodeEntry::with_state(ext_relay_state())) as Box<dyn NodeEntry>,
        ),
        (
            "watcher",
            Box::new(ContextRelayNodeEntry::new()) as Box<dyn NodeEntry>,
        ),
    ])
}

fn co_consumer_reference() -> Recording {
    record_uniform(
        co_consumer_yaml(),
        co_consumer_factories,
        &[
            ExternalDrive::singles(CO_CAM, (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect()),
            ExternalDrive::singles(
                CO_TICK,
                (0..CP_STEPS).map(|k| (k * 100 + 7) as f64).collect(),
            ),
        ],
        CP_STEPS,
    )
}

#[test]
#[serial]
fn a_drain_to_latest_co_consumer_keeps_its_topics_whole_band_and_the_cap_stays_per_input() {
    // TWO rules in one fixture, because they are the same rule seen from two
    // sides — the cursor belongs to an INPUT, not to a node or a topic.
    //
    // (a) `/xc/ext/cam` is read by `relay` as a per-message FIFO trigger AND by
    //     `watcher` as a latest-value CONTEXT input. There is ONE injection
    //     stream, and NOTHING else restores a latest-value input's held
    //     frame — no anchor carries one — so the re-injected band is how that
    //     reader gets a value at all. Skipping any of it would leave `watcher`
    //     with no delivery at the first resumed step and blame the candidate.
    //     So the band is kept whole and the report says why.
    //
    // (b) `watcher`'s own section states a cursor for `tick` and NOT for `ctx`,
    //     and that difference is honoured: `/xc/ext/tick` IS capped while
    //     `/xc/ext/cam` is not. A cap attributed per NODE, or applied to every
    //     topic a cursor-carrying node reads, fails here.
    let dir = tempfile::tempdir().unwrap();
    let rec = co_consumer_reference();
    let anchor_clock = cp_anchor_clock(&rec);
    let cam_band = pre_anchor_sequences(&rec, CO_CAM, anchor_clock);
    let tick_band = pre_anchor_sequences(&rec, CO_TICK, anchor_clock);
    assert!(
        cam_band.len() >= 3 && tick_band.len() >= 3,
        "both bands must be big enough to tell a cap from an absence: \
         {cam_band:?} / {tick_band:?}"
    );

    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("co_consumer.mcap");
    let mut records = state_records(
        CHECKPOINT_RUN,
        CP_FIRST_STEP - 1,
        0,
        &node_anchor_blob_with_framework(
            &ext_relay_state(),
            &NodeFrameworkState {
                input_service: service_table("inp", Some(cam_band[cam_band.len() - 2])),
                ..Default::default()
            },
        ),
    );
    records.extend(state_records(
        CHECKPOINT_RUN,
        CP_FIRST_STEP - 1,
        1,
        &node_anchor_blob_with_framework(
            &ContextRelayNode::default(),
            &NodeFrameworkState {
                // States a cursor for the TRIGGER input only. `ctx` is absent
                // from the table, which is the section's way of saying it is a
                // drain-to-latest read.
                input_service: service_table("tick", Some(tick_band[1])),
                ..Default::default()
            },
        ),
    ));
    write_checkpoint_bag(
        &mid,
        &bag,
        &records,
        Some(&coverage_for_nodes(&[("relay", 0), ("watcher", 1)])),
        None,
    );

    let outcome = replay(&bag, co_consumer_factories, None, None).expect("the mid-run bag replays");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CO_CAM),
        None,
        "a topic with a drain-to-latest co-consumer keeps its whole band: {:?}",
        resume.pre_anchor_frames_already_read
    );
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(CO_TICK),
        Some(&2usize),
        "while the same node's TRIGGER input is capped from its own cursor: {:?}",
        resume.pre_anchor_frames_already_read
    );
    let note = resume
        .service_cursor_notes
        .get(CO_CAM)
        .expect("the uncapped topic is named");
    assert!(
        note.contains("watcher") && note.contains("ctx") && note.contains("drain-to-latest"),
        "the note names the co-consumer that keeps the band: {note}"
    );
    assert!(
        !resume.service_cursor_notes.contains_key(CO_TICK),
        "and the capped topic needs no caveat: {:?}",
        resume.service_cursor_notes
    );
}

