#[test]
#[serial]
fn a_sync_co_consumer_keeps_its_topics_whole_band() {
    // The Sync twin of the arm above, scoped by per-set delivery the same way
    // the sibling arm
    // `a_backlog_a_recording_cannot_attribute_to_one_topic_is_withheld` is.
    //
    // What is NOT true: "a Sync node carries no service cursor". A per-set
    // Sync node's trigger inputs ARE per-message FIFO, they are minted a cursor
    // at the same wiring site as a data trigger's, and a REAL recording of this
    // graph states one per trigger input.
    //
    // What this arm drives, and what it is worth: a section that
    // states an EMPTY table — a positive claim of "no per-message FIFO input" —
    // and the engine's handling of it. The table is HAND-STAMPED below, so this
    // is a crafted claim rather than a recorded one, and the pin is that the
    // engine BELIEVES what the section says: it takes the drain-to-latest arm,
    // keeps the shared topic's whole band, and NAMES the node in the note. A bag
    // written before per-set delivery carries exactly this section, so the behaviour has
    // to keep working; a bag written by this binary does not carry it.
    let dir = tempfile::tempdir().unwrap();
    let rec = record_uniform(
        sync_co_consumer_yaml(),
        sync_co_consumer_factories,
        &[
            ExternalDrive::singles(SY_A, (0..CP_STEPS).map(|k| (k * 10 + 1) as f64).collect()),
            ExternalDrive::singles(SY_B, (0..CP_STEPS).map(|k| (k * 100 + 7) as f64).collect()),
        ],
        CP_STEPS,
    );
    let anchor_clock = cp_anchor_clock(&rec);
    let band = pre_anchor_sequences(&rec, SY_A, anchor_clock);
    assert!(
        band.len() >= 3,
        "the shared band must be big enough: {band:?}"
    );

    let mid = make_mid_run(&rec, CP_FIRST_STEP);
    let bag = dir.path().join("sync_co_consumer.mcap");
    let mut records = state_records(
        CHECKPOINT_RUN,
        CP_FIRST_STEP - 1,
        0,
        &node_anchor_blob_with_framework(
            &ext_relay_state(),
            &NodeFrameworkState {
                input_service: service_table("inp", Some(band[band.len() - 2])),
                ..Default::default()
            },
        ),
    );
    records.extend(state_records(
        CHECKPOINT_RUN,
        CP_FIRST_STEP - 1,
        1,
        &node_anchor_blob_with_framework(
            &SumFusionNode::default(),
            &NodeFrameworkState {
                // The crafted claim under test: an empty table, which is a
                // CLAIM ("no per-message FIFO input"), not an absent one, which
                // would be silence. A real per-set Sync recording
                // states a cursor per trigger input instead — see the
                // header — so this stands for an OLDER bag, whose sections
                // must keep decoding to the behaviour they described.
                input_service: Some(BTreeMap::new()),
                ..Default::default()
            },
        ),
    ));
    write_checkpoint_bag(
        &mid,
        &bag,
        &records,
        Some(&coverage_for_nodes(&[("relay", 0), ("fusion", 1)])),
        None,
    );

    let outcome =
        replay(&bag, sync_co_consumer_factories, None, None).expect("the mid-run bag replays");
    let resume = outcome.resume.expect("a mid-run bag reports its resume");
    assert_eq!(
        resume.pre_anchor_frames_already_read.get(SY_A),
        None,
        "a Sync co-consumer keeps the shared band: {:?}",
        resume.pre_anchor_frames_already_read
    );
    assert!(
        resume
            .service_cursor_notes
            .get(SY_A)
            .is_some_and(|n| n.contains("fusion") && n.contains("drain-to-latest")),
        "and the note names it: {:?}",
        resume.service_cursor_notes
    );
}

