    let dir = tempfile::tempdir().unwrap();
    let bag = dir.path().join("readlog_mp_clean.mcap");
    write_multi_rank_bag(
        &rec,
        |id| if id == "source" { 0 } else { 1 },
        2,
        MpLayout::RankBlocks,
        &bag,
    );
    let outcome = replay(&bag, source_relay_factories, None, None).expect("replay runs");
    assert_clean_verdict(&outcome, "two-rank read-log bag");
